function openPasteDeckModal() {
  document.getElementById('paste-deck-text').value = '';
  document.getElementById('paste-deck-modal').style.display = 'flex';
  studyDeckOpenDialog('paste-deck-modal', { focusSelector: '#paste-deck-text' });
}
function closePasteDeckModal() {
  document.getElementById('paste-deck-modal').style.display = 'none';
  studyDeckCloseDialog('paste-deck-modal');
}
function isValidCard(c) {
  return c && typeof c.q === 'string' && typeof c.a === 'string';
}

function importDeckFromPaste() {
  var raw = document.getElementById('paste-deck-text').value.trim();
  if (!raw) { alert('Please paste some deck code first.'); return; }
  var incoming = parseIncomingDeck(raw);
  if (!incoming || !Array.isArray(incoming.cards) || !incoming.cards.length) {
    alert('Could not find a valid deck in the pasted code.\nMake sure you copied the full export text.');
    return;
  }

  // Validate cards
  incoming.cards = incoming.cards.filter(isValidCard);

  if (!incoming.cards.length) {
    alert('No valid cards found in this deck.');
    return;
  }
  incoming = JSON.parse(JSON.stringify(incoming)); // deep clone
  var importedDeckId = incoming.id;
  incoming.id = nextNumericId();
  // Ensure all cards have UIDs
  var used = {}; decks.forEach(function(d){ d.cards.forEach(function(c){ if(c.uid) used[c.uid]=1; }); });
  incoming.cards.forEach(function(c){
    if (!c.uid || used[c.uid]) {
      var uid; do { uid = genUID(); } while (used[uid]);
      c.uid = uid;
    }
    used[c.uid] = 1;
  });
  var incomingIdToUid = {};
  incoming.cards.forEach(function(c){ if (c && c.id != null && c.uid) incomingIdToUid[String(c.id)] = c.uid; });
  repairCardLinksForImportedDeck(incoming, {
    importedDeckId: importedDeckId,
    incomingIdToUid: incomingIdToUid
  });
  decks.push(incoming);
  saveDataImmediatePersistent().then(function(){
    closePasteDeckModal();
    renderHome();
    renderDecks();
    showEditDeck(incoming.id);
    guidedShowSidecarCompatibilityToast(incoming, 'Deck imported and saved.');
  }).catch(function(){
    closePasteDeckModal();
    renderHome();
    renderDecks();
    showEditDeck(incoming.id);
    alert('Deck imported for this session, but StudyDeck could not save it. Export a backup before refreshing.');
  });
}

