function openExportTextModal(title, bodyHtml, text, downloadName, options) {
  options = options || {};
  var modal = document.getElementById('export-modal');
  var textEl = document.getElementById('export-text');
  var copyBtn = document.getElementById('export-copy-btn');
  var downloadLink = document.getElementById('export-download-link');
  var saveBtn = document.getElementById('export-save-file-btn');
  var bridgeBtn = document.getElementById('export-bridge-save-btn');
  var fileNameWrap = document.getElementById('export-filename-wrap');
  var fileNameInput = document.getElementById('export-filename-input');
  var titleEl = document.querySelector('#export-modal .export-sheet h3');
  var bodyEl = document.querySelector('#export-modal .export-sheet p');
  studyDeckCurrentExportText = text || '';
  studyDeckCurrentExportFileName = downloadName ? studyDeckSafeJsonFileName(downloadName) : '';
  studyDeckCurrentExportDescription = options.description || 'JSON file';
  studyDeckCurrentExportBridgeFolder = options.bridgeFolder || 'sidecars';
  if (titleEl) {
    if (titleEl._origHTML === undefined) titleEl._origHTML = titleEl.innerHTML;
    titleEl.innerHTML = title || titleEl._origHTML;
  }
  if (bodyEl && bodyHtml) {
    if (bodyEl._origHTML === undefined) bodyEl._origHTML = bodyEl.innerHTML;
    bodyEl.innerHTML = bodyHtml;
  }
  if (textEl) textEl.value = text || '';
  if (copyBtn) {
    copyBtn.textContent = 'Copy to clipboard';
    copyBtn.classList.remove('btn-gold');
    copyBtn.classList.add('btn-soft');
  }
  if (fileNameWrap) fileNameWrap.style.display = (downloadName && text) ? '' : 'none';
  if (fileNameInput) fileNameInput.value = studyDeckCurrentExportFileName || 'studydeck-export.json';
  if (studyDeckExportDownloadUrl) {
    URL.revokeObjectURL(studyDeckExportDownloadUrl);
    studyDeckExportDownloadUrl = '';
  }
  if (downloadLink) {
    if (downloadName && text) {
      var safeName = studyDeckGetCurrentExportFileName();
      var dataUrl = studyDeckBuildJsonDataUrl(text);
      if (dataUrl.length <= studyDeckExportDownloadDataUrlLimit) {
        downloadLink.href = dataUrl;
      } else {
        studyDeckExportDownloadUrl = URL.createObjectURL(new Blob([text], { type: 'application/json;charset=utf-8' }));
        downloadLink.href = studyDeckExportDownloadUrl;
      }
      downloadLink.onclick = studyDeckHandleExportDownloadClick;
      downloadLink.download = safeName;
      downloadLink.textContent = 'Download JSON file';
      downloadLink.style.display = '';
    } else {
      downloadLink.onclick = null;
      downloadLink.removeAttribute('href');
      downloadLink.style.display = 'none';
    }
  }
  if (saveBtn) {
    var canUseSavePicker = typeof window !== 'undefined'
      && typeof window.showSaveFilePicker === 'function'
      && window.location
      && window.location.protocol !== 'file:';
    saveBtn.style.display = (downloadName && text && canUseSavePicker) ? '' : 'none';
    saveBtn.textContent = 'Save JSON file';
  }
  if (bridgeBtn) {
    bridgeBtn.style.display = (downloadName && text) ? '' : 'none';
    bridgeBtn.disabled = false;
    bridgeBtn.textContent = 'Save via local bridge';
  }
  if (modal) {
    modal.style.display = 'flex';
    studyDeckOpenDialog(modal, { focusSelector: downloadName && text ? '#export-filename-input' : '#export-copy-btn' });
  }
}
function studyDeckBuildJsonDataUrl(text) {
  return 'data:application/json;charset=utf-8,' + encodeURIComponent(text || '');
}
function studyDeckGetCurrentExportFileName() {
  var input = document.getElementById('export-filename-input');
  var raw = input && input.value ? input.value : (studyDeckCurrentExportFileName || 'studydeck-export.json');
  var safeName = studyDeckSafeJsonFileName(raw);
  studyDeckCurrentExportFileName = safeName;
  return safeName;
}
function studyDeckUpdateExportFileNameFromInput() {
  var safeName = studyDeckGetCurrentExportFileName();
  var downloadLink = document.getElementById('export-download-link');
  if (downloadLink) downloadLink.download = safeName;
  return safeName;
}
function studyDeckHandleExportDownloadClick() {
  studyDeckUpdateExportFileNameFromInput();
  if (typeof showXpToast === 'function') {
    setTimeout(function(){
      showXpToast('JSON download requested. If the in-app browser blocks it, use Chrome/Safari or Copy to clipboard.');
    }, 250);
  }
  return true;
}
function studyDeckSafeJsonFileName(name) {
  var base = String(name || 'studydeck-export')
    .trim()
    .replace(/\.json$/i, '')
    .replace(/[^a-z0-9._-]+/gi, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 90) || 'studydeck-export';
  return base + '.json';
}
async function studyDeckWriteJsonWithSavePicker(json, filename, description) {
  if (typeof window === 'undefined' || typeof window.showSaveFilePicker !== 'function') {
    throw new Error('Native save picker is not available in this browser.');
  }
  if (typeof json !== 'string' || !json.trim()) {
    throw new Error('StudyDeck could not build a JSON payload to save.');
  }
  var safeName = studyDeckSafeJsonFileName(filename);
  var handle = await window.showSaveFilePicker({
    suggestedName: safeName,
    types: [{
      description: description || 'JSON file',
      accept: { 'application/json': ['.json'] }
    }]
  });
  var bytes = new TextEncoder().encode(json);
  var writable = await handle.createWritable();
  await writable.write({ type: 'write', position: 0, data: bytes });
  await writable.truncate(bytes.byteLength);
  await writable.close();
  if (handle && typeof handle.getFile === 'function') {
    var savedFile = await handle.getFile();
    var savedSize = Number(savedFile && savedFile.size || 0);
    if (savedSize < bytes.byteLength) {
      throw new Error('Save picker wrote ' + savedSize + ' bytes; expected ' + bytes.byteLength + '.');
    }
  }
  return true;
}
async function studyDeckSaveCurrentExportWithPicker() {
  var btn = document.getElementById('export-save-file-btn');
  var json = studyDeckCurrentExportText || (document.getElementById('export-text') || {}).value || '';
  var filename = studyDeckGetCurrentExportFileName();
  try {
    if (btn) {
      btn.disabled = true;
      btn.textContent = 'Saving...';
    }
    await studyDeckWriteJsonWithSavePicker(json, filename, studyDeckCurrentExportDescription || 'JSON file');
    if (btn) btn.textContent = 'Saved';
    if (typeof showXpToast === 'function') showXpToast('JSON file saved.');
    return true;
  } catch (err) {
    if (err && err.name === 'AbortError') {
      if (btn) btn.textContent = 'Save JSON file';
      return false;
    }
    console.warn('Native export save failed.', err);
    alert('StudyDeck could not save the JSON file through this browser. ' + (err && err.message ? err.message : '') + '\n\nUse Download JSON file in Chrome, or Copy to clipboard as a fallback.');
    if (btn) btn.textContent = 'Save failed';
    return false;
  } finally {
    if (btn) {
      setTimeout(function(){
        btn.disabled = false;
        btn.textContent = 'Save JSON file';
      }, 1200);
    }
  }
}
async function studyDeckSaveCurrentExportWithBridge() {
  var btn = document.getElementById('export-bridge-save-btn');
  var json = studyDeckCurrentExportText || (document.getElementById('export-text') || {}).value || '';
  var filename = studyDeckGetCurrentExportFileName();
  try {
    if (typeof json !== 'string' || !json.trim()) {
      throw new Error('StudyDeck could not build a JSON payload to save.');
    }
    JSON.parse(json);
    if (btn) {
      btn.disabled = true;
      btn.textContent = 'Saving...';
    }
    var healthResponse = await fetch(studyDeckAuthorBridgeBaseUrl + '/health');
    var health = await healthResponse.json();
    if (!healthResponse.ok || !health || !health.ok || !health.token) {
      throw new Error('The local bridge did not provide a valid save token.');
    }
    var response = await fetch(studyDeckAuthorBridgeBaseUrl + '/save-sidecar', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-StudyDeck-Bridge-Token': health.token
      },
      body: JSON.stringify({
        filename: filename,
        json: json,
        folder: studyDeckCurrentExportBridgeFolder || 'sidecars'
      })
    });
    var payload = null;
    try {
      payload = await response.json();
    } catch (parseErr) {
      payload = { error: 'The bridge returned a non-JSON response.' };
    }
    if (!response.ok || !payload || !payload.ok) {
      throw new Error(payload && payload.error ? payload.error : ('Bridge save failed with HTTP ' + response.status + '.'));
    }
    if (btn) btn.textContent = 'Saved';
    if (typeof showXpToast === 'function') showXpToast('JSON saved through local bridge.');
    alert('Saved JSON file through the local Author Bridge:\n\n' + payload.path + '\n\nBytes written: ' + payload.bytes);
    return true;
  } catch (err) {
    console.warn('Author Bridge export save failed.', err);
    alert(
      'StudyDeck could not save through the local Author Bridge. No file was written.' +
      (err && err.message ? '\n\nDetails: ' + err.message : '') +
      '\n\nStart the bridge by double-clicking:\n' + studyDeckAuthorBridgeStartScript +
      '\n\nOr run this Terminal command:\n' + studyDeckAuthorBridgeCommand +
      '\n\nChrome download and Copy to clipboard still work as fallbacks.'
    );
    if (btn) btn.textContent = 'Bridge unavailable';
    return false;
  } finally {
    if (btn) {
      setTimeout(function(){
        btn.disabled = false;
        btn.textContent = 'Save via local bridge';
      }, 1400);
    }
  }
}
async function saveJsonFileFromBrowser(value, preferredName, description) {
  var filename = studyDeckSafeJsonFileName(preferredName);
  var json = JSON.stringify(value, null, 2);
  if (typeof json !== 'string' || !json.trim()) {
    alert('StudyDeck could not build a JSON payload to save. Nothing was written.');
    return false;
  }
  var blob = new Blob([json], { type: 'application/json;charset=utf-8' });
  var canUseSavePicker = typeof window !== 'undefined'
    && window.location
    && window.location.protocol !== 'file:'
    && typeof window.showSaveFilePicker === 'function';
  if (!canUseSavePicker && typeof openExportTextModal === 'function') {
    studyDeckCurrentExportDescription = description || 'JSON file';
    openExportTextModal(
      'Save updated sidecar JSON',
      '<strong>Recommended in Codex:</strong> use <strong>Save via local bridge</strong>. It writes the updated sidecar directly into StudyDeck’s <code>sidecars/</code> folder through the local Author Bridge.<br><br>If the bridge is not running, double-click <code>' + studyDeckAuthorBridgeStartScript + '</code>, or run:<br><code>' + studyDeckAuthorBridgeCommand + '</code><br><br><strong>Other browsers:</strong> use <strong>Download JSON file</strong> in Chrome or Safari-style browsers.<br><br><strong>Manual fallback:</strong> use <strong>Copy to clipboard</strong> if the bridge is not running and browser downloads are blocked.',
      json,
      filename
    );
    if (typeof showXpToast === 'function') showXpToast('JSON export ready.');
    return true;
  }
  if (canUseSavePicker) {
    try {
      await studyDeckWriteJsonWithSavePicker(json, filename, description || 'JSON file');
      if (typeof showXpToast === 'function') showXpToast('JSON file saved.');
      return true;
    } catch (err) {
      if (err && err.name === 'AbortError') return false;
      console.warn('Save picker failed; falling back to download.', err);
    }
  }
  var url = URL.createObjectURL(blob);
  var link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.rel = 'noopener';
  document.body.appendChild(link);
  link.click();
  setTimeout(function(){
    URL.revokeObjectURL(url);
    if (link.parentNode) link.parentNode.removeChild(link);
  }, 60000);
  if (typeof showXpToast === 'function') showXpToast('JSON file download started.');
  return true;
}
function exportData() {
  var json = JSON.stringify({ decks: decks, tagGroups: tagGroups }, null, 2);
  openExportTextModal('', '', json);
}
