// ── CARD UNIQUE IDs ──
function genUID() {
  var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no ambiguous chars (0,O,1,I)
  var uid = '';
  for (var i = 0; i < 4; i++) uid += chars[Math.floor(Math.random() * chars.length)];
  return uid;
}
var _lastNumericId = 0;
function nextNumericId() {
  var candidate = Date.now();
  if (candidate <= _lastNumericId) candidate = _lastNumericId + 1;
  _lastNumericId = candidate;
  return candidate;
}
function ensureUIDs() {
  // Build a set of all existing UIDs to avoid collisions
  var used = {};
  decks.forEach(function(d){ d.cards.forEach(function(c){ if (c.uid) used[c.uid] = 1; }); });
  decks.forEach(function(d){
    d.cards.forEach(function(c){
      if (!c.uid) {
        var uid;
        do { uid = genUID(); } while (used[uid]);
        c.uid = uid; used[uid] = 1;
      }
    });
  });
}
function findCardByUID(uid) {
  uid = uid.toUpperCase().trim();
  for (var di = 0; di < decks.length; di++) {
    var d = decks[di];
    for (var ci = 0; ci < d.cards.length; ci++) {
      if (d.cards[ci].uid === uid) return { deck: d, card: d.cards[ci] };
    }
  }
  return null;
}
function findDeckByIdLoose(deckId) {
  return decks.find(function(d){ return String(d.id) === String(deckId); }) || null;
}
function findCardInDeckByIdLoose(deck, cardId) {
  if (!deck || !Array.isArray(deck.cards)) return null;
  return deck.cards.find(function(c){ return String(c.id) === String(cardId); }) || null;
}
function cardLinkTargetUID(link) {
  if (!link || link.type !== 'card') return '';
  var candidates = [
    link.cardUid,
    link.targetCardUid,
    link.targetUid,
    link.uid
  ];
  for (var i = 0; i < candidates.length; i += 1) {
    var uid = String(candidates[i] || '').trim().toUpperCase();
    if (uid && /^[A-Z2-9]{4}$/.test(uid)) return uid;
  }
  return '';
}
function setCardLinkTarget(link, target) {
  if (!link || !target || !target.deck || !target.card) return link;
  link.deckId = target.deck.id;
  link.cardId = target.card.id;
  if (target.card.uid) link.cardUid = target.card.uid;
  link.targetDeckName = target.deck.name || '';
  return link;
}
function resolveCardLinkTarget(link) {
  if (!link || link.type !== 'card') return null;
  var uid = cardLinkTargetUID(link);
  if (uid) return findCardByUID(uid);
  var deck = findDeckByIdLoose(link.deckId);
  var card = findCardInDeckByIdLoose(deck, link.cardId);
  if (deck && card) return { deck: deck, card: card };
  var matches = [];
  decks.forEach(function(d){
    var found = findCardInDeckByIdLoose(d, link.cardId);
    if (found) matches.push({ deck: d, card: found });
  });
  return matches.length === 1 ? matches[0] : null;
}
function enrichCardLinkTarget(link) {
  var target = resolveCardLinkTarget(link);
  if (target) setCardLinkTarget(link, target);
  return target;
}
function buildCardUidMap(cards) {
  var out = {};
  (cards || []).forEach(function(card){
    if (card && card.uid) out[String(card.uid).trim().toUpperCase()] = card;
  });
  return out;
}
function repairCardLinksForImportedDeck(deck, options) {
  options = options || {};
  if (!deck || !Array.isArray(deck.cards)) return { repaired: 0, unresolved: 0 };
  var importedDeckId = options.importedDeckId;
  var incomingIdToUid = options.incomingIdToUid || {};
  var actualByUid = options.actualByUid || buildCardUidMap(deck.cards);
  var counts = { repaired: 0, unresolved: 0 };
  deck.cards.forEach(function(card){
    (card.links || []).forEach(function(link){
      if (!link || link.type !== 'card') return;
      var linkDeckMatchesImport = importedDeckId != null && String(link.deckId) === String(importedDeckId);
      var remappedUid = String(incomingIdToUid[String(link.cardId)] || '').trim().toUpperCase();
      var uid = linkDeckMatchesImport && remappedUid ? remappedUid : cardLinkTargetUID(link);
      if (!uid && !findDeckByIdLoose(link.deckId)) uid = remappedUid;
      if (uid && actualByUid[uid]) {
        setCardLinkTarget(link, { deck: deck, card: actualByUid[uid] });
        counts.repaired += 1;
        return;
      }
      if (uid) {
        var globalTarget = findCardByUID(uid);
        if (globalTarget) {
          setCardLinkTarget(link, globalTarget);
          counts.repaired += 1;
          return;
        }
        link.cardUid = uid;
      }
      if (enrichCardLinkTarget(link)) counts.repaired += 1;
      else counts.unresolved += 1;
    });
  });
  return counts;
}
function repairAllCardLinks() {
  decks.forEach(function(deck){
    repairCardLinksForImportedDeck(deck);
  });
}
// Run on startup
