function cardKey(c)    { return (c._deckId || activeDeck.id) + ':' + c.id; }
function isFav(c)      { return favorites.has(cardKey(c)); }
function isMore(c)     { return studyMore.has(cardKey(c)); }
function toggleFav(c)  { var k=cardKey(c); favorites.has(k)  ? favorites.delete(k)  : favorites.add(k); saveReviewMarks(); }
function toggleMore(c) { var k=cardKey(c); studyMore.has(k)  ? studyMore.delete(k)  : studyMore.add(k); saveReviewMarks(); }
function currentFlashcardKey() {
  if (!fcCards.length || !fcCards[fcIdx]) return '';
  return cardKey(fcCards[fcIdx].card);
}

function parseLevelFilter(str) {
  // Returns a Set of accepted levels, or null if blank/invalid (= show all)
  str = str.trim();
  if (!str) return null;
  var levels = new Set();
  str.split(',').forEach(function(part) {
    part = part.trim();
    var range = part.match(/^(\d+)\s*-\s*(\d+)$/);
    if (range) {
      var lo = parseInt(range[1]), hi = parseInt(range[2]);
      for (var i = Math.min(lo,hi); i <= Math.max(lo,hi); i++) levels.add(i);
    } else if (/^\d+$/.test(part)) {
      levels.add(parseInt(part));
    }
  });
  return levels.size ? levels : null;
}

function getFiltered() {
  if (!activeDeck) return [];
  var cards = activeDeck.cards.slice();
  // Non-authors: only show cards at or below the deck's unlocked level
  if (!authorMode && !activeDeck._isAll && activeDeck.id !== '__daily__') {
    var ul = getDeckUnlockedLevel(activeDeck.id);
    cards = cards.filter(function(c){ return (c.level || 1) <= ul; });
  }
  if (filterFav)  cards = cards.filter(function(c){ return favorites.has(cardKey(c)); });
  if (filterMore) cards = cards.filter(function(c){ return studyMore.has(cardKey(c)); });
  if (filterTags.length) cards = cards.filter(function(c){ return filterTags.some(function(t){ return c.tags.includes(t); }); });
  if (filterExcludeTags.length) cards = cards.filter(function(c){
    return !filterExcludeTags.some(function(t){ return c.tags.includes(t); });
  });
  if (filterSearch.trim()) {
    var q = filterSearch.trim().toLowerCase();
    cards = cards.filter(function(c){
      return (c.q && c.q.toLowerCase().indexOf(q) !== -1)
          || (c.a && c.a.toLowerCase().indexOf(q) !== -1)
          || (c.tags && c.tags.some(function(t){ return t.toLowerCase().indexOf(q) !== -1; }));
    });
  }
  if (filterLevel.trim()) {
    var lvSet = parseLevelFilter(filterLevel);
    if (lvSet) cards = cards.filter(function(c){ return lvSet.has(c.level || 1); });
  }
  return cards;
}
function allTags(deck) {
  var seen = {}, out = [];
  deck.cards.forEach(function(c){ c.tags.forEach(function(t){ if(!seen[t]){ seen[t]=1; out.push(t); } }); });
  return out;
}
function shuffle(arr) {
  var a = arr.slice();
  for (var i = a.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = a[i]; a[i] = a[j]; a[j] = tmp;
  }
  return a;
}

var BIBLE_BOOK_NAMES = [
  'Song of Solomon','Song of Songs','1 Chronicles','2 Chronicles','1 Corinthians','2 Corinthians','1 Thessalonians','2 Thessalonians',
  '1 Samuel','2 Samuel','1 Kings','2 Kings','1 Timothy','2 Timothy','1 Peter','2 Peter','1 John','2 John','3 John',
  'Deuteronomy','Ecclesiastes','Lamentations','Philippians','Colossians','Revelation',
  'Genesis','Exodus','Leviticus','Numbers','Joshua','Judges','Ruth','Ezra','Nehemiah','Esther','Psalms','Psalm','Proverbs',
  'Isaiah','Jeremiah','Ezekiel','Daniel','Hosea','Joel','Amos','Obadiah','Jonah','Micah','Nahum','Habakkuk','Zephaniah',
  'Haggai','Zechariah','Malachi','Matthew','Mark','Luke','John','Acts','Romans','Galatians','Ephesians','Titus','Philemon',
  'Hebrews','James','Jude','Job'
];
var BIBLE_BOOK_RE = null;

function regexEscape(str) {
  return String(str).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
function getBibleBookRegex() {
  if (!BIBLE_BOOK_RE) {
    var books = BIBLE_BOOK_NAMES.slice().sort(function(a,b){ return b.length - a.length; });
    BIBLE_BOOK_RE = new RegExp('^(' + books.map(regexEscape).join('|') + ')(?:\\s+(.+))?$', 'i');
  }
  return BIBLE_BOOK_RE;
}
function cleanQuizAnswerText(value) {
  return String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
}
function normalizeQuizOptionKey(value) {
  return cleanQuizAnswerText(value).toLowerCase();
}
function formatReferenceList(parts) {
  var out = [];
  var seen = {};
  parts.forEach(function(part){
    var key = normalizeQuizOptionKey(part);
    if (key && !seen[key]) { seen[key] = 1; out.push(part); }
  });
  if (out.length <= 2) return out.join(' & ');
  return out.slice(0, -1).join(', ') + ', & ' + out[out.length - 1];
}
function mediumChapterFromReference(ref) {
  ref = cleanQuizAnswerText(ref).replace(/[–—]/g, '-');
  var m = ref.match(/^(\d+)(?::(\d+[a-z]?))?(?:\s*-\s*(?:(\d+):)?(\d+[a-z]?))?/i);
  if (!m) return '';
  var startChapter = m[1];
  var hasStartVerse = !!m[2];
  var explicitEndChapter = m[3];
  var endTail = m[4];
  if (explicitEndChapter) return explicitEndChapter === startChapter ? startChapter : startChapter + '-' + explicitEndChapter;
  if (!hasStartVerse && endTail && /^\d+$/.test(endTail)) return startChapter + '-' + endTail;
  return startChapter;
}
function simplifyBibleReferenceSegment(segment, difficulty) {
  segment = cleanQuizAnswerText(segment).replace(/^[&,\s]+/, '').replace(/^(and)\s+/i, '').replace(/[.;]+$/, '');
  var match = segment.match(getBibleBookRegex());
  if (!match) return null;
  var book = cleanQuizAnswerText(match[1]);
  var ref = cleanQuizAnswerText(match[2] || '');
  if (!ref) return book;
  if (!/^\d/.test(ref)) return null;
  if (difficulty === 'easy') return book;
  if (difficulty === 'medium') {
    var chapter = mediumChapterFromReference(ref);
    return chapter ? book + ' ' + chapter : book;
  }
  return segment;
}
function simplifyBibleReferenceList(answer, difficulty) {
  var text = cleanQuizAnswerText(answer);
  var parts = text
    .replace(/\s*&\s*/g, ', ')
    .replace(/\s+\band\b\s+/gi, ', ')
    .split(/\s*,\s*|\s*;\s*/)
    .filter(Boolean);
  if (!parts.length) return null;
  var simplified = [];
  for (var i = 0; i < parts.length; i++) {
    var part = simplifyBibleReferenceSegment(parts[i], difficulty);
    if (!part) return null;
    simplified.push(part);
  }
  return formatReferenceList(simplified);
}
function simplifyKnownNonBibleReference(answer, difficulty) {
  var text = cleanQuizAnswerText(answer);
  var match;

  match = text.match(/^(The\s+Qur['’]?an|Qur['’]?an|The\s+Quran|Quran)\s*,\s*(Surah\s+.+)$/i);
  if (match) {
    if (difficulty === 'easy') return cleanQuizAnswerText(match[1]);
    if (difficulty === 'medium') {
      var surah = cleanQuizAnswerText(match[2]).replace(/\s+\d+(?::\d+(?:-\d+)?)?$/i, '');
      return cleanQuizAnswerText(match[1]) + ', ' + surah;
    }
  }

  match = text.match(/^(Bhagavad\s+Gita)\s+(\d+)(?::\d+(?:-\d+)?)?$/i);
  if (match) {
    if (difficulty === 'easy') return cleanQuizAnswerText(match[1]);
    if (difficulty === 'medium') return cleanQuizAnswerText(match[1]) + ' ' + match[2];
  }

  match = text.match(/^(Mein\s+Kampf)\s+Vol\.?\s+(\d+)(?:\s+Ch\.?\s+[\w.-]+)?$/i);
  if (match) {
    if (difficulty === 'easy') return cleanQuizAnswerText(match[1]);
    if (difficulty === 'medium') return cleanQuizAnswerText(match[1]) + ' Vol. ' + match[2];
  }

  return null;
}
function simplifyAnswerTextForDifficulty(answer, difficulty) {
  difficulty = normalizeQuizDifficulty(difficulty);
  var exact = cleanQuizAnswerText(answer);
  if (!exact || difficulty === 'hard') return exact;
  return simplifyKnownNonBibleReference(exact, difficulty)
      || simplifyBibleReferenceList(exact, difficulty)
      || exact;
}
function getQuizAnswerOverride(card, difficulty) {
  if (!card || difficulty === 'hard') return '';
  var value = '';
  if (card.quizAnswers && card.quizAnswers[difficulty]) value = card.quizAnswers[difficulty];
  if (!value && difficulty === 'medium') value = card.aMedium || card.a2 || '';
  if (!value && difficulty === 'easy') value = card.aEasy || card.a3 || '';
  return cleanQuizAnswerText(value);
}
function getQuizAnswerForDifficulty(card, difficulty) {
  difficulty = normalizeQuizDifficulty(difficulty);
  var exact = cleanQuizAnswerText(card && card.a);
  if (difficulty === 'hard') return exact;
  return getQuizAnswerOverride(card, difficulty) || simplifyAnswerTextForDifficulty(exact, difficulty);
}
function addQuizOption(out, used, label, sourceAnswer, correct) {
  label = cleanQuizAnswerText(label);
  var key = normalizeQuizOptionKey(label);
  if (!key || used.has(key)) return false;
  used.add(key);
  out.push({ label: label, sourceAnswer: sourceAnswer || label, correct: !!correct });
  return true;
}
function genOpts(card, pool) {
  var correctLabel = getQuizAnswerForDifficulty(card, quizDifficulty);
  var correctOption = { label: correctLabel, sourceAnswer: card.a, correct: true };
  var usedAnswers = new Set([normalizeQuizOptionKey(correctLabel)]);
  var wrong = [];

  // Determine how many pool distractors to use
  // poolCount = min(2, deckUnlockedLevel - cardLevel), clamped to [0,2]
  var cardLevel = card.level || 1;
  var deckId    = card._deckId || (activeDeck ? activeDeck.id : null);
  var deckUnlocked = getDeckUnlockedLevel(deckId);
  var poolCount = Math.min(2, Math.max(0, deckUnlocked - cardLevel));

  // Pull from wrong answer pool first (if available)
  if (poolCount > 0 && card.wrongAnswers && card.wrongAnswers.length) {
    var poolCandidates = shuffle(card.wrongAnswers.filter(function(a){
      return a && cleanQuizAnswerText(a);
    }));
    for (var p = 0; p < poolCandidates.length && wrong.length < poolCount; p++) {
      addQuizOption(
        wrong,
        usedAnswers,
        simplifyAnswerTextForDifficulty(poolCandidates[p], quizDifficulty),
        poolCandidates[p],
        false
      );
    }
  }

  // Fill remaining slots from same-deck cards
  var candidates = shuffle(pool.filter(function(c){ return c.id !== card.id; }));
  for (var i = 0; i < candidates.length && wrong.length < 3; i++) {
    addQuizOption(
      wrong,
      usedAnswers,
      getQuizAnswerForDifficulty(candidates[i], quizDifficulty),
      candidates[i].a,
      false
    );
  }

  // Pad from all decks if still not enough
  if (wrong.length < 3) {
    var allCards = shuffle(decks.flatMap(function(d){ return d.cards; }));
    for (var j = 0; j < allCards.length && wrong.length < 3; j++) {
      addQuizOption(
        wrong,
        usedAnswers,
        getQuizAnswerForDifficulty(allCards[j], quizDifficulty),
        allCards[j].a,
        false
      );
    }
  }

  return shuffle(wrong.concat([correctOption]));
}

function getDeckPool(card) {
  // For daily challenge cards tagged with _deckId, use that deck's cards.
  // Otherwise use activeDeck's cards.
  var deckId = card._deckId || (activeDeck ? activeDeck.id : null);
  if (deckId && deckId !== '__daily__' && deckId !== '__all__') {
    var d = decks.find(function(x){ return x.id === deckId; });
    if (d) return d.cards;
  }
  return activeDeck ? activeDeck.cards : [];
}

// ── VIEWS ──
function guidedMainDockAllowed() {
  if (typeof guidedState === 'undefined' || !guidedState) return true;
  return [
    GUIDED_SCREEN_HUB,
    GUIDED_SCREEN_PATH
  ].indexOf(guidedState.screen) !== -1;
}
function getMainDockActiveViewId() {
  var activeEl = document.querySelector('.view.active');
  return activeEl ? activeEl.id : '';
}
function repairMainDockMount() {
  var appEl = document.getElementById('app');
  var docks = document.querySelectorAll('#main-dock');
  if (!appEl || !docks.length) return null;
  var dock = docks[0];
  for (var i = 1; i < docks.length; i++) {
    if (docks[i].parentNode) docks[i].parentNode.removeChild(docks[i]);
  }
  if (dock.parentElement !== appEl) appEl.appendChild(dock);
  return dock;
}
function syncMainDockStyleLabGate() {
  if (typeof authorMode === 'undefined' || typeof styleLabOpen === 'undefined') return;
  document.documentElement.classList.toggle('style-lab-open', !!(authorMode && styleLabOpen));
}
function updateMainDock(activeViewId) {
  var dock = repairMainDockMount();
  syncMainDockStyleLabGate();
  var active = getMainDockActiveViewId() || activeViewId || '';
  var visible = active === 'home' || active === 'decks' || active === 'profile' || (active === 'guided' && guidedMainDockAllowed());
  var activeTab = active === 'guided' ? 'guided' : active;
  if (dock) dock.setAttribute('aria-hidden', visible ? 'false' : 'true');
  document.documentElement.classList.toggle('main-dock-visible', !!visible);
  document.documentElement.setAttribute('data-main-tab', activeTab || '');
  document.querySelectorAll('.main-dock-btn').forEach(function(btn){
    var tab = btn.getAttribute('data-main-tab');
    var label = btn.getAttribute('data-main-label') || btn.getAttribute('aria-label') || tab || 'section';
    var isCurrent = !!visible && tab === activeTab;
    btn.classList.toggle('is-active', isCurrent);
    btn.setAttribute('tabindex', visible ? '0' : '-1');
    btn.setAttribute('aria-label', isCurrent ? label + ', current section' : 'Open ' + label);
    btn.setAttribute('title', isCurrent ? label + ' (current)' : label);
    if (isCurrent) {
      btn.setAttribute('aria-current', 'page');
    } else {
      btn.removeAttribute('aria-current');
    }
  });
}
function showMainTab(tab) {
  if (tab === 'guided') { showGuided(); return; }
  if (tab === 'decks') { showDecks(); return; }
  if (tab === 'profile') { showProfile(); return; }
  showHome();
}
var studyDeckDeferredViewRenderToken = 0;
function studyDeckRenderAfterViewShown(viewId, renderFn) {
  var token = studyDeckDeferredViewRenderToken;
  studyDeckAfterPaint(function(){
    if (token !== studyDeckDeferredViewRenderToken) return;
    if (getMainDockActiveViewId() !== viewId) return;
    renderFn();
  });
}
function show(id) {
  studyDeckDeferredViewRenderToken++;
  if (id !== 'guided' && typeof guidedDiscardNodePositionOnExit === 'function' && guidedDiscardNodePositionOnExit()) {
    if (typeof saveGuidedState === 'function') saveGuidedState();
  }
  document.querySelectorAll('.view').forEach(function(v){ v.classList.remove('active'); });
  document.getElementById(id).classList.add('active');
  document.documentElement.classList.toggle('flashcard-active', id === 'flashcard');
  document.getElementById('app').scrollTo(0,0);
  if (typeof scheduleGuidedPathMaskSync === 'function') scheduleGuidedPathMaskSync();
  if (typeof updateStyleLabChrome === 'function') updateStyleLabChrome();
  if (typeof refreshStyleLabView === 'function') setTimeout(refreshStyleLabView, 0);
  updateMainDock(id);
}
function rememberTimelineViewBeforeExit() {
  var active = document.querySelector('.view.active');
  if (active && active.id === 'timeline' && typeof studyDeckTimelineRememberScroll === 'function') {
    studyDeckTimelineRememberScroll();
  }
}
function showHome()   { rememberTimelineViewBeforeExit(); stopCelebration(); show('home');    studyDeckRenderAfterViewShown('home', renderHome); }
function showDecks()  { rememberTimelineViewBeforeExit(); stopCelebration(); show('decks');   studyDeckRenderAfterViewShown('decks', renderDecks); }
function showProfile(){ rememberTimelineViewBeforeExit(); stopCelebration(); show('profile'); studyDeckRenderAfterViewShown('profile', renderProfile); }
function showDetail() { rememberTimelineViewBeforeExit(); stopCelebration(); renderDetail(); show('detail'); }
function showCreate() { rememberTimelineViewBeforeExit(); renderCreate(); show('create'); }

// ── PIN / AUTH ──
function lockTap() {
  if (authorMode) {
    authorMode = false;
    closeStyleLab();
    renderHome();
    renderDecks();
    renderProfile();
    updateStyleLabChrome();
    return;
  }
  if (!AUTHOR_PIN_REQUIRED) {
    authorMode = true;
    closePin();
    renderHome();
    renderDecks();
    renderProfile();
    updateStyleLabChrome();
    return;
  }
  pinEntry = '';
  document.getElementById('pin-error').textContent = '';
  updatePinDots();
  document.getElementById('pin-overlay').classList.add('open');
  studyDeckOpenDialog('pin-overlay', { focusSelector: '.pin-key' });
}
function closePin() {
  pinEntry = '';
  document.getElementById('pin-overlay').classList.remove('open');
  studyDeckCloseDialog('pin-overlay');
}
function pinKey(d) {
  if (pinEntry.length >= 4) return;
  pinEntry += d;
  updatePinDots();
  if (pinEntry.length === 4) {
    if (pinEntry === AUTHOR_PIN) {
      authorMode = true;
      closePin();
      renderHome();
      renderDecks();
      renderProfile();
      updateStyleLabChrome();
    } else {
      document.getElementById('pin-error').textContent = 'Incorrect PIN';
      var box = document.getElementById('pin-box');
      box.classList.add('shake');
      setTimeout(function(){ box.classList.remove('shake'); pinEntry=''; updatePinDots(); }, 400);
    }
  }
}
function pinDel() { if (pinEntry.length) { pinEntry=pinEntry.slice(0,-1); updatePinDots(); } }
function updatePinDots() {
  for (var i=0;i<4;i++) {
    document.getElementById('pd'+i).classList.toggle('filled', i < pinEntry.length);
  }
}

// ── EDIT DECK ──
function showEditDeck(deckId) {
  var d = decks.find(function(x){ return x.id===deckId; });
  if (!d) return;
  activeDeck = d;
  editDeckId = deckId;
  editColor  = d.color;
  editTagFilter = [];
  editExcludeTags = [];
  editTagsExpanded = false;
  editLevelFilter = '';
  editSearch = '';
  document.getElementById('edit-name').value = d.name;
  document.getElementById('edit-desc').value = d.desc;
  var versionEl = document.getElementById('edit-content-version');
  if (versionEl) versionEl.value = d.contentVersion ? String(d.contentVersion) : 'Not set';
  renderEditColorRow();
  renderEditCardsList();
  document.getElementById('edit-new-q').value = '';
  document.getElementById('edit-new-a').value = '';
  document.getElementById('edit-new-t').value = '';
  show('edit-deck');
}
function renderEditColorRow() {
  document.getElementById('edit-color-row').innerHTML = COLORS.map(function(c){
    return '<div class="swatch'+(c===editColor?' on':'')+'" style="background:'+c+'" onclick="pickEditColor(\''+c+'\')"></div>';
  }).join('');
}
function pickEditColor(c) { editColor=c; renderEditColorRow(); }
function renderEditCardsList() {
  var d = decks.find(function(x){ return x.id==editDeckId; });
  if (!d) return;

  // Collect all tags across this deck for the filter bar
  var allEditTags = [];
  var seenTags = {};
  d.cards.forEach(function(c){
    c.tags.forEach(function(t){
      if (!seenTags[t]) { seenTags[t]=1; allEditTags.push(t); }
    });
  });

  // Build tag filter bar — mirror detail view with tag groups
  var relevantEditGroups = tagGroups.filter(function(g){
    return g.tags.some(function(t){ return seenTags[t]; });
  });
  var ungroupedEditTags = allEditTags.filter(function(t){
    return !relevantEditGroups.some(function(g){ return g.tags.includes(t); });
  });
  var editTagControlCount = relevantEditGroups.length + ungroupedEditTags.length;
  var shouldCollapseEditTags = editTagControlCount > 10;

  var filterBar = '';
  if (allEditTags.length || true) {
    var tagPills = relevantEditGroups.map(function(g){
      var hasActive = g.tags.some(function(t){ return editTagFilter.includes(t) || editExcludeTags.includes(t); });
      return '<button class="filter-pill tg-pill'+(hasActive?' has-active':'')+'" onclick="openTgOverlayEdit('+g.id+')">'
        +escHtml(g.name)+'<span class="tg-chevron">▾</span></button>';
    }).join('')
    + ungroupedEditTags.map(function(t){
      var on = editTagFilter.includes(t);
      var excluded = editExcludeTags.includes(t);
      return '<button class="filter-pill tag-pill'+(on?' on':'')+(excluded?' excluded':'')+'" '
        +'data-tag-pill="1" '
        +'data-tag="'+escHtml(t)+'" '
        +'data-tag-context="edit" '
        +'title="Tap to include. Press and hold to exclude.">'+escHtml(t)+'</button>';
    }).join('');

    var hasAnyFilter = editTagFilter.length || editExcludeTags.length || editLevelFilter.trim() || editSearch.trim();
    var editFilterSummary = [];
    if (editSearch.trim()) editFilterSummary.push({ label: 'Search', value: editSearch.trim(), type: 'search' });
    if (editLevelFilter.trim()) editFilterSummary.push({ label: 'Level', value: editLevelFilter.trim(), type: 'level' });
    editTagFilter.forEach(function(t){ editFilterSummary.push({ label: 'Include tag', value: t, type: 'include' }); });
    editExcludeTags.forEach(function(t){ editFilterSummary.push({ label: 'Hide tag', value: t, type: 'exclude' }); });
    filterBar = (tagPills
      ? '<div class="filter-tags-shell" style="margin-bottom:8px">'
          +'<div style="font-size:11px;color:var(--muted);margin-bottom:8px">Tags:</div>'
          +'<div class="filter-row filter-tags-wrap '+(shouldCollapseEditTags && !editTagsExpanded ? 'collapsed' : 'expanded')+'">'
            +tagPills
          +'</div>'
          +(shouldCollapseEditTags
            ? (editTagsExpanded
                ? '<div class="filter-tags-hint">Hold a tag for 1 second to hide matching cards.</div>'
                : '')
              +'<button class="filter-pill filter-tags-toggle" onclick="toggleEditTagExpansion()">'
              +(editTagsExpanded ? 'Show Less Tags' : 'Show More Tags')
              +'</button>'
            : '')
        +'</div>'
      : '')
    + '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px">'
        +'<span style="font-size:11px;color:var(--muted);flex-shrink:0">Level:</span>'
        +'<input class="form-inp" id="edit-filter-level-inp" value="'+escHtml(editLevelFilter)+'" placeholder="e.g. 2 or 3-5 or 1,4" style="padding:6px 10px;font-size:12px;flex:1;max-width:180px" oninput="setEditLevelFilter(this.value)">'
        +(hasAnyFilter ? '<button class="filter-pill" style="font-size:11px;padding:4px 10px;flex-shrink:0" onclick="clearAllEditFilters()">✕ Clear all</button>' : '')
      +'</div>'
    + renderFilterActiveSummary(editFilterSummary, 'clearAllEditFilters()');
  }

  // Apply filters
  var cards = d.cards;
  if (editTagFilter.length) {
    cards = cards.filter(function(c){
      return editTagFilter.some(function(t){ return c.tags.includes(t); });
    });
  }
  if (editExcludeTags.length) {
    cards = cards.filter(function(c){
      return !editExcludeTags.some(function(t){ return c.tags.includes(t); });
    });
  }
  if (editLevelFilter.trim()) {
    var lvSet = parseLevelFilter(editLevelFilter);
    if (lvSet) cards = cards.filter(function(c){ return lvSet.has(c.level || 1); });
  }
  if (editSearch.trim()) {
    var q = editSearch.trim().toLowerCase();
    cards = cards.filter(function(c){
      return (c.q && c.q.toLowerCase().indexOf(q) !== -1)
          || (c.a && c.a.toLowerCase().indexOf(q) !== -1)
          || (c.tags && c.tags.some(function(t){ return t.toLowerCase().indexOf(q) !== -1; }));
    });
  }
  // Sync search input state
  var esInp = document.getElementById('edit-search-inp');
  var esClr = document.getElementById('edit-search-clear');
  if (esInp && esInp.value !== editSearch) esInp.value = editSearch;
  if (esClr) esClr.style.display = editSearch.trim() ? '' : 'none';
  var countEl = document.getElementById('edit-cards-count');
  if (countEl) {
    countEl.textContent = cards.length + ' shown' + (cards.length !== d.cards.length ? ' of ' + d.cards.length : '');
  }

  document.getElementById('edit-cards-list').innerHTML =
    filterBar
    + (cards.length === 0 ? renderEditCardsNoResults() : '')
    + cards.map(function(c,i){
    var tagsVal  = c.tags.join(', ');
    var links    = c.links || [];
    var addOpen  = !!linkEditOpen[c.id];
    var addType  = linkEditType[c.id] || 'url';
    var editingLinkId = linkEditing[c.id] || null;
    // Existing links list
    var existingLinks = links.map(function(lk, li){
      var typeLabel = lk.type==='url' ? '↗ URL' : '🃏 Card';
      var sideLabel = lk.side==='q' ? ' · Front only' : lk.side==='a' ? ' · Back only' : ' · Both sides';
      var isFirstLk = li === 0, isLastLk = li === links.length - 1;
      var resolvedLinkTarget = lk.type === 'card' ? resolveCardLinkTarget(lk) : null;
      var linkSelectedVal = resolvedLinkTarget
        ? resolvedLinkTarget.deck.id + ':' + resolvedLinkTarget.card.id
        : (lk.deckId + ':' + lk.cardId);
      // Show inline edit form for this link
      if (editingLinkId === lk.id) {
        var cardPickerEdit = lk.type === 'url'
          ? '<div class="form-group" style="margin-bottom:8px">'
              +'<label class="form-lbl" for="elu-'+lk.id+'">URL</label>'
              +'<input class="form-inp" id="elu-'+lk.id+'" value="'+escHtml(lk.url||'')+'">'
            +'</div>'
          : '<div class="form-group" style="margin-bottom:8px">'
              +'<label class="form-lbl">Change linked card</label>'
              +'<div style="display:flex;gap:8px;margin-bottom:6px">'
                +'<input class="form-inp" id="euid-'+lk.id+'" placeholder="Enter 4-char ID (e.g. A3K9)" style="font-family:monospace;letter-spacing:.08em;flex:1" maxlength="4" oninput="this.value=this.value.toUpperCase()">'
                +'<button class="btn btn-soft" style="padding:9px 12px;font-size:12px;flex-shrink:0" onclick="applyUIDToEditLink('+c.id+','+lk.id+')">Look up</button>'
              +'</div>'
              +'<div style="font-size:12px;color:var(--muted);padding:8px;background:var(--surface);border-radius:8px" id="euid-preview-'+lk.id+'">'
                +'Currently: '+escHtml(lk.label||'Card link')
              +'</div>'
              +'<select class="form-inp" id="elcard-'+lk.id+'" style="padding:10px 12px;margin-top:6px">'
                +'<option value="">— or pick from list —</option>'
                +buildCardOptions(d.id, c.id, linkSelectedVal)
              +'</select>'
            +'</div>';
        return '<div class="add-link-form" style="margin-bottom:6px">'
          +'<div class="form-group" style="margin-bottom:8px">'
            +'<label class="form-lbl" for="els-'+lk.id+'">Side</label>'
            +'<select class="form-inp" id="els-'+lk.id+'" style="padding:10px 12px">'
              +'<option value="both"'+((!lk.side||lk.side==='both')?' selected':'')+'>Both sides</option>'
              +'<option value="q"'+(lk.side==='q'?' selected':'')+'>Front only</option>'
              +'<option value="a"'+(lk.side==='a'?' selected':'')+'>Back only</option>'
            +'</select>'
          +'</div>'
          +'<div class="form-group" style="margin-bottom:8px">'
            +'<label class="form-lbl" for="ell-'+lk.id+'">Label</label>'
            +'<input class="form-inp" id="ell-'+lk.id+'" value="'+escHtml(lk.label||'')+'" placeholder="e.g. See also…">'
          +'</div>'
          +cardPickerEdit
          +'<div style="display:flex;gap:8px">'
            +'<button class="btn btn-soft" style="padding:9px;font-size:12px" onclick="cancelEditLink('+c.id+')">Cancel</button>'
            +'<button class="btn btn-gold" style="padding:9px;font-size:12px" onclick="saveLinkEdit('+c.id+','+lk.id+')">Save</button>'
          +'</div>'
        +'</div>';
      }
      return '<div class="existing-link-row">'
        +'<div class="reorder-btns">'
          +'<button class="reorder-btn" '+(isFirstLk?'disabled':'')+' onclick="moveLink('+c.id+','+lk.id+',-1)" title="Move up">↑</button>'
          +'<button class="reorder-btn" '+(isLastLk?'disabled':'')+' onclick="moveLink('+c.id+','+lk.id+',1)" title="Move down">↓</button>'
        +'</div>'
        +'<div class="existing-link-info">'
          +'<div class="existing-link-type">'+typeLabel+sideLabel+'</div>'
          +'<div class="existing-link-lbl">'+escHtml(lk.label||lk.url||'Linked card')+'</div>'
        +'</div>'
        +'<button class="reorder-btn" onclick="copyLink('+c.id+','+lk.id+')" title="Copy link" style="width:32px;height:32px;border-radius:8px;font-size:13px">📋</button>'
        +'<button class="reorder-btn" onclick="startEditLink('+c.id+','+lk.id+')" title="Edit link" style="width:32px;height:32px;border-radius:8px;font-size:13px">✏</button>'
        +'<button class="del-card-btn" onclick="deleteLink('+c.id+','+lk.id+')" title="Remove link">✕</button>'
      +'</div>';
    }).join('');

    // Add-link form
    var addSide  = linkEditSide[c.id] || 'both';
    var draftLnk = linkDraft[c.id] || {};
    var urlFields = addType==='url'
      ? '<div class="form-group" style="margin-bottom:8px">'
          +'<label class="form-lbl" for="lu-'+c.id+'">URL</label>'
          +'<input class="form-inp" id="lu-'+c.id+'" value="'+escHtml(draftLnk.url||'')+'" placeholder="https://…">'
        +'</div>'
      : '<div class="form-group" style="margin-bottom:8px">'
          +'<label class="form-lbl">Pick a card</label>'
          +'<div style="display:flex;gap:8px;margin-bottom:6px">'
            +'<input class="form-inp" id="luid-'+c.id+'" placeholder="Enter 4-char ID (e.g. A3K9)" style="font-family:monospace;letter-spacing:.08em;flex:1;text-transform:uppercase" maxlength="4">'
            +'<button class="btn btn-soft" style="padding:9px 12px;font-size:12px;flex-shrink:0" onclick="applyUIDToAddLink('+c.id+')">Look up</button>'
          +'</div>'
          +'<div style="font-size:12px;color:var(--muted);padding:8px;background:var(--surface);border-radius:8px;margin-bottom:6px" id="luid-preview-'+c.id+'">Enter an ID or pick from the list below</div>'
          +'<select class="form-inp" id="ld-'+c.id+'" onchange="syncCardSelect('+c.id+')" style="padding:10px 12px">'
            +'<option value="">— or browse all cards —</option>'
            +buildCardOptions(d.id, c.id)
          +'</select>'
          +'<input type="hidden" id="lc-'+c.id+'" value="">'
        +'</div>';

    var addForm = addOpen
      ? '<div class="add-link-form">'
          +'<div class="link-type-row">'
            +'<button class="link-type-btn'+(addType==='url'?' on':'')+'" onclick="setLinkType('+c.id+',\'url\')">↗ External URL</button>'
            +'<button class="link-type-btn'+(addType==='card'?' on':'')+'" onclick="setLinkType('+c.id+',\'card\')">🃏 Another card</button>'
          +'</div>'
          +'<div class="form-group" style="margin-bottom:8px">'
            +'<label class="form-lbl">Show on</label>'
            +'<div class="link-type-row">'
              +'<button class="link-type-btn'+(addSide==='both'?' on':'')+'" onclick="setLinkSide('+c.id+',\'both\')">Both sides</button>'
              +'<button class="link-type-btn'+(addSide==='q'?' on':'')+'" onclick="setLinkSide('+c.id+',\'q\')">Front only</button>'
              +'<button class="link-type-btn'+(addSide==='a'?' on':'')+'" onclick="setLinkSide('+c.id+',\'a\')">Back only</button>'
            +'</div>'
          +'</div>'
          +'<div class="form-group" style="margin-bottom:8px">'
            +'<label class="form-lbl" for="ll-'+c.id+'">Label (optional)</label>'
            +'<input class="form-inp" id="ll-'+c.id+'" value="'+escHtml(draftLnk.label||'')+'" placeholder="e.g. See Wikipedia…">'
          +'</div>'
          +urlFields
          +'<div style="display:flex;gap:8px">'
            +'<button class="btn btn-soft" style="padding:9px;font-size:12px" onclick="toggleAddLinkForm('+c.id+')">Cancel</button>'
            +'<button class="btn btn-gold" style="padding:9px;font-size:12px" onclick="addLink('+c.id+')">+ Add</button>'
          +'</div>'
        +'</div>'
      : '';

    var realIdx = d.cards.indexOf(c);
    var isFirst = realIdx === 0, isLast = realIdx === d.cards.length - 1;
    return '<div class="edit-card-block">'
      +'<div class="edit-card-num">'
        +'<div style="display:flex;align-items:center;gap:8px">'
          +'<div class="reorder-btns">'
            +'<button class="reorder-btn" '+(isFirst?'disabled':'')+' onclick="moveCard('+c.id+',-1)" title="Move up">↑</button>'
            +'<button class="reorder-btn" '+(isLast?'disabled':'')+' onclick="moveCard('+c.id+',1)" title="Move down">↓</button>'
          +'</div>'
          +'<span>Card '+(i+1)+'</span>'
        +'</div>'
        +'<span role="button" tabindex="0" data-copy-card-uid="'+escHtml(c.uid||'')+'" title="Unique card ID — tap to copy" style="font-family:monospace;font-size:12px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.14);border-radius:6px;padding:2px 8px;cursor:pointer;color:var(--muted);letter-spacing:.08em;user-select:all">'+escHtml(c.uid||'????')+'</span>'
        +'<button class="del-card-btn" onclick="editDeleteCard('+c.id+')" title="Delete card">✕</button>'
      +'</div>'
      +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">'
        +'<span class="form-lbl" style="margin:0;flex-shrink:0">Level</span>'
        +'<input class="form-inp" id="elv-'+c.id+'" type="number" min="1" max="40" step="1" value="'+(c.level||1)+'" style="width:64px;padding:8px 10px;text-align:center;font-weight:600" oninput="this.value=Math.min(40,Math.max(1,parseInt(this.value)||1))">'
        +'<span style="font-size:12px;color:var(--muted)">Difficulty 1–40</span>'
      +'</div>'
      +'<div class="form-group" style="margin-bottom:10px">'
        +'<label class="form-lbl" for="eq-'+c.id+'">Front</label>'
        +'<textarea class="form-ta" id="eq-'+c.id+'" rows="1" oninput="autoResize(this)">'+escHtml(c.q)+'</textarea>'
      +'</div>'
      +'<div class="form-group" style="margin-bottom:10px">'
        +'<label class="form-lbl" for="ea-'+c.id+'">Back</label>'
        +'<textarea class="form-ta" id="ea-'+c.id+'" rows="1" oninput="autoResize(this)">'+escHtml(c.a)+'</textarea>'
      +'</div>'
      +'<div class="form-group" style="margin-bottom:0;margin-top:10px">'
        +'<label class="form-lbl" for="et-'+c.id+'">Tags</label>'
        +'<input class="form-inp" id="et-'+c.id+'" value="'+escHtml(tagsVal)+'">'
      +'</div>'
      +'<div style="margin-top:10px">'
        +'<button class="btn btn-soft" style="padding:6px 12px;font-size:12px;width:100%" onclick="openDistractorModal('+c.id+')">'
          +'✗ Distractors'+(c.wrongAnswers&&c.wrongAnswers.length?' ('+c.wrongAnswers.length+')':'')
        +'</button>'
      +'</div>'
      // ── NOTES SECTION (above links) ──
      +(function(){
        var notes   = c.notes || [];
        var nOpen   = !!noteEditOpen[c.id];
        var nSide   = noteEditSide[c.id] || 'both';
        var editingNoteId = noteEditing[c.id] || null;
        var existingNotes = notes.map(function(n, ni){
          var isFirstN = ni===0, isLastN = ni===notes.length-1;
          var sideLabel = n.side==='q' ? 'Front only' : n.side==='a' ? 'Back only' : 'Both sides';
          // Show inline edit form for this note
          if (editingNoteId === n.id) {
            return '<div class="add-note-form" style="margin-bottom:6px">'
              +'<div class="form-group" style="margin-bottom:8px">'
                +'<label class="form-lbl" for="ens-'+n.id+'">Side</label>'
                +'<select class="form-inp" id="ens-'+n.id+'" style="padding:10px 12px">'
                  +'<option value="both"'+((!n.side||n.side==='both')?' selected':'')+'>Both sides</option>'
                  +'<option value="q"'+(n.side==='q'?' selected':'')+'>Front only</option>'
                  +'<option value="a"'+(n.side==='a'?' selected':'')+'>Back only</option>'
                +'</select>'
              +'</div>'
              +'<div class="form-group" style="margin-bottom:8px">'
                +'<label class="form-lbl" for="enl-'+n.id+'">Label</label>'
                +'<input class="form-inp" id="enl-'+n.id+'" value="'+escHtml(n.label||'')+'" placeholder="e.g. Tip, Warning…">'
              +'</div>'
              +'<div class="form-group" style="margin-bottom:8px">'
                +'<label class="form-lbl" for="ent-'+n.id+'">Note text</label>'
                +'<textarea class="form-ta" id="ent-'+n.id+'" rows="1" oninput="autoResize(this)">'+escHtml(n.text)+'</textarea>'
              +'</div>'
              +'<div style="display:flex;gap:8px">'
                +'<button class="btn btn-soft" style="padding:9px;font-size:12px" onclick="cancelEditNote('+c.id+')">Cancel</button>'
                +'<button class="btn btn-gold" style="padding:9px;font-size:12px" onclick="saveNoteEdit('+c.id+','+n.id+')">Save</button>'
              +'</div>'
            +'</div>';
          }
          return '<div class="existing-note-row">'
            +'<div class="reorder-btns">'
              +'<button class="reorder-btn" '+(isFirstN?'disabled':'')+' onclick="moveNote('+c.id+','+n.id+',-1)" title="Move up">↑</button>'
              +'<button class="reorder-btn" '+(isLastN?'disabled':'')+' onclick="moveNote('+c.id+','+n.id+',1)" title="Move down">↓</button>'
            +'</div>'
            +'<div class="existing-note-info">'
              +'<div class="existing-note-side">'+escHtml(n.label||'Note')+' · '+sideLabel+'</div>'
              +'<div class="existing-note-preview">'+escHtml(n.text)+'</div>'
            +'</div>'
            +'<button class="reorder-btn" onclick="copyNote('+c.id+','+n.id+')" title="Copy note" style="width:32px;height:32px;border-radius:8px;font-size:13px">📋</button>'
            +'<button class="reorder-btn" onclick="startEditNote('+c.id+','+n.id+')" title="Edit note" style="width:32px;height:32px;border-radius:8px;font-size:13px">✏</button>'
            +'<button class="del-card-btn" onclick="deleteNote('+c.id+','+n.id+')" title="Remove note">✕</button>'
          +'</div>';
        }).join('');
        var addNoteForm = nOpen
          ? (function(){
              var draftNt = noteDraft[c.id] || {};
              return '<div class="add-note-form">'
                +'<div class="form-group" style="margin-bottom:8px">'
                  +'<label class="form-lbl">Show on</label>'
                  +'<div class="link-type-row">'
                    +'<button class="link-type-btn'+(nSide==='both'?' on':'')+'" onclick="setNoteSide('+c.id+',\'both\')">Both sides</button>'
                    +'<button class="link-type-btn'+(nSide==='q'?' on':'')+'" onclick="setNoteSide('+c.id+',\'q\')">Front only</button>'
                    +'<button class="link-type-btn'+(nSide==='a'?' on':'')+'" onclick="setNoteSide('+c.id+',\'a\')">Back only</button>'
                  +'</div>'
                +'</div>'
                +'<div class="form-group" style="margin-bottom:8px">'
                  +'<label class="form-lbl" for="nl-'+c.id+'">Label</label>'
                  +'<input class="form-inp" id="nl-'+c.id+'" value="'+escHtml(draftNt.label||'')+'" placeholder="e.g. Etymology, Tip, Warning…">'
                +'</div>'
                +'<div class="form-group" style="margin-bottom:8px">'
                  +'<label class="form-lbl" for="nt-'+c.id+'">Note text</label>'
                  +'<textarea class="form-ta" id="nt-'+c.id+'" rows="1" oninput="autoResize(this)" placeholder="Type your note…">'+escHtml(draftNt.text||'')+'</textarea>'
                +'</div>'
                +'<div style="display:flex;gap:8px">'
                  +'<button class="btn btn-soft" style="padding:9px;font-size:12px" onclick="toggleAddNoteForm('+c.id+')">Cancel</button>'
                  +'<button class="btn btn-gold" style="padding:9px;font-size:12px" onclick="addNote('+c.id+')">+ Add</button>'
                +'</div>'
              +'</div>';
            }())
          : '';
        return '<div class="note-edit-sec">'
          +'<div class="note-edit-label">'
            +'<span>Notes'+(notes.length?' ('+notes.length+')':'')+'</span>'
            +'<div style="display:flex;gap:6px">'
              +(_noteClipboard ? '<button class="btn btn-soft" style="padding:4px 10px;font-size:11px;flex:none" onclick="pasteNote('+c.id+')" title="Paste copied note">📋 Paste</button>' : '')
              +(nOpen ? '' : '<button class="btn btn-soft" style="padding:4px 10px;font-size:11px;flex:none" onclick="toggleAddNoteForm('+c.id+')">+ Add note</button>')
            +'</div>'
          +'</div>'
          +existingNotes
          +addNoteForm
        +'</div>';
      }())
      +'<div class="link-edit-sec">'
        +'<div class="link-edit-label">'
          +'<span>Links'+(links.length?' ('+links.length+')':'')+'</span>'
          +'<div style="display:flex;gap:6px">'
            +(_linkClipboard ? '<button class="btn btn-soft" style="padding:4px 10px;font-size:11px;flex:none" onclick="pasteLink('+c.id+')" title="Paste copied link">📋 Paste</button>' : '')
            +(addOpen ? '' : '<button class="btn btn-soft" style="padding:4px 10px;font-size:11px;flex:none" onclick="toggleAddLinkForm('+c.id+')">+ Add link</button>')
          +'</div>'
        +'</div>'
        +existingLinks
        +addForm
      +'</div>'
    +'</div>';
  }).join('');
  setTimeout(initResizeAll, 0);
}
function applyUIDToAddLink(cardId) {
  var el = document.getElementById('luid-'+cardId);
  var previewEl = document.getElementById('luid-preview-'+cardId);
  if (!el || !previewEl) return;
  var uid = el.value.toUpperCase().trim();
  if (uid.length !== 4) { previewEl.style.color='#EF4444'; previewEl.textContent='Enter a 4-character ID.'; return; }
  var result = findCardByUID(uid);
  if (!result) { previewEl.style.color='#EF4444'; previewEl.textContent='No card found with ID "'+uid+'".'; return; }
  previewEl.style.color='#10B981';
  previewEl.textContent='✓ Found: "'+result.card.q.slice(0,50)+'" in '+result.deck.name;
  var sel = document.getElementById('ld-'+cardId);
  var val = result.deck.id+':'+result.card.id;
  if (sel) {
    var found=false;
    for (var i=0;i<sel.options.length;i++){ if(sel.options[i].value===val){sel.value=val;found=true;break;} }
    if (!found) { var opt=document.createElement('option'); opt.value=val; opt.textContent=result.card.q.slice(0,40)+' ['+uid+']'; opt.selected=true; sel.appendChild(opt); }
    sel.dataset.combined=val;
  }
}
