function escHtml(s) { return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function renderFilterActiveSummary(items, clearAction) {
  items = (items || []).filter(function(item){ return item && String(item.value || '').trim(); });
  if (!items.length) return '';
  return '<div class="filter-active-summary" role="status" aria-label="Active filters">'
    + '<span class="filter-active-label">Active filters</span>'
    + '<div class="filter-active-chip-row">'
    + items.map(function(item){
      var type = String(item.type || '').replace(/[^a-z0-9_-]/gi, '');
      return '<span class="filter-active-chip' + (type ? ' is-' + type : '') + '">'
        + '<strong>' + escHtml(item.label || 'Filter') + '</strong>'
        + '<span>' + escHtml(item.value) + '</span>'
      + '</span>';
    }).join('')
    + '</div>'
    + (clearAction ? '<button type="button" class="filter-active-clear" onclick="' + clearAction + '">Clear filters</button>' : '')
  + '</div>';
}
function filterOptionLabel(options, value) {
  value = String(value || '');
  var match = (options || []).find(function(option){ return String(option.value) === value; });
  return match ? match.label : value;
}
function nl2br(s)   { return escHtml(s).replace(/\n/g,'<br>'); }
function renderMDInline(s) {
  s = escHtml(s);
  s = s.replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>'); // ***bold italic***
  s = s.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');  // **bold**
  s = s.replace(/\*(.+?)\*/g,     '<em>$1</em>');           // *italic*
  s = s.replace(/__(.+?)__/g,     '<u>$1</u>');             // __underline__
  s = s.replace(/~~(.+?)~~/g,     '<s>$1</s>');             // ~~strikethrough~~
  s = s.replace(/`(.+?)`/g,       '<code class="md-code">$1</code>'); // `code`
  return s;
}
function renderMDTableCells(line) {
  var raw = String(line || '').trim();
  if (raw.charAt(0) === '|') raw = raw.slice(1);
  if (raw.charAt(raw.length - 1) === '|') raw = raw.slice(0, -1);
  return raw.split('|').map(function(cell){ return cell.trim(); });
}
function renderMDTableAlignments(line, columnCount) {
  var cells = renderMDTableCells(line);
  var valid = cells.length >= 1 && cells.every(function(cell){ return /^:?-{3,}:?$/.test(cell.replace(/\s+/g, '')); });
  if (!valid) return null;
  while (cells.length < columnCount) cells.push('---');
  return cells.slice(0, columnCount).map(function(cell){
    cell = cell.replace(/\s+/g, '');
    if (cell.charAt(0) === ':' && cell.charAt(cell.length - 1) === ':') return 'center';
    if (cell.charAt(cell.length - 1) === ':') return 'right';
    return 'left';
  });
}
function renderMDTable(headerLine, separatorLine, bodyLines) {
  var headers = renderMDTableCells(headerLine);
  var aligns = renderMDTableAlignments(separatorLine, headers.length) || [];
  var rows = (bodyLines || []).map(renderMDTableCells).filter(function(cells){ return cells.length; });
  function cellStyle(index) {
    var align = aligns[index] || 'left';
    return align === 'left' ? '' : ' style="text-align:' + align + '"';
  }
  return '<div class="md-table-wrap"><table class="md-table"><thead><tr>'
    + headers.map(function(cell, idx){ return '<th' + cellStyle(idx) + '>' + renderMDInline(cell) + '</th>'; }).join('')
    + '</tr></thead><tbody>'
    + rows.map(function(cells){
      while (cells.length < headers.length) cells.push('');
      return '<tr>' + cells.slice(0, headers.length).map(function(cell, idx){
        return '<td' + cellStyle(idx) + '>' + renderMDInline(cell) + '</td>';
      }).join('') + '</tr>';
    }).join('')
    + '</tbody></table></div>';
}
function renderMD(s) {
  var lines = String(s == null ? '' : s).replace(/\r\n?/g, '\n').split('\n');
  var parts = [];
  var pending = [];
  function flushPending() {
    if (!pending.length) return;
    parts.push(pending.map(renderMDInline).join('<br>'));
    pending = [];
  }
  for (var i = 0; i < lines.length; i += 1) {
    var line = lines[i] || '';
    var next = lines[i + 1] || '';
    var headerCells = line.indexOf('|') !== -1 ? renderMDTableCells(line) : [];
    var alignments = headerCells.length >= 2 && next.indexOf('|') !== -1 ? renderMDTableAlignments(next, headerCells.length) : null;
    if (alignments) {
      flushPending();
      var tableRows = [];
      i += 2;
      while (i < lines.length && String(lines[i] || '').indexOf('|') !== -1 && String(lines[i] || '').trim()) {
        tableRows.push(lines[i]);
        i += 1;
      }
      i -= 1;
      parts.push(renderMDTable(line, next, tableRows));
    } else {
      pending.push(line);
    }
  }
  flushPending();
  return parts.join('<br>');
}
function guidedRenderPassageReferencePrompt(question) {
  if (!question || guidedQuestionPolicyType(question) !== 'passage_reference') return '';
  var raw = String(question.prompt || '').trim();
  var match = raw.match(/^Which passage is this\?\s*\n\s*---\*\*(.+?)\*\*---\s*([\s\S]*)$/);
  if (!match) return '';
  return '<div class="guided-passage-reference-prompt">'
    + '<div class="guided-passage-reference-kicker">Which passage is this?</div>'
    + '<div class="guided-passage-reference-title">' + renderMD(match[1]) + '</div>'
    + '<div class="guided-passage-reference-summary">' + renderMD(match[2]) + '</div>'
    + '</div>';
}
function guidedRenderPromptBlankLine() {
  return '<span class="guided-inline-blank" aria-label="blank"></span>';
}
function guidedRenderQuestionPrompt(question) {
  if (!question) return '';
  var passagePrompt = guidedRenderPassageReferencePrompt(question);
  if (passagePrompt) return passagePrompt;
  var html = question.promptHtml || renderMD(question.prompt || '');
  if (guidedNormalizeChallengeInteractionType(question.interactionType) !== 'cloze_drag') return html;
  return html.replace(/_{3,}/g, guidedRenderPromptBlankLine());
}

// ── CARD LINK POPUP ──
var cardlinkShowing = 'q';
var cardlinkCard    = null;
var cardlinkDeckName = '';
var cardlinkDeckId   = null;
var cardlinkLockInfo = null;
function getCardLinkLockInfo(deck, card) {
  if (!deck || !card || authorMode) return { locked: false, cardLevel: 1, unlockedLevel: 40 };
  var cardLevel = Number(card.level || 1) || 1;
  var unlockedLevel = Number(getDeckUnlockedLevel(deck.id) || 1) || 1;
  return {
    locked: cardLevel > unlockedLevel,
    cardLevel: cardLevel,
    unlockedLevel: unlockedLevel,
    deckName: deck.name || 'this deck'
  };
}
function openCardlink(deckId, cardId, cardUid) {
  var linkTarget = resolveCardLinkTarget({ type:'card', deckId:deckId, cardId:cardId, cardUid:cardUid });
  var d = linkTarget ? linkTarget.deck : findDeckByIdLoose(deckId);
  if (!d) return;
  var c = linkTarget ? linkTarget.card : findCardInDeckByIdLoose(d, cardId);
  if (!c) return;
  cardlinkCard     = c;
  cardlinkDeckId   = d.id;
  cardlinkDeckName = d.name;
  cardlinkShowing  = 'q';
  cardlinkLockInfo = getCardLinkLockInfo(d, c);
  renderCardlinkBox();
  document.getElementById('cardlink-overlay').classList.add('open');
  studyDeckOpenDialog('cardlink-overlay', { focusSelector: '.cardlink-flip' });
}
function renderCardlinkBox() {
  document.getElementById('cl-deck').textContent = cardlinkDeckName;
  document.getElementById('cl-side').textContent = cardlinkShowing === 'q' ? 'Front' : 'Back';
  var lockEl = document.getElementById('cl-lock');
  if (lockEl) {
    if (cardlinkLockInfo && cardlinkLockInfo.locked) {
      lockEl.textContent = 'Reference preview - direct study unlocks at ' + cardlinkLockInfo.deckName + ' Level ' + cardlinkLockInfo.cardLevel;
      lockEl.classList.add('show');
    } else {
      lockEl.textContent = '';
      lockEl.classList.remove('show');
    }
  }
  document.getElementById('cl-text').innerHTML   = renderMD(cardlinkShowing === 'q' ? cardlinkCard.q : cardlinkCard.a);
}
function cardlinkFlip() {
  cardlinkShowing = cardlinkShowing === 'q' ? 'a' : 'q';
  renderCardlinkBox();
}
function closeCardlink() {
  document.getElementById('cardlink-overlay').classList.remove('open');
  studyDeckCloseDialog('cardlink-overlay');
  cardlinkCard = null; cardlinkDeckId = null; cardlinkLockInfo = null;
}
function goToLinkedCard() {
  var targetCard = cardlinkCard;
  var targetDeckId = cardlinkDeckId;
  // Switch to the target deck
  var d = findDeckByIdLoose(targetDeckId);
  if (!d) return;
  var lockInfo = getCardLinkLockInfo(d, targetCard);
  if (lockInfo.locked) {
    showXpToast('Locked: reach ' + lockInfo.deckName + ' Level ' + lockInfo.cardLevel + ' to study this card directly.', 3600);
    cardlinkLockInfo = lockInfo;
    renderCardlinkBox();
    return;
  }
  closeCardlink();
  activeDeck = d;
  filterTags=[]; filterExcludeTags=[]; filterFav=false; filterMore=false; filterLevel=""; filterSearch=""; filterTagsExpanded=false;
  deckOrder='learning'; deckFace='front'; fcAutoAdvance=false;
  // Build flashcard session for that deck, find the target card index
  var base = d.cards.slice();
  if (!startFlashcardSession(base, targetCard.id)) {
    showXpToast('No cards are available in this deck.', 1600);
    return;
  }
  fcFlipped = false;
  document.getElementById('fc-deck-name').textContent = d.name;
  // Jump instantly to the right card without animation
  var el = document.getElementById('card-3d');
  el.style.transition = 'none';
  el.classList.remove('flipped');
  el.getBoundingClientRect();
  el.style.transition = '';
  renderFC();
  show('flashcard');
}
function openExternalLink(url) {
  window.open(url, '_blank', 'noopener');
}

