function checkStreakMilestones() {
  if (!gd.claimedMilestones) gd.claimedMilestones = [];
  if (!gd.badges) gd.badges = [];
  if (!gd.ownedTitles) gd.ownedTitles = [];
  var representedStreakDays = gd.claimedMilestones.reduce(function(max, days){
    return Math.max(max, Number(days) || 0);
  }, 0);
  STREAK_MILESTONES.forEach(function(m) {
    var hasMilestoneBadge = !!(m.badgeId && gd.badges.includes(m.badgeId));
    var hasMilestoneTitle = !!(m.titleId && gd.ownedTitles.includes(m.titleId));
    if (hasMilestoneBadge || hasMilestoneTitle) representedStreakDays = Math.max(representedStreakDays, m.days || 0);
  });
  var newBadges = [];
  STREAK_MILESTONES.forEach(function(m) {
    if (gd.streak >= m.days && !gd.claimedMilestones.includes(m.days)) {
      var alreadyRepresented = m.days <= representedStreakDays || (m.badgeId && gd.badges.includes(m.badgeId)) || (m.titleId && gd.ownedTitles.includes(m.titleId));
      gd.claimedMilestones.push(m.days);
      if (alreadyRepresented) {
        if (m.badgeId && !gd.badges.includes(m.badgeId)) gd.badges.push(m.badgeId);
        if (m.titleId && !gd.ownedTitles.includes(m.titleId)) gd.ownedTitles.push(m.titleId);
        return;
      }
      // Award shekels
      if (m.shekels) { gd.shekels = (gd.shekels||0) + m.shekels; }
      // Award freezes (up to max)
      if (m.freezes) {
        var maxF = getMaxFreezes();
        gd.freezes = Math.min(maxF, (gd.freezes||0) + m.freezes);
      }
      // Award badge
      if (m.badgeId && !gd.badges.includes(m.badgeId)) {
        gd.badges.push(m.badgeId);
        newBadges.push(m.badgeId);
      }
      // Award exclusive title
      if (m.titleId) {
        if (!gd.ownedTitles) gd.ownedTitles = [];
        if (!gd.ownedTitles.includes(m.titleId)) gd.ownedTitles.push(m.titleId);
      }
      // Toast
      var msg = '🏆 ' + m.days + '-day streak! +' + m.shekels + ' 🪙';
      if (m.exclusiveTitle) msg += ' · "' + m.exclusiveTitle + '" unlocked!';
      setTimeout(function(){ showXpToast(msg); }, 500);
    }
  });
  return newBadges;
}

// ── FREEZE CAP ──
function getMaxFreezes() {
  var lv = xpLevel(gd.xp);
  var s  = gd.streak || 0;
  if (lv >= 15 || s >= 180) return 5;
  if (lv >= 10 || s >= 90)  return 4;
  if (lv >= 5  || s >= 30)  return 3;
  return 2;
}

