  nodeType = guidedNormalizeQuestionNode(nodeType || 'spiral_review') || 'spiral_review';
  var footprint = guidedResolveNodeFootprint(nodeType, { type: nodeType, categoryId: 'mixed' });
  if (maxCount != null) footprint = guidedNodeFootprintMergeEntry(footprint, { maxTotal: maxCount });
  var activeSelected = {};
  (run.selectedCategoryIds || []).forEach(function(id){ activeSelected[id] = true; });
