  if (session.nodeType === 'challenge') return GUIDED_SCREEN_CHALLENGE;
  if (session.nodeType === 'checkpoint') return GUIDED_SCREEN_CHECKPOINT;
  if (session.nodeType === 'spiral_review') return GUIDED_SCREEN_SPIRAL_REVIEW;
  return GUIDED_SCREEN_LEARN;
