	  var item = question && question.scholarItemId ? guidedFindScholarPoolItem(run, question.scholarItemId) : null;
	  if (!item) return { creditAwarded: false, alreadyCredited: false };
	  item.seenCount = (item.seenCount || 0) + 1;
	  item.lastSeenAt = Date.now();
	  if (!Array.isArray(item.creditedNodeIds)) item.creditedNodeIds = [];
	  var nodeId = question.scholarNodeId
	    || (guidedState.scholarSession && guidedState.scholarSession.nodeId)
	    || (guidedState.currentResults && guidedState.currentResults.nodeId)
	    || '';
