	  var alreadyCredited = false;
	  if (correct) {
	    if (nodeId) {
	      alreadyCredited = item.creditedNodeIds.indexOf(nodeId) !== -1;
	      if (!alreadyCredited) {
	        item.creditedNodeIds.push(nodeId);
	        item.correctCount = (item.correctCount || 0) + 1;
	        creditAwarded = true;
	      }
	    } else {
	      item.correctCount = (item.correctCount || 0) + 1;
	      creditAwarded = true;
	    }
	  }
	  item.due = !correct || (item.correctCount || 0) < 2;
	  return { creditAwarded: creditAwarded, alreadyCredited: alreadyCredited };
