	    var creditedCount = results.filter(function(item){ return item.creditAwarded; }).length;
	    var summary = guidedState.currentResults || {};
	    summary.scholar = {
	      status: 'completed',
	      availableCount: scholarSession.items.length,
	      completedCount: results.length,
	      correctCount: correctCount,
	      creditedCount: creditedCount
	    };
    guidedState.currentResults = summary;
    guidedState.scholarAvailable = [];
    guidedState.scholarSession = null;
    guidedState.screen = GUIDED_SCREEN_NODE_SUMMARY;
