  var edit = guidedAuthorDraftPatch && guidedAuthorDraftPatch.cardEdits ? guidedAuthorDraftPatch.cardEdits[key] : null;
  if (!edit) return card;
  var copy = guidedAuthorClone(card);
  if (Object.prototype.hasOwnProperty.call(edit, 'q')) copy.q = edit.q;
  if (Object.prototype.hasOwnProperty.call(edit, 'a')) copy.a = edit.a;
  ['helperCue','rememberThis','whyThisMatters','teachingPrompt','commonMistake'].forEach(function(field){
    if (Object.prototype.hasOwnProperty.call(edit, field)) copy[field] = edit[field];
  });
  if (edit.notes && typeof edit.notes === 'object' && Array.isArray(GUIDED_LEARN_NOTE_LAYERS)) {
    copy.notes = Array.isArray(copy.notes) ? copy.notes.slice() : [];
    Object.keys(edit.notes).forEach(function(layerKey){
      var noteEdit = edit.notes[layerKey];
      if (!noteEdit) return;
      var spec = guidedAuthorLayerSpecByKey(layerKey);
      var note = spec ? guidedFindCardNoteByLabels(copy, spec.labels) : null;
      if (!note) {
        note = {
          id: 'guided_' + layerKey,
          label: noteEdit.label || (spec && spec.label) || layerKey,
          text: ''
        };
        copy.notes.push(note);
      }
      if (Object.prototype.hasOwnProperty.call(noteEdit, 'label')) note.label = noteEdit.label;
      if (Object.prototype.hasOwnProperty.call(noteEdit, 'text')) note.text = noteEdit.text;
    });
  }
