    report.totals.cardsWithContext += categoryReport.studyLayerCounts.context;
    report.totals.cardsWithScholarlyNote += categoryReport.studyLayerCounts.scholar;
    report.totals.cardsWithMoralProblem += categoryReport.studyLayerCounts.problem;
    report.totals.cardsWithAnyStudyLayer += categoryReport.studyLayerCounts.any;
    report.totals.cardsWithAllCoreLayers += categoryReport.studyLayerCounts.allCore;
    report.totals.authoredLearnCards += categoryReport.authoredLearnCards;
    report.totals.authoredLearnQuestions += categoryReport.authoredLearnQuestions;
    report.totals.fallbackLearnCards += categoryReport.fallbackLearnCards;
