    report.totals.weakHelperCards += categoryReport.weakHelperCards;
    report.totals.cardsWithReferenceSlot += categoryReport.cardsWithReferenceSlot;
    report.totals.cardsWithContentSlot += categoryReport.cardsWithContentSlot;
    report.totals.cardsWithEvidenceSlot += categoryReport.cardsWithEvidenceSlot;
    report.totals.cardsMeetingV1SlotPlan += categoryReport.cardsMeetingV1SlotPlan;
