function guidedAuthorValidateGuidedNodePolicy(policy, report) {
  if (!policy) return;
  if (typeof policy !== 'object' || Array.isArray(policy)) {
    report.issues.push(guidedAuthorSidecarIssue('error', 'node_policy_not_object', 'guidedNodePolicy must be an object.', ''));
    return;
  }
  function looksLikeNodeLayer(layer) {
    if (!layer || typeof layer !== 'object' || Array.isArray(layer)) return false;
    if (layer.nodes && typeof layer.nodes === 'object') return true;
    return Object.keys(layer).some(function(key){ return !!guidedNormalizeQuestionNode(key); });
  }
  function validateLayer(layer, label) {
    if (!looksLikeNodeLayer(layer)) return;
    var nodes = guidedNodePolicyLayerNodes(layer);
    Object.keys(nodes || {}).forEach(function(nodeType){
      if (!guidedNormalizeQuestionNode(nodeType)) {
        report.issues.push(guidedAuthorSidecarIssue('error', 'node_policy_unknown_node', 'guidedNodePolicy has an unknown node name.', label + ': ' + nodeType));
        return;
      }
      Object.keys(nodes[nodeType] || {}).forEach(function(policyType){
        if (!guidedNodePolicySpec(policyType)) {
          report.issues.push(guidedAuthorSidecarIssue('error', 'node_policy_unknown_type', 'guidedNodePolicy has an unknown question type.', label + ': ' + policyType));
        }
        var rawEntry = nodes[nodeType][policyType];
        var hasLimit = guidedNodePolicyEntryHasLimit(rawEntry, 'min') || guidedNodePolicyEntryHasLimit(rawEntry, 'max');
        var rawState = rawEntry && typeof rawEntry === 'object' && !Array.isArray(rawEntry)
          ? (rawEntry.state || rawEntry.status || rawEntry.mode || rawEntry.value)
          : rawEntry;
        if (!hasLimit && !guidedNodePolicyNormalizeState(rawState, false)) {
          report.issues.push(guidedAuthorSidecarIssue('error', 'node_policy_unknown_state', 'guidedNodePolicy has an unknown state.', label + ': ' + nodeType + ' / ' + policyType));
        }
        if (!hasLimit && guidedNodePolicyNormalizeState(rawState, false)) {
          report.issues.push(guidedAuthorSidecarIssue('warning', 'node_policy_legacy_state', 'guidedNodePolicy should use count-only min/max rows.', label + ': ' + nodeType + ' / ' + policyType));
        }
        if (guidedNodePolicyEntryHasLimit(rawEntry, 'min') && rawEntry.min !== '' && rawEntry.minimum !== '' && guidedNodePolicyNormalizeLimit(rawEntry.min != null ? rawEntry.min : rawEntry.minimum) == null) {
          report.issues.push(guidedAuthorSidecarIssue('error', 'node_policy_bad_limits', 'guidedNodePolicy min must be a number.', label + ': ' + nodeType + ' / ' + policyType));
        }
        if (guidedNodePolicyEntryHasLimit(rawEntry, 'max') && rawEntry.max !== '' && rawEntry.maximum !== '' && guidedNodePolicyNormalizeLimit(rawEntry.max != null ? rawEntry.max : rawEntry.maximum) == null) {
          report.issues.push(guidedAuthorSidecarIssue('error', 'node_policy_bad_limits', 'guidedNodePolicy max must be a number.', label + ': ' + nodeType + ' / ' + policyType));
        }
      });
    });
  }
  if (policy.nodes) validateLayer(policy, 'guidedNodePolicy');
  validateLayer(policy.global, 'guidedNodePolicy.global');
  Object.keys(policy.decks || {}).forEach(function(scopeKey){ validateLayer(policy.decks[scopeKey], 'guidedNodePolicy.decks.' + scopeKey); });
  Object.keys(policy.categories || {}).forEach(function(categoryId){ validateLayer(policy.categories[categoryId], 'guidedNodePolicy.categories.' + categoryId); });
}
