  validateLayer(footprint.global, 'guidedNodeFootprint.global');
  Object.keys(footprint.decks || {}).forEach(function(scopeKey){ validateLayer(footprint.decks[scopeKey], 'guidedNodeFootprint.decks.' + scopeKey); });
