function guidedAuthorFirstExampleUid(source, keys) {
  source = source || {};
  keys = keys || [];
  for (var i = 0; i < keys.length; i += 1) {
    var items = Array.isArray(source[keys[i]]) ? source[keys[i]] : [];
    for (var j = 0; j < items.length; j += 1) {
      var uid = String(items[j] && (items[j].uid || items[j].id || '') || '').trim();
      if (uid) return uid;
    }
  }
  return '';
}
function guidedAuthorFirstQuestionExampleUid(source, keys, categoryId, interaction) {
  var records = typeof guidedAuthorQuestionBrowserRecords === 'function' ? guidedAuthorQuestionBrowserRecords() : [];
  var lookup = {};
  (records || []).forEach(function(record){
    var uid = String(record && record.cardUid || '').trim();
    if (!uid) return;
    if (categoryId && String(record.categoryId || record.categoryLabel || '') !== String(categoryId)) return;
    if (interaction && interaction !== 'all' && String(record.interaction || '') !== String(interaction)) return;
    lookup[uid] = true;
  });
  source = source || {};
  keys = keys || [];
  for (var i = 0; i < keys.length; i += 1) {
    var items = Array.isArray(source[keys[i]]) ? source[keys[i]] : [];
    for (var j = 0; j < items.length; j += 1) {
      var uid = String(items[j] && (items[j].uid || items[j].id || '') || '').trim();
      if (uid && lookup[uid]) return uid;
    }
  }
  return '';
}
function guidedAuthorNeedsWorkOpenQuestions(cardUid, categoryId, interaction) {
  var state = guidedAuthorQuestionBrowserEnsureState();
  state.view = 'authored';
  state.category = categoryId ? String(categoryId) : 'all';
  state.stage = 'all';
  state.card = 'all';
  state.interaction = interaction ? String(interaction) : 'all';
  state.search = String(cardUid || '');
  state.selectedKey = '';
  state.listLimit = GUIDED_AUTHOR_LIST_WINDOW_INITIAL;
  var records = guidedAuthorQuestionBrowserRecords();
  guidedAuthorQuestionBrowserCascadeOptions(records);
  var filtered = guidedAuthorQuestionBrowserFilterRecords(records);
  if (filtered.length) {
    state.selectedKey = filtered[0].key;
  } else if (cardUid) {
    state.search = '';
    state.category = categoryId ? String(categoryId) : 'all';
    state.interaction = interaction ? String(interaction) : 'all';
    filtered = guidedAuthorQuestionBrowserFilterRecords(records);
    if (filtered.length) state.selectedKey = filtered[0].key;
  }
  guidedAuthorSetTab('questions');
  setTimeout(function(){
    var selected = document.querySelector('.guided-author-question-row.is-selected') || document.querySelector('.guided-author-question-browser-card');
    if (selected && selected.scrollIntoView) selected.scrollIntoView({ block: 'center', behavior: studyDeckPrefersReducedMotion() ? 'auto' : 'smooth' });
    if (!filtered.length && typeof showXpToast === 'function') showXpToast('No matching question is loaded yet. Check Sidecars if this deck needs to be saved as active.');
    else if (cardUid && !state.search && typeof showXpToast === 'function') showXpToast('That exact card is not loaded in Questions yet, so the deck question list is open instead.');
  }, 80);
}
