  if (state.card !== 'all') activeSummary.push({ label: 'Card', value: filterOptionLabel(cardOptions, state.card), type: 'card' });
  if (state.evidence !== 'all') activeSummary.push({ label: 'Evidence', value: filterOptionLabel(evidenceOptions, state.evidence), type: 'evidence' });
  if (state.issue !== 'all') activeSummary.push({ label: 'Issue', value: filterOptionLabel(issueOptions, state.issue), type: 'issue' });
