    + '<div class="guided-author-question-filter-actions"><button type="button" class="btn btn-soft" onclick="guidedAuthorBriefingBrowserClearFilters()" ' + (hasActiveFilters ? '' : 'disabled') + '>Clear filters</button></div>'
    + renderFilterActiveSummary(activeSummary, 'guidedAuthorBriefingBrowserClearFilters()')
