function guidedAuthorRenderActiveTab(run) {
  guidedAuthorActiveTab = guidedAuthorNormalizeTab(guidedAuthorActiveTab);
  var report = null;
  var qualityReport = null;
  var typeCoverageReport = null;
  var learnCoverageReport = null;
  if (guidedAuthorActiveTab === 'needsWork' || guidedAuthorActiveTab === 'diagnostics') {
    report = guidedAuthorBuildMetadataReport();
    qualityReport = report.challengeQuality || guidedAuthorBuildChallengeQualityReport();
    typeCoverageReport = report.challengeTypeCoverage || guidedAuthorBuildChallengeTypeCoverageReport();
    learnCoverageReport = report.learnContentCoverage || guidedAuthorBuildLearnContentCoverageReport();
  }
  if (guidedAuthorActiveTab === 'needsWork') return guidedAuthorRenderNeedsWorkTab(run, report, qualityReport, typeCoverageReport, learnCoverageReport);
  if (guidedAuthorActiveTab === 'questions') return guidedAuthorRenderQuestionBrowserTab();
  if (guidedAuthorActiveTab === 'nodes') return guidedAuthorRenderNodesTab();
  if (guidedAuthorActiveTab === 'rewards') return guidedAuthorRenderRewardsTab();
  if (guidedAuthorActiveTab === 'briefings') return guidedAuthorRenderBriefingBrowserTab();
  if (guidedAuthorActiveTab === 'coverage') return guidedAuthorRenderCoverageTab();
  if (guidedAuthorActiveTab === 'timeline') {
    return typeof studyDeckTimelineRenderAuthorHealth === 'function'
      ? studyDeckTimelineRenderAuthorHealth()
      : '<div class="guided-card guided-hero-card"><div class="guided-section-kicker">Timeline</div><div class="guided-card-title">Timeline checker is not loaded.</div><div class="guided-card-sub">Reload StudyDeck and open this tab again.</div></div>';
  }
  if (guidedAuthorActiveTab === 'maps') return guidedAuthorRenderMapsTab();
  if (guidedAuthorActiveTab === 'contentQa') return guidedAuthorRenderContentQaTab();
  if (guidedAuthorActiveTab === 'reviewEdits') return guidedAuthorRenderReviewEditsTab();
  if (guidedAuthorActiveTab === 'diagnostics') return guidedAuthorRenderDiagnosticsTab(run, report, qualityReport, typeCoverageReport, learnCoverageReport);
  guidedAuthorActiveTab = 'sidecars';
  return guidedAuthorRenderSidecarsTab();
}
