function guidedFormatPlainList(items) {
  var out = (items || []).filter(Boolean).map(function(item){ return String(item); });
  if (!out.length) return '';
  if (out.length === 1) return out[0];
  if (out.length === 2) return out[0] + ' and ' + out[1];
  return out.slice(0, -1).join(', ') + ', and ' + out[out.length - 1];
}
function guidedCategoryIdSet(ids) {
  var out = {};
  guidedNormalizeCategoryIds(ids || []).forEach(function(id){ out[id] = true; });
  return out;
}
function guidedSameCategorySet(left, right) {
  var a = guidedCategoryIdSet(left);
  var b = guidedCategoryIdSet(right);
  var aKeys = Object.keys(a);
  var bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;
  return aKeys.every(function(id){ return !!b[id]; });
}
function guidedCategoryLabelsForIds(ids) {
  return guidedNormalizeCategoryIds(ids || []).map(guidedResolveCategoryById).filter(Boolean).map(function(cat){ return cat.label; });
}
function guidedDescribeCategoryDelta(addIds, removeIds) {
  var bits = [];
  var addLabels = guidedCategoryLabelsForIds(addIds);
  var removeLabels = guidedCategoryLabelsForIds(removeIds);
  if (addLabels.length) bits.push('Add ' + guidedFormatPlainList(addLabels));
  if (removeLabels.length) bits.push('Remove ' + guidedFormatPlainList(removeLabels));
  return bits.join('. ');
}
function guidedGetSetupSaveState(run, selectedIds) {
  if (!run) return null;
  var selected = guidedNormalizeCategoryIds(selectedIds || []).filter(function(id){ return !!guidedResolveCategoryById(id); });
  var current = guidedNormalizeCategoryIds(run.selectedCategoryIds || []);
  var planned = guidedGetPlannedCategoryIds(run);
  var pendingSummary = guidedGetPendingChangeSummary(run);
  var addIds = selected.filter(function(id){ return current.indexOf(id) === -1; });
  var removeIds = current.filter(function(id){ return selected.indexOf(id) === -1; });
  var selectedMatchesPlanned = guidedSameCategorySet(selected, planned);
  var selectedMatchesCurrent = guidedSameCategorySet(selected, current);
  if (!selectedMatchesPlanned) {
    return {
      key: selectedMatchesCurrent ? 'clear_pending' : 'unsaved',
      buttonLabel: selectedMatchesCurrent ? 'Clear saved change' : 'Save for next bracket',
      kicker: selectedMatchesCurrent ? 'Unsaved change' : 'Not saved yet',
      title: selectedMatchesCurrent ? 'Save to cancel the next-bracket change' : 'Save this list for the next bracket',
      sub: selectedMatchesCurrent
        ? 'This list matches the bracket you are in now. Saving will remove the saved change.'
        : guidedDescribeCategoryDelta(addIds, removeIds) + '. The bracket you are in now will not change.'
    };
  }
  if (pendingSummary) {
    return {
      key: 'saved_pending',
      buttonLabel: 'Return to path',
      kicker: 'Saved for next bracket',
      title: 'Next-bracket change is saved',
      sub: pendingSummary.text + '. The bracket you are in now will not change.'
    };
  }
  return {
    key: 'no_changes',
    buttonLabel: 'Return to path',
    kicker: 'No pending changes',
    title: 'No category changes saved',
    sub: 'Change a category above, or return to the path.'
  };
}
function guidedBuildSetupPreviewCopy(selectedCategories, run) {
  var labels = (selectedCategories || []).map(function(cat){ return cat.label; }).filter(Boolean);
  if (!labels.length) {
    return {
      title: 'Choose at least one category',
      sub: run
        ? 'The next bracket needs at least one category before you can save.'
        : 'Pick one or more available categories, then start Guided Learning.'
    };
  }
  var firstLabels = labels.slice(0, 3);
  var firstText = guidedFormatPlainList(firstLabels);
  var extraCount = Math.max(0, labels.length - firstLabels.length);
  if (run) {
    return {
      title: extraCount ? 'Next bracket starts with ' + firstText : 'Next bracket uses ' + firstText,
      sub: extraCount
        ? extraCount + ' more ' + (extraCount === 1 ? 'category stays' : 'categories stay') + ' selected and will appear in a later bracket.'
        : 'Saving uses this list for the next bracket. The bracket you are in now will not change.'
    };
  }
  return {
    title: 'First bracket starts with ' + firstText,
    sub: extraCount
      ? extraCount + ' more ' + (extraCount === 1 ? 'category stays' : 'categories stay') + ' selected and will appear in a later bracket.'
      : 'Start Guided Learning when this looks right.'
  };
}
function guidedGetSetupEntryCopy(run) {
  if (!run) {
    return {
      topTitle: 'Build Your Guided Path',
      title: 'Pick what to study first',
      sub: 'Choose one or more categories. If more than three are selected, the extra categories stay selected for later brackets.',
      statePill: 'New run'
    };
  }
  var bracketComplete = guidedIsCurrentBracketComplete(run);
  var pendingSummary = guidedGetPendingChangeSummary(run);
  if (bracketComplete) {
    return {
      topTitle: 'Manage Guided Categories',
      title: 'Choose the next bracket',
      sub: pendingSummary
        ? 'This bracket is complete, and a category change is already saved for what comes next.'
        : 'This bracket is complete. Save changes only if the next bracket should use a different set of categories.',
      statePill: 'Bracket complete'
    };
  }
  if (pendingSummary) {
    return {
      topTitle: 'Manage Guided Categories',
      title: 'Review the saved next-bracket change',
      sub: 'Your current bracket stays the same. The saved list will be used when the next bracket is built.',
      statePill: 'Changes queued'
    };
  }
  return {
    topTitle: 'Manage Guided Categories',
    title: 'Plan the next bracket',
    sub: 'Changing this list will not interrupt the bracket you are in now. Save only if the next bracket should use a different set of categories.',
    statePill: 'Current bracket active'
  };
}
function guidedPreviewNextBracketCategoryIds(run, selectedIds) {
  selectedIds = guidedNormalizeCategoryIds(selectedIds || (run ? guidedGetPlannedCategoryIds(run) : []));
  if (!selectedIds.length) return [];
  var currentIds = run ? guidedNormalizeCategoryIds(run.selectedCategoryIds || []) : [];
  var priorityIds = run
    ? selectedIds.filter(function(id){ return currentIds.indexOf(id) === -1 || (run.pendingCategoryAdds || []).indexOf(id) !== -1; })
    : [];
  return guidedPickBracketCategoryIds(selectedIds, {
    rotationCursor: run ? (run.categoryRotationCursor || 0) : 0,
    priorityCategoryIds: priorityIds
  }).categoryIds || [];
}
function guidedPreviewNextBracketCategories(run, selectedIds) {
  return guidedPreviewNextBracketCategoryIds(run, selectedIds).map(guidedResolveCategoryById).filter(Boolean);
}
function guidedRenderSmallCategoryChips(categories) {
  categories = categories || [];
  if (!categories.length) return '<span class="guided-rotation-empty">None</span>';
  return categories.map(function(cat){
    return '<span class="guided-rotation-chip"><span style="background:' + guidedEsc(cat.color || 'var(--gold)') + '"></span>' + guidedEsc(cat.label) + '</span>';
  }).join('');
}
function guidedGetSetupRotationPreview(selectedCategories, run) {
  selectedCategories = selectedCategories || [];
  var selectedIds = selectedCategories.map(function(cat){ return cat && cat.id; }).filter(Boolean);
  if (selectedIds.length <= 1) return null;
  var nextIds = guidedPreviewNextBracketCategoryIds(run, selectedIds);
  var nextSet = {};
  nextIds.forEach(function(id){ nextSet[id] = true; });
  var waitingIds = selectedIds.filter(function(id){ return !nextSet[id]; });
  return {
    selectedCount: selectedIds.length,
    maxCount: GUIDED_MAX_CATEGORIES_PER_BRACKET,
    bracketLabel: run ? 'Next bracket' : 'First bracket',
    next: nextIds.map(guidedResolveCategoryById).filter(Boolean),
    waiting: waitingIds.map(guidedResolveCategoryById).filter(Boolean),
    allFit: waitingIds.length === 0
  };
}
function guidedRenderSetupRotationPreview(preview) {
  if (!preview) return '';
  var bracketLabel = preview.bracketLabel || 'Next bracket';
  var title = preview.allFit
    ? 'All selected categories fit in the ' + bracketLabel.toLowerCase()
    : bracketLabel + ' shows ' + preview.next.length + ' of ' + preview.selectedCount + ' selected categories';
  var sub = preview.allFit
    ? 'No category has to wait; they can all appear together.'
    : 'Coming-later categories are not removed. They stay selected and appear in later brackets.';
  return '<div class="guided-rotation-preview">'
    + '<div class="guided-section-kicker">Category rotation</div>'
    + '<div class="guided-rotation-title">' + guidedEsc(title) + '</div>'
    + '<div class="guided-rotation-sub">' + guidedEsc(sub) + '</div>'
    + '<div class="guided-rotation-row"><strong>' + guidedEsc(bracketLabel) + '</strong><div>' + guidedRenderSmallCategoryChips(preview.next) + '</div></div>'
    + (preview.waiting.length ? '<div class="guided-rotation-row"><strong>Coming later</strong><div>' + guidedRenderSmallCategoryChips(preview.waiting) + '</div></div>' : '')
    + '</div>';
}
function guidedRenderPathRotationBanner(run) {
  if (!run) return '';
  var activeIds = guidedNormalizeCategoryIds(run.selectedCategoryIds || []);
  var currentIds = (run.categories || []).map(function(cat){ return cat && cat.id; }).filter(Boolean);
  if (activeIds.length <= currentIds.length || activeIds.length <= GUIDED_MAX_CATEGORIES_PER_BRACKET) return '';
  var currentSet = {};
  currentIds.forEach(function(id){ currentSet[id] = true; });
  var waiting = activeIds.filter(function(id){ return !currentSet[id]; }).map(guidedResolveCategoryById).filter(Boolean);
  if (!waiting.length) return '';
  return '<div class="guided-card guided-rotation-banner">'
    + '<div class="guided-section-kicker">Study rotation</div>'
    + '<div class="guided-card-sub">Showing ' + guidedEsc(String(currentIds.length)) + ' of ' + guidedEsc(String(activeIds.length)) + ' selected categories here. The rest stay selected for later brackets.</div>'
    + '<div class="guided-rotation-row"><strong>Coming later</strong><div>' + guidedRenderSmallCategoryChips(waiting) + '</div></div>'
    + '</div>';
}
function renderGuidedSetupScreen() {
  var run = guidedGetRun();
  var resolved = guidedResolveCategories();
  var selected = guidedState.setupSelected || [];
  var selectedAvailable = resolved.filter(function(cat){ return selected.indexOf(cat.id) !== -1 && cat.available; });
  var availableCategories = resolved.filter(function(cat){ return cat.available; });
  var unavailableCategories = resolved.filter(function(cat){ return !cat.available; });
  var unavailableLabels = unavailableCategories.map(function(cat){ return cat.label; });
  var hasSelection = selectedAvailable.length > 0;
  var previewCopy = guidedBuildSetupPreviewCopy(selectedAvailable, run);
  var entryCopy = guidedGetSetupEntryCopy(run);
  var rotationPreview = guidedGetSetupRotationPreview(selectedAvailable, run);
  var setupSaveState = run ? guidedGetSetupSaveState(run, selected.map(String)) : null;
  var selectionText = selectedAvailable.length + ' selected';
  var availableText = availableCategories.length + ' available';
  var primaryAction = run && setupSaveState && (setupSaveState.key === 'no_changes' || setupSaveState.key === 'saved_pending')
    ? 'showGuidedPathMap()'
    : (run ? 'guidedSavePendingCategoryChanges()' : 'guidedCreatePrototypeRun()');
  var primaryLabel = run && setupSaveState ? setupSaveState.buttonLabel : 'Begin Guided Journey';
  return ''
    + '<div class="guided-shell guided-setup-shell">'
    + '<div class="top-bar"><button class="back-btn" onclick="' + (run ? 'showGuidedOptions()' : 'showHome()') + '">←</button><span class="top-title" style="flex:1">' + guidedEsc(entryCopy.topTitle) + '</span></div>'
    + '<div class="guided-card guided-hero-card">'
    +   '<div class="guided-kicker">Guided setup</div>'
    +   '<div class="guided-card-title">' + guidedEsc(entryCopy.title) + '</div>'
    +   '<div class="guided-card-sub">' + guidedEsc(entryCopy.sub) + '</div>'
    +   '<div class="guided-setup-status-row">'
    +     '<span>' + guidedEsc(entryCopy.statePill) + '</span>'
    +     '<span>' + guidedEsc(selectionText) + '</span>'
    +     '<span>' + guidedEsc(availableText) + '</span>'
    +   '</div>'
    + '</div>'
    + '<div class="guided-setup-section-head">'
    +   '<div><strong>Study categories</strong><span>Tap a row to include or remove it.</span></div>'
    +   '<em>' + guidedEsc(selectionText) + '</em>'
    + '</div>'
    + '<div class="guided-category-list">'
    + availableCategories.map(function(cat){
      var isSelected = selected.indexOf(cat.id) !== -1;
      var stateLabel = cat.available ? (isSelected ? (selectedAvailable.length === 1 ? 'Required' : 'Selected') : 'Add') : 'Not loaded';
      return '<button class="guided-category-row' + (isSelected ? ' is-selected' : '') + (cat.available ? '' : ' is-disabled') + '"'
        + (cat.available ? ' onclick="guidedToggleCategory(\'' + guidedEsc(cat.id) + '\')"' : ' disabled')
        + ' style="--guided-accent:' + guidedEsc(cat.color) + '">'
        + '<span class="guided-category-dot" style="background:' + guidedEsc(cat.color) + '"></span>'
        + '<div class="guided-category-copy"><div class="guided-category-title">' + guidedEsc(cat.label) + '</div><div class="guided-category-blurb">' + guidedEsc(cat.available ? cat.blurb : 'Load or import this deck before adding it to Guided Learning.') + '</div></div>'
        + '<div class="guided-category-state">' + guidedEsc(stateLabel) + '</div>'
        + '</button>';
    }).join('')
    + (unavailableCategories.length
      ? '<div class="guided-category-unavailable-note">'
        + '<div class="guided-category-unavailable-title">Not loaded yet</div>'
        + '<div class="guided-category-unavailable-copy">' + guidedEsc(guidedFormatPlainList(unavailableLabels)) + ' ' + (unavailableCategories.length === 1 ? 'will appear here after its deck is loaded.' : 'will appear here after their decks are loaded.') + '</div>'
      + '</div>'
      : '')
    + '</div>'
    + '<div class="guided-card">'
    +   '<div class="guided-section-kicker">' + (run ? 'Next bracket' : 'First bracket') + '</div>'
    +   '<div class="guided-card-title guided-setup-preview-title">' + guidedEsc(previewCopy.title) + '</div>'
    +   '<div class="guided-card-sub">' + guidedEsc(previewCopy.sub) + '</div>'
    +   guidedRenderChipRow(selectedAvailable)
    +   guidedRenderSetupRotationPreview(rotationPreview)
    + '</div>'
    + (setupSaveState
      ? '<div class="guided-card guided-setup-save-card is-' + guidedEsc(setupSaveState.key) + '">'
        + '<div class="guided-section-kicker">' + guidedEsc(setupSaveState.kicker) + '</div>'
        + '<div class="guided-card-title guided-setup-save-title">' + guidedEsc(setupSaveState.title) + '</div>'
        + '<div class="guided-card-sub">' + guidedEsc(setupSaveState.sub) + '</div>'
      + '</div>'
      : '')
    + '<div class="guided-actions">'
    +   '<button class="btn btn-gold"' + (hasSelection ? ' onclick="' + primaryAction + '"' : ' disabled') + '>' + guidedEsc(primaryLabel) + '</button>'
    +   '<button class="btn btn-soft" onclick="' + (run ? 'showGuidedOptions()' : 'showHome()') + '">Cancel</button>'
    + '</div>'
    + '</div>';
}
