  if (type === 'learn') return '<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M9 14.5c5.5-3.2 10.5-3.2 15 0v23.5c-4.6-3.1-9.6-3.3-15-.5v-23Z" fill="currentColor"/><path d="M24 14.5c4.5-3.2 9.5-3.2 15 0v23c-5.4-2.8-10.4-2.6-15 .5v-23.5Z" fill="currentColor"/><path d="M13.5 16.5c2.4-.9 4.8-.8 7.2.4M27.3 16.9c2.4-1.2 4.8-1.3 7.2-.4" fill="none" stroke="rgba(255,255,255,0.36)" stroke-width="2.1" stroke-linecap="round"/><path d="M23 14h2v25h-2z" fill="rgba(255,255,255,0.22)"/></svg>';
  if (type === 'practice') return '<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M12 34.8l2.7-8.8 17.7-17.7c1.1-1.1 2.8-1.1 3.9 0l3.4 3.4c1.1 1.1 1.1 2.8 0 3.9L22 33.3l-8.8 2.7c-.8.2-1.4-.5-1.2-1.2Z" fill="currentColor"/><path d="M28.8 12.2l7 7" stroke="rgba(255,255,255,0.34)" stroke-width="2.4" stroke-linecap="round"/><path d="M15.7 28.1l4.2 4.2-5.5 1.7 1.3-5.9Z" fill="rgba(255,255,255,0.22)"/></svg>';
  if (type === 'challenge') return '<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M16 10.5h16v7.2c0 7.8-3.3 13.1-8 15.7-4.7-2.6-8-7.9-8-15.7v-7.2Z" fill="currentColor"/><path d="M16.7 16H9.5c.2 7.1 4.2 11.1 9.5 11.8l.7-4.2c-3.5-.6-5.7-2.8-6.3-5.7h3.3V16ZM31.3 16h7.2c-.2 7.1-4.2 11.1-9.5 11.8l-.7-4.2c3.5-.6 5.7-2.8 6.3-5.7h-3.3V16ZM21.5 32h5v5h5.4v4.5H16.1V37h5.4v-5Z" fill="currentColor"/><path d="M24 15.5l1.7 3.4 3.7.5-2.7 2.6.7 3.7-3.4-1.8-3.4 1.8.7-3.7-2.7-2.6 3.7-.5 1.7-3.4Z" fill="rgba(255,255,255,0.28)"/></svg>';
  if (type === 'checkpoint') return '<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M24 6.5l15 6.3v10.8c0 9.1-5.8 15.6-15 19.3-9.2-3.7-15-10.2-15-19.3V12.8l15-6.3Z" fill="currentColor"/><path d="M24 13.7v22.4M14.5 24.6h19" stroke="rgba(255,255,255,0.32)" stroke-width="4" stroke-linecap="round"/></svg>';
  if (type === 'spiral_review') return '<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M31.5 10.8c-6.6-4.4-17-1.2-20.3 7.2-4.4 11.3 4.4 22.2 15.5 22.2 8.2 0 14.8-5.2 15.5-12.6.6-6.4-4.8-11.2-11.3-10.7-6.1.5-10.5 5.2-9.5 10 .8 3.8 5.2 5.6 8.5 3.6 2.4-1.4 3.6-3.8 2.8-6.5-.4-1.3-1.8-2.1-3.1-1.7-1.3.4-2 1.8-1.6 3.1.1.5-.1.8-.6 1.1-.8.5-1.8.1-2-.5-.4-1.8 2.3-4.5 5.8-4.8 3.4-.3 6.8 1.8 6.4 5.9-.5 5-5.3 8.6-10.9 8.6-7.6 0-13.5-7.3-10.5-15 2.2-5.5 9.2-7.9 13.2-5.3 1.2.8 2.8.5 3.6-.7.8-1.2.5-2.9-.7-3.7Z" fill="currentColor"/></svg>';
  return '<svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="15" fill="currentColor"/><circle cx="24" cy="24" r="6" fill="rgba(255,255,255,0.28)"/></svg>';
