    summary.streakScreenSeen = true;
    guidedState.currentResults = summary;
    guidedState.screen = GUIDED_SCREEN_STREAK_EXTENDED;
    saveGuidedState();
    renderGuidedView();
    show('guided');
    guidedScrollAppToTop();
