function guidedBuildBracketHistoryTimeline(run) {
  if (!run) return [];
  var byIndex = {};
  (Array.isArray(run.bracketHistory) ? run.bracketHistory : []).forEach(function(snapshot){
    if (!snapshot) return;
    var index = Number(snapshot.bracketIndex || 0);
    if (!index) return;
    byIndex[index] = snapshot;
  });
  var currentSnapshot = guidedSnapshotCurrentBracket(run);
  if (currentSnapshot) {
    currentSnapshot.isCurrentBracket = true;
    byIndex[Number(currentSnapshot.bracketIndex || run.bracketIndex || 1)] = currentSnapshot;
  }
  return Object.keys(byIndex).map(function(index){
    return byIndex[index];
  }).sort(function(a, b){
    return Number(a && a.bracketIndex || 0) - Number(b && b.bracketIndex || 0);
  });
}
