// ── DECK MASTERY ──
function checkDeckMastery(deckId) {
  // Returns XP bonus if deck just hit 100% for the first time, else 0
  if (!deckId || deckId === '__all__' || deckId === '__daily__') return 0;
  if ((gd.masteredDecks || []).includes(String(deckId))) return 0; // already awarded
  var d = decks.find(function(x){ return x.id == deckId; });
  if (!d || !d.cards.length) return 0;
  var totalScore = 0;
  d.cards.forEach(function(c){ totalScore += (getMastery(d.id, c.id).score || 0); });
  var pct = Math.round(totalScore / (d.cards.length * 20) * 100);
  if (pct === 100) {
    if (!gd.masteredDecks) gd.masteredDecks = [];
    gd.masteredDecks.push(String(deckId));
    if (!gd.badges.includes('deck_mastered')) gd.badges.push('deck_mastered');
    return 500; // one-time Shekel bonus
  }
  return 0;
}


// ── CARD LEVEL SYSTEM ──
// Thresholds: to unlock level N+1, need previous levels' cards correct ≥:
// N-0 (1 below target) → 3,  N-1 (2 below) → 8,  N-2 (3 below) → 15
var LEVEL_UNLOCK_THRESHOLDS = [3, 8, 15]; // index 0 = closest level

function getDeckUnlockedLevel(deckId) {
  if (!deckId || deckId === '__all__' || deckId === '__daily__') return 9;
  return (gd.deckLevels && gd.deckLevels[String(deckId)]) || 1;
}

function getCardScore(deckId, cardId) {
  return getMastery(deckId, cardId).score || 0;
}

function checkDeckLevelUnlock(deckId) {
  // Returns new unlocked level if it increased, else null
  if (!deckId || deckId === '__all__' || deckId === '__daily__') return null;
  var d = decks.find(function(x){ return x.id == deckId; });
  if (!d) return null;
  if (!gd.deckLevels) gd.deckLevels = {};
  var currentLevel = getDeckUnlockedLevel(deckId);
  if (currentLevel >= 40) return null; // already max

  var nextLevel = currentLevel + 1;
  var nextCards = d.cards.filter(function(c){ return (c.level || 1) === nextLevel; });
  if (!nextCards.length) return null;
  // Check each requirement: cards at level (nextLevel - 1 - i) need score >= THRESHOLDS[i]
  for (var i = 0; i < LEVEL_UNLOCK_THRESHOLDS.length; i++) {
    var targetCardLevel = nextLevel - 1 - i;
    if (targetCardLevel < 1) break; // no more levels to check
    var threshold = LEVEL_UNLOCK_THRESHOLDS[i];
    var cardsAtLevel = d.cards.filter(function(c){ return (c.level || 1) === targetCardLevel; });
    if (!cardsAtLevel.length) continue; // no cards at this level, skip requirement
    var allMet = cardsAtLevel.every(function(c){ return getCardScore(deckId, c.id) >= threshold; });
    if (!allMet) return null;
  }
  // All requirements met — unlock!
  gd.deckLevels[String(deckId)] = nextLevel;
  return nextLevel;
}

function getUnlockedCards(deck) {
  // Returns cards whose level ≤ deck's unlocked level
  var ul = getDeckUnlockedLevel(deck.id);
  return deck.cards.filter(function(c){ return (c.level || 1) <= ul; });
}

function getDeckUnlockProgress(deck) {
  // Returns info needed to display progress toward next level unlock
  var deckId = deck.id;
  var currentLevel = getDeckUnlockedLevel(deckId);
  if (currentLevel >= 40) return null;
  var nextLevel = currentLevel + 1;
  var reqs = [];
  for (var i = 0; i < LEVEL_UNLOCK_THRESHOLDS.length; i++) {
    var targetCardLevel = nextLevel - 1 - i;
    if (targetCardLevel < 1) break;
    var threshold = LEVEL_UNLOCK_THRESHOLDS[i];
    var cards = deck.cards.filter(function(c){ return (c.level || 1) === targetCardLevel; });
    if (!cards.length) continue;
    var met = cards.filter(function(c){ return getCardScore(deckId, c.id) >= threshold; }).length;
    reqs.push({ cardLevel: targetCardLevel, threshold: threshold, met: met, total: cards.length, done: met === cards.length });
  }
  // Check if there are actually any level nextLevel cards to unlock
  var nextCards = deck.cards.filter(function(c){ return (c.level || 1) === nextLevel; });
  return { nextLevel: nextLevel, reqs: reqs, nextCards: nextCards.length };
}

// ── UNLOCK NOTIFICATION QUEUE ──
var _unlockQueue = [];
var _unlockShowing = false;

function queueUnlockNotification(deckName, newLevel) {
  _unlockQueue.push({ deckName: deckName, newLevel: newLevel });
  if (!_unlockShowing) showNextUnlock();
}
function showNextUnlock() {
  if (!_unlockQueue.length) { _unlockShowing = false; return; }
  _unlockShowing = true;
  var item = _unlockQueue.shift();
  var overlay = document.getElementById('unlock-overlay');
  document.getElementById('unlock-deck-name').textContent = item.deckName;
  document.getElementById('unlock-new-level').textContent = item.newLevel;
  overlay.classList.add('open');
  studyDeckOpenDialog(overlay, { focusSelector: 'button' });
}
function dismissUnlock() {
  document.getElementById('unlock-overlay').classList.remove('open');
  studyDeckCloseDialog('unlock-overlay', { restoreFocus: false });
  setTimeout(showNextUnlock, 300);
}

function checkAllDeckUnlocks(affectedDeckIds) {
  // Check each affected deck and queue notifications for any unlocks
  var seen = {};
  affectedDeckIds.forEach(function(deckId) {
    if (!deckId || deckId === '__all__' || deckId === '__daily__' || seen[deckId]) return;
    seen[deckId] = true;
    var newLevel = checkDeckLevelUnlock(deckId);
    if (newLevel !== null) {
      var d = decks.find(function(x){ return x.id == deckId; });
      if (d) queueUnlockNotification(d.name, newLevel);
    }
  });
}

function localDateKey(date) {
  var d = date instanceof Date ? date : new Date();
  return d.getFullYear() + '-'
    + String(d.getMonth() + 1).padStart(2, '0') + '-'
    + String(d.getDate()).padStart(2, '0');
}
function parseLocalDateKey(key) {
  var parts = String(key || '').split('-').map(function(part){ return parseInt(part, 10); });
  if (parts.length !== 3 || parts.some(function(num){ return !Number.isFinite(num); })) return new Date();
  return new Date(parts[0], parts[1] - 1, parts[2]);
}
function todayStr() {
  return localDateKey(new Date());
}
function localTodayStr() {
  return todayStr();
}
function getMastery(deckId, cardId) {
  var k = deckId + ':' + cardId;
  return gd.mastery[k] || { level:0, nextReview:0, correct:0, wrong:0 };
}
function setMastery(deckId, cardId, m) {
  gd.mastery[deckId+':'+cardId] = m;
}

var _masteryEditorDeckId = null;
var _masteryEditorCardId = null;
var MASTERY_PRESET_SCORES = [0, 6, 12, 19, 20];

function clampMasteryScore(score) {
  score = parseInt(score, 10);
  if (!isFinite(score)) score = 0;
  return Math.max(0, Math.min(20, score));
}
function getCardRecord(deckId, cardId) {
  var deck = decks.find(function(x){ return String(x.id) === String(deckId); });
  if (!deck) return null;
  var card = deck.cards.find(function(x){ return String(x.id) === String(cardId); });
  return card ? { deck: deck, card: card } : null;
}
function masteryNextReviewForScore(score) {
  var intervals = [0, 1, 3, 7, 14];
  var days = intervals[masteryTier(score)] || 0;
  return days === 0 ? 0 : Date.now() + days * 86400000;
}
function getFlashcardMasteryDeckId(card) {
  if (!card) return null;
  var deckId = card._deckId || (activeDeck && activeDeck.id !== '__all__' && activeDeck.id !== '__daily__' ? activeDeck.id : null);
  if (!deckId || deckId === '__all__' || deckId === '__daily__') return null;
  return deckId;
}
function getFlashcardReviewKey(card) {
  var deckId = getFlashcardMasteryDeckId(card);
  return deckId ? deckId + ':' + card.id : cardKey(card);
}
function ensureFlashcardKnowStore() {
  if (!gd.fcKnowIt || typeof gd.fcKnowIt !== 'object') gd.fcKnowIt = {};
  return gd.fcKnowIt;
}
function getFlashcardKnowEntry(key) {
  var store = ensureFlashcardKnowStore();
  var entry = store[key];
  if (!entry) return null;
  if (entry.date !== localTodayStr()) {
    delete store[key];
    return null;
  }
  return entry;
}
function isFlashcardKnownToday(key) {
  var entry = getFlashcardKnowEntry(key);
  return !!(entry && entry.applied);
}
function clearFlashcardKnowEntry(key) {
  var store = ensureFlashcardKnowStore();
  delete store[key];
}
function setMasteryScore(deckId, cardId, score) {
  var m = getMastery(deckId, cardId);
  score = clampMasteryScore(score);
  m.score = score;
  m.level = masteryTier(score);
  m.nextReview = masteryNextReviewForScore(score);
  setMastery(deckId, cardId, m);
  return m;
}
function applyFlashcardKnowBoost(card) {
  var deckId = getFlashcardMasteryDeckId(card);
  var key = getFlashcardReviewKey(card);
  var existing = getFlashcardKnowEntry(key);
  if (existing && existing.applied) {
    showXpToast((existing.delta || 0) > 0 ? 'Mastery can increase again tomorrow.' : 'Mastery is already maxed.', 1200);
    return false;
  }

  var delta = 0;
  var scoreBefore = null;
  if (deckId) {
    var before = clampMasteryScore((getMastery(deckId, card.id).score || 0));
    var after = Math.min(20, before + 1);
    scoreBefore = before;
    delta = after - before;
    setMasteryScore(deckId, card.id, after);
  }

  ensureFlashcardKnowStore()[key] = { date: localTodayStr(), applied: true, delta: delta, scoreBefore: scoreBefore };
  studyMore.delete(key);
  saveReviewMarks();

  var unlockedLevel = deckId && delta > 0 ? checkDeckLevelUnlock(deckId) : null;
  saveGameData();
  showXpToast(delta > 0 ? '+1 mastery' : 'Marked known for today', 1200);
  if (unlockedLevel !== null) {
    var d = decks.find(function(x){ return x.id == deckId; });
    if (d) queueUnlockNotification(d.name, unlockedLevel);
  }
  return true;
}
function revokeFlashcardKnowBoost(card) {
  var deckId = getFlashcardMasteryDeckId(card);
  var key = getFlashcardReviewKey(card);
  var entry = getFlashcardKnowEntry(key);
  if (!entry || !entry.applied) return 0;
  var delta = Number(entry.delta || 0);
  if (deckId && delta > 0) {
    var current = clampMasteryScore((getMastery(deckId, card.id).score || 0));
    var base = typeof entry.scoreBefore === 'number' ? clampMasteryScore(entry.scoreBefore) : null;
    var nextScore = base !== null
      ? (current > base ? Math.max(base, current - delta) : current)
      : Math.max(0, current - delta);
    setMasteryScore(deckId, card.id, nextScore);
  }
  clearFlashcardKnowEntry(key);
  saveGameData();
  return delta;
}
function openMasteryEditor(deckId, cardId) {
  if (!authorMode) return;
  var rec = getCardRecord(deckId, cardId);
  if (!rec) return;
  _masteryEditorDeckId = String(deckId);
  _masteryEditorCardId = cardId;
  var m = getMastery(deckId, cardId);
  var score = clampMasteryScore(m.score || 0);
  document.getElementById('mastery-editor-q').innerHTML = renderMD(rec.card.q || '');
  document.getElementById('mastery-editor-a').innerHTML = renderMD(rec.card.a || '');
  document.getElementById('mastery-editor-grid').innerHTML = MASTERY_NAMES.map(function(name, tier){
    var presetScore = MASTERY_PRESET_SCORES[tier];
    return '<button class="mastery-editor-tier-btn mp'+tier+'" data-tier="'+tier+'" onclick="setMasteryEditorDraftScore('+presetScore+')">'
      +escHtml(name)
      +'<small>'+presetScore+'/20</small>'
      +'</button>';
  }).join('');
  document.getElementById('mastery-score-input').value = score;
  syncMasteryEditorScore();
  document.getElementById('mastery-editor-overlay').classList.add('open');
  studyDeckOpenDialog('mastery-editor-overlay', { focusSelector: '#mastery-score-input' });
}
function closeMasteryEditor() {
  document.getElementById('mastery-editor-overlay').classList.remove('open');
  studyDeckCloseDialog('mastery-editor-overlay');
  _masteryEditorDeckId = null;
  _masteryEditorCardId = null;
}
function syncMasteryEditorScore() {
  var inp = document.getElementById('mastery-score-input');
  if (!inp) return;
  var score = clampMasteryScore(inp.value);
  inp.value = score;
  var tier = masteryTier(score);
  var current = document.getElementById('mastery-editor-current');
  if (current) current.textContent = 'Selected: ' + score + '/20 · ' + MASTERY_NAMES[tier];
  document.querySelectorAll('#mastery-editor-grid .mastery-editor-tier-btn').forEach(function(btn){
    btn.classList.toggle('on', Number(btn.getAttribute('data-tier')) === tier);
  });
}
function stepMasteryEditorScore(delta) {
  var inp = document.getElementById('mastery-score-input');
  if (!inp) return;
  inp.value = clampMasteryScore((parseInt(inp.value, 10) || 0) + delta);
  syncMasteryEditorScore();
}
function setMasteryEditorDraftScore(score) {
  var inp = document.getElementById('mastery-score-input');
  if (!inp) return;
  inp.value = clampMasteryScore(score);
  syncMasteryEditorScore();
}
function applyMasteryEditorInput() {
  var inp = document.getElementById('mastery-score-input');
  applyMasteryEditorScore(inp ? inp.value : 0);
}
function applyMasteryEditorScore(score) {
  if (!authorMode || _masteryEditorDeckId === null || _masteryEditorCardId === null) return;
  var deckId = _masteryEditorDeckId;
  var cardId = _masteryEditorCardId;
  score = clampMasteryScore(score);
  var rec = getCardRecord(deckId, cardId);
  if (!rec) return;

  var m = getMastery(deckId, cardId);
  m.score = score;
  m.level = masteryTier(score);
  m.nextReview = masteryNextReviewForScore(score);
  setMastery(deckId, cardId, m);

  var unlockedLevel = checkDeckLevelUnlock(deckId);
  saveGameData();
  closeMasteryEditor();
  if (activeDeck) renderDetail();
  showXpToast('Mastery set: ' + score + '/20 · ' + MASTERY_NAMES[masteryTier(score)]);
  if (unlockedLevel !== null) queueUnlockNotification(rec.deck.name, unlockedLevel);
}

// Update streak on any study activity
function checkEmergencyFreeze() {
  if (!gd.lastStudy) return;
  var today     = todayStr();
  if (gd.lastStudy === today) return; // already studied today, no problem
  var lastDate  = new Date(gd.lastStudy + 'T00:00:00');
  var todayDate = new Date(today + 'T00:00:00');
  var daysMissed = Math.round((todayDate - lastDate) / 86400000) - 1;
  if (daysMissed <= 0 || daysMissed > 3) return; // nothing to rescue, or too far gone

  // Check how many days stored freezes already cover
  var storedFreezes = gd.freezes || 0;
  var daysUncovered = Math.max(0, daysMissed - storedFreezes);
  if (daysUncovered <= 0) return; // stored freezes handle it

  var costPerDay  = 200;
  var available   = (gd.shekels||0) - (gd.shekelsSpent||0);
  var canAfford   = Math.min(daysUncovered, Math.floor(available / costPerDay));
  if (canAfford <= 0) return; // can't afford anything

  var totalCost = canAfford * costPerDay;
  appConfirm(
    '🚨 Streak at Risk!',
    'You missed ' + daysMissed + ' day' + (daysMissed!==1?'s':'') + '. Your ' + gd.streak
      + '-day streak will reset when you next study!\n\nSpend ' + totalCost
      + ' 🪙 to apply ' + canAfford + ' emergency freeze' + (canAfford!==1?'s':'') + ' and save your streak?',
    'Save My Streak',
    'btn-gold',
    function(ok) {
      if (!ok) return;
      gd.shekelsSpent = (gd.shekelsSpent||0) + totalCost;
      // Fill in missed days as freeze-protected
      for (var i = 1; i <= canAfford + storedFreezes; i++) {
        var d = new Date(gd.lastStudy + 'T00:00:00');
        d.setDate(d.getDate() + i);
        var ds = localDateKey(d);
        if (ds < today) gd.studyDays[ds] = 'freeze';
      }
      gd.freezes = 0; // consumed stored freezes too
      gd.lastStudy = new Date(today + 'T00:00:00');
      // Move lastStudy back enough so touchStreak will extend (not reset) streak
      var newLast = new Date(today + 'T00:00:00');
      newLast.setDate(newLast.getDate() - 1);
      gd.lastStudy = localDateKey(newLast);
      saveGameData();
      renderHomeGamification();
      showXpToast('🧊 Emergency freeze applied! Streak saved!');
    }
  );
}

function checkFreezeNotification() {
  if (!gd.freezeUsedPending) return;
  gd.freezeUsedPending = false;
  saveGameData();
  appConfirm(
    '🧊 Streak Freeze Used',
    'A streak freeze was automatically used to protect your ' + gd.streak + '-day streak while you were away. You have ' + (gd.freezes || 0) + ' freeze' + (gd.freezes !== 1 ? 's' : '') + ' remaining.',
    'Got it', 'btn-gold',
    function() {}
  );
}

function touchStreak() {
  var today = todayStr();
  if (gd.lastStudy === today) return { extendedToday: false, streak: gd.streak || 0 };
  if (!gd.studyDays) gd.studyDays = {};
  var yesterday = new Date(); yesterday.setDate(yesterday.getDate()-1);
  var yStr = localDateKey(yesterday);
  if (gd.lastStudy === yStr) {
    gd.streak = gd.streak + 1;
  } else if (gd.lastStudy && gd.lastStudy !== yStr) {
    // Missed a day — fill gap with freeze or reset
    if (gd.freezes > 0) {
      gd.freezes--;
      var missed = parseLocalDateKey(gd.lastStudy);
      missed.setDate(missed.getDate() + 1);
      while (localDateKey(missed) < today) {
        gd.studyDays[localDateKey(missed)] = 'freeze';
        missed.setDate(missed.getDate() + 1);
      }
      gd.freezeUsedPending = true;
    } else {
      gd.streak = 1;
    }
  } else {
    gd.streak = 1;
  }
  gd.studyDays[today] = 'studied';
  gd.lastStudy = today;
  saveGameData();
  checkStreakMilestones();
  renderHomeGamification();
  return { extendedToday: true, streak: gd.streak || 0 };
}

// Award XP and check badges
function awardXP(amount, reason) {
  gd.xp += amount;
  var newBadges = checkBadges();
  saveGameData();
  showXpToast('+' + amount + ' XP' + (reason ? '  ' + reason : ''));
  renderHomeGamification();
  return newBadges;
}

function checkBadges() {
  var newlyEarned = [];
  function earn(id) {
    if (!gd.badges.includes(id)) { gd.badges.push(id); newlyEarned.push(id); }
  }
  var masteredCount = Object.values(gd.mastery).filter(function(m){ return (m.score||0) >= 20; }).length;
  if (masteredCount >= 1)   earn('mastered1');
  if (masteredCount >= 10)  earn('mastered10');
  if (masteredCount >= 25)  earn('mastered25');
  if (masteredCount >= 50)  earn('mastered50');
  if (masteredCount >= 100) earn('mastered100');
  if (masteredCount >= 250) earn('mastered250');
  if (masteredCount >= 500) earn('mastered500');
  var lv = xpLevel(gd.xp);
  if (lv >= 5)  earn('level5');
  if (lv >= 10) earn('level10');
  if (lv >= 15) earn('level15');
  if (lv >= 20) earn('level20');
  if (lv >= 25) earn('level25');
  if (lv >= 30) earn('level30');
  if (lv >= 40) earn('level40');
  if (lv >= 50) earn('level50');
  if (gd.dailyDone >= 5)   earn('daily5');
  if (gd.dailyDone >= 30)  earn('daily30');
  if (gd.dailyDone >= 100) earn('daily100');
  return newlyEarned;
}

var _xpToastTimer = null;
function showXpToast(msg, duration) {
  var t = document.getElementById('xp-toast');
  if (!t) return;
  t.textContent = msg;
  t.classList.add('show');
  if (_xpToastTimer) clearTimeout(_xpToastTimer);
  _xpToastTimer = setTimeout(function(){ t.classList.remove('show'); }, duration || 2000);
}

// ── SPACED REPETITION ──
function cardsDueNow() {
  var now = Date.now();
  var due = [];
  decks.forEach(function(d){
    if (!gd.dcDecks || !gd.dcDecks[String(d.id)]) return; // not enabled for DC
    var ul = getDeckUnlockedLevel(d.id);
    d.cards.forEach(function(c){
      if ((c.level || 1) > ul) return;
      var m = getMastery(d.id, c.id);
      if (m.score < 20 || m.nextReview <= now) {
        due.push({ card: c, deckId: d.id, mastery: m });
      }
    });
  });
  return due;
}

// ── DAILY CHALLENGE ──
var dailyCards = []; // array of {card, deckId}
var dailyIdx   = 0;
var dailyMode  = false;

function buildDailyCards() {
  // Seed with today's date for consistency
  var today = todayStr();
  var due   = cardsDueNow();
  // Seeded Fisher-Yates shuffle for reliable, date-consistent ordering
  var seed  = today.replace(/-/g,'') | 0;
  function seededRand() { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; }
  for (var i = due.length - 1; i > 0; i--) {
    var j = Math.floor(seededRand() * (i + 1));
    var tmp = due[i]; due[i] = due[j]; due[j] = tmp;
  }
  return due.slice(0, Math.min(10, due.length));
}

function startDailyChallenge() {
  // Check at least one deck is enabled for DC
  var anyEnabled = decks.some(function(d){ return gd.dcDecks && gd.dcDecks[String(d.id)]; });
  if (!anyEnabled) {
    appConfirm(
      'No decks in Daily Challenge',
      'At least one deck must be included in the Daily Challenge. Open any deck, tap ⚙, and turn on "Include this deck".',
      'Got it', 'btn-gold', function(){}
    );
    return;
  }
  var today = todayStr();
  dailyCards = buildDailyCards();
  if (!dailyCards.length) {
    appConfirm('All caught up!', 'No cards due for review today. Come back tomorrow or study a deck first.', 'Got it', 'btn-gold', function(){});
    return;
  }
  dailyMode = true;
  dailyIdx  = 0;
  if (gd.dailyDate !== today) { gd.dailyProg = 0; gd.dailyTotal = dailyCards.length; gd.dailyDate = today; saveGameData(); }
  activeDeck = {
    id: '__daily__', name: 'Daily Challenge', color: '#F59E0B',
    desc: 'Cards due for review', _isAll: true,
    cards: dailyCards.map(function(e){ return Object.assign({}, e.card, { _deckId: e.deckId }); })
  };
  filterTags=[]; filterExcludeTags=[]; filterFav=false; filterMore=false; filterLevel=""; filterSearch=""; filterTagsExpanded=false;
  qzCards  = shuffle(activeDeck.cards);
  if (!qzCards.length) {
    appConfirm('All caught up!', 'No cards are available for Daily Challenge right now.', 'Got it', 'btn-gold', function(){});
    return;
  }
  touchStreak();
  qzIdx    = 0; qzScore = 0; qzChosen = null; qzLog = [];
  qzOpts   = genOpts(qzCards[0], getDeckPool(qzCards[0]));
  renderQZ(); show('quiz');
}

function renderDailyButton() {
  var today   = todayStr();
  var due     = cardsDueNow().length;
  var sub     = document.getElementById('daily-sub');
  var pctEl   = document.getElementById('daily-pct');
  var ringEl  = document.getElementById('daily-ring-fill');
  if (!sub) return;
  var prog = (gd.dailyDate === today) ? gd.dailyProg : 0;
  var tot  = (gd.dailyDate === today) ? gd.dailyTotal : Math.min(10, due);
  if (tot === 0) tot = due || 0;
  var pct  = tot > 0 ? Math.round(prog/tot*100) : 0;
  sub.textContent = prog >= tot && tot > 0 ? 'Complete! ✓ Come back tomorrow' : due + ' card' + (due!==1?'s':'') + ' due for review';
  if (pctEl) pctEl.textContent = pct + '%';
  if (ringEl) { var circ = 119.4; ringEl.style.strokeDashoffset = (circ - circ * pct/100).toFixed(1); }
  var btn = document.getElementById('daily-btn');
  if (btn) btn.style.opacity = (prog >= tot && tot > 0) ? '.5' : '1';
}

