// ── SHOP ──
function renderShopView() {
  var available = (gd.shekels||0) - (gd.shekelsSpent||0);
  var userLevel = xpLevel(gd.xp);
  var xpEl = document.getElementById('shop-xp-amount');
  if (xpEl) xpEl.innerHTML = available + ' <span style="font-size:16px">🪙</span> Shekels';

  var sections = {};
  SHOP_ITEMS.forEach(function(item) {
    if (!sections[item.section]) sections[item.section] = [];
    sections[item.section].push(item);
  });

  var html = '';
  Object.keys(sections).forEach(function(sectionName) {
    var isTitles = sectionName === 'Titles';
    html += '<div class="shop-section">'
      + '<div class="shop-section-title">' + sectionName + '</div>';

    if (isTitles) html += '<div style="max-height:420px;overflow-y:auto;padding-right:4px">';

    sections[sectionName].forEach(function(item) {
      var btnClass, btnText, onclick;
      if (item.type === 'freeze') {
        var count = gd.freezes || 0;
        var maxF  = getMaxFreezes();
        var maxed = count >= maxF;
        if (maxed) {
          btnClass = 'cant-buy'; btnText = 'Full (' + count + '/' + maxF + ')'; onclick = '';
        } else if (available >= item.cost) {
          btnClass = 'can-buy'; btnText = item.cost + ' 🪙'; onclick = 'buyItem(\'' + item.id + '\')';
        } else {
          btnClass = 'cant-buy'; btnText = item.cost + ' 🪙'; onclick = '';
        }
        var nextMax = maxF < 5
          ? '<div style="font-size:10px;color:var(--muted);margin-top:2px">Max increases at ' + (maxF >= 3 ? (maxF >= 4 ? 'Lv 15 or 180-day streak' : 'Lv 10 or 90-day streak') : 'Lv 5 or 30-day streak') + '</div>'
          : '';
        html += '<div class="shop-item">'
          + '<div class="shop-item-icon">' + item.icon + '</div>'
          + '<div class="shop-item-info">'
            + '<div class="shop-item-name">' + item.name + '</div>'
            + '<div class="shop-item-desc">' + item.desc + '</div>'
            + '<div class="shop-item-stock">🧊 ' + count + ' / ' + maxF + ' in stock</div>'
            + nextMax
          + '</div>'
          + '<button class="shop-buy-btn ' + btnClass + '" ' + (onclick ? 'onclick="' + onclick + '"' : '') + '>' + btnText + '</button>'
        + '</div>';
      } else if (item.type === 'title') {
        var owned   = (gd.ownedTitles||[]).includes(item.id);
        var isActive = gd.activeTitle === item.id;
        var levelOk = !item.minLevel || userLevel >= item.minLevel;
        if (isActive) {
          btnClass = 'active'; btnText = '✓ Active'; onclick = '';
        } else if (owned) {
          btnClass = 'can-buy'; btnText = 'Equip'; onclick = 'equipTitle(\'' + item.id + '\')';
        } else if (!levelOk) {
          btnClass = 'cant-buy'; btnText = 'Lv ' + item.minLevel; onclick = '';
        } else if (available >= item.cost) {
          btnClass = 'can-buy'; btnText = item.cost + ' 🪙'; onclick = 'buyItem(\'' + item.id + '\')';
        } else {
          btnClass = 'cant-buy'; btnText = item.cost + ' 🪙'; onclick = '';
        }
        var lvLabel = item.minLevel ? '<span style="font-size:10px;color:' + (levelOk?'var(--gold)':'var(--muted)') + ';margin-left:4px">Lv ' + item.minLevel + (levelOk?'':' required') + '</span>' : '';
        html += '<div class="shop-item">'
          + '<div class="shop-item-icon">' + item.icon + '</div>'
          + '<div class="shop-item-info">'
            + '<div class="shop-item-name">' + item.name + lvLabel + '</div>'
            + '<div class="shop-item-desc">' + item.desc + '</div>'
          + '</div>'
          + '<button class="shop-buy-btn ' + btnClass + '" ' + (onclick ? 'onclick="' + onclick + '"' : '') + '>' + btnText + '</button>'
        + '</div>';
      } else if (item.type === 'frame') {
        var ownedFrame = (gd.ownedFrames||['none']).includes(item.id);
        var isActiveFrame = gd.activeFrame === item.frameId;
        var levelOkF = !item.minLevel || userLevel >= item.minLevel;
        var streakOkF = !item.streakReq || (gd.streak||0) >= item.streakReq;
        if (isActiveFrame) {
          btnClass = 'active'; btnText = '✓ Active'; onclick = 'equipFrame(\'' + item.frameId + '\',\'' + item.id + '\')';
        } else if (ownedFrame) {
          btnClass = 'can-buy'; btnText = 'Equip'; onclick = 'equipFrame(\'' + item.frameId + '\',\'' + item.id + '\')';
        } else if (!levelOkF) {
          btnClass = 'cant-buy'; btnText = 'Lv ' + item.minLevel; onclick = '';
        } else if (item.streakReq && !streakOkF) {
          btnClass = 'cant-buy'; btnText = item.streakReq + 'd streak'; onclick = '';
        } else if (item.cost === 0) {
          btnClass = 'can-buy'; btnText = 'Claim Free'; onclick = 'buyItem(\'' + item.id + '\')';
        } else if (available >= item.cost) {
          btnClass = 'can-buy'; btnText = item.cost + ' 🪙'; onclick = 'buyItem(\'' + item.id + '\')';
        } else {
          btnClass = 'cant-buy'; btnText = item.cost + ' 🪙'; onclick = '';
        }
        var lvLabelF = item.minLevel ? ' <span style="font-size:10px;color:'+(levelOkF?'var(--gold)':'var(--muted)')+'">Lv '+item.minLevel+'</span>' : '';
        var shapeBadge = '<span style="font-size:10px;color:var(--muted);margin-left:4px">'+(item.shape==='round'?'⬭ Round':'⬛ Square')+'</span>';
        html += '<div class="shop-item" onclick="openShopPreview(\''+item.id+'\')" style="cursor:pointer">'
          + '<div class="shop-item-icon">' + item.icon + '</div>'
          + '<div class="shop-item-info">'
            + '<div class="shop-item-name">' + item.name + lvLabelF + shapeBadge + '</div>'
            + '<div class="shop-item-desc">' + item.desc + '</div>'
          + '</div>'
          + '<button class="shop-buy-btn ' + btnClass + '" onclick="event.stopPropagation();' + (onclick || '') + '">' + btnText + '</button>'
        + '</div>';
      } else if (item.type === 'theme') {
        var ownedTheme   = (gd.ownedThemes||['default']).includes(item.id);
        var isActiveTheme = gd.activeTheme === item.id;
        if (isActiveTheme) {
          btnClass = 'active'; btnText = '✓ Active'; onclick = 'equipTheme(\'' + item.id + '\')';
        } else if (ownedTheme) {
          btnClass = 'can-buy'; btnText = 'Equip'; onclick = 'equipTheme(\'' + item.id + '\')';
        } else if (available >= item.cost) {
          btnClass = 'can-buy'; btnText = item.cost + ' 🪙'; onclick = 'buyItem(\'' + item.id + '\')';
        } else {
          btnClass = 'cant-buy'; btnText = item.cost + ' 🪙'; onclick = '';
        }
        html += '<div class="shop-item" onclick="openShopPreview(\''+item.id+'\')" style="cursor:pointer">'
          + '<div class="shop-item-icon">' + item.icon + '</div>'
          + '<div class="shop-item-info">'
            + '<div class="shop-item-name">' + item.name + '</div>'
            + '<div class="shop-item-desc">' + item.desc + '</div>'
          + '</div>'
          + '<div style="display:flex;gap:6px;align-items:center;flex-shrink:0">'
            + '<div style="width:16px;height:16px;border-radius:4px;background:' + item.front + ';border:1px solid rgba(255,255,255,0.15)"></div>'
            + '<div style="width:16px;height:16px;border-radius:4px;background:' + item.back + ';border:1px solid rgba(255,255,255,0.15)"></div>'
            + '<button class="shop-buy-btn ' + btnClass + '" onclick="event.stopPropagation();' + (onclick || '') + '">' + btnText + '</button>'
          + '</div>'
        + '</div>';
      }
    });

    // Milestone-exclusive titles section (at the end of Titles)
    if (isTitles) {
      var exOwned = STREAK_MILESTONES.filter(function(m){ return m.titleId && (gd.ownedTitles||[]).includes(m.titleId); });
      var exUnowned = STREAK_MILESTONES.filter(function(m){ return m.titleId && !(gd.ownedTitles||[]).includes(m.titleId); });
      if (exOwned.length || exUnowned.length) {
        html += '<div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--gold);padding:8px 0 4px;font-weight:700">🏆 Streak Exclusive</div>';
        exOwned.forEach(function(m){
          var isAct = gd.activeTitle === m.titleId;
          html += '<div class="shop-item">'
            + '<div class="shop-item-icon">🏆</div>'
            + '<div class="shop-item-info">'
              + '<div class="shop-item-name">"' + m.exclusiveTitle + '"</div>'
              + '<div class="shop-item-desc">' + m.days + '-day streak reward</div>'
            + '</div>'
            + '<button class="shop-buy-btn ' + (isAct?'active':'can-buy') + '" onclick="' + (isAct?'':'equipTitle(\''+m.titleId+'\')') + '">' + (isAct?'✓ Active':'Equip') + '</button>'
          + '</div>';
        });
        exUnowned.slice(0,3).forEach(function(m){
          html += '<div class="shop-item" style="opacity:0.45">'
            + '<div class="shop-item-icon">🔒</div>'
            + '<div class="shop-item-info">'
              + '<div class="shop-item-name">"' + m.exclusiveTitle + '"</div>'
              + '<div class="shop-item-desc">Reach a ' + m.days + '-day streak</div>'
            + '</div>'
            + '<button class="shop-buy-btn cant-buy">' + m.days + 'd streak</button>'
          + '</div>';
        });
      }
      html += '</div>'; // close scrollable div
    }

    html += '</div>'; // close shop-section
  });

  document.getElementById('shop-items').innerHTML = html;
}

function buyItem(itemId) {
  var item = getShopItem(itemId);
  if (!item) return;
  var available = (gd.shekels||0) - (gd.shekelsSpent||0);
  if (available < item.cost) { showXpToast('Not enough 🪙 Shekels!'); return; }
  if (item.minLevel && xpLevel(gd.xp) < item.minLevel) {
    showXpToast('Requires Level ' + item.minLevel + '!'); return;
  }
  gd.shekelsSpent = (gd.shekelsSpent||0) + item.cost;

  if (item.type === 'freeze') {
    var maxF = getMaxFreezes();
    gd.freezes = Math.min(maxF, (gd.freezes || 0) + 1);
    showXpToast('🧊 Streak freeze added!');
  } else if (item.type === 'frame') {
    if (!gd.ownedFrames) gd.ownedFrames = ['none'];
    if (!gd.ownedFrames.includes(item.id)) gd.ownedFrames.push(item.id);
    gd.activeFrame = item.frameId;
    applyFrame(item.frameId);
    showXpToast(item.icon + ' Frame equipped!');
  } else if (item.type === 'title') {
    if (!gd.ownedTitles) gd.ownedTitles = [];
    if (!gd.ownedTitles.includes(itemId)) gd.ownedTitles.push(itemId);
    gd.activeTitle = itemId;
    showXpToast(item.icon + ' Title equipped!');
    renderHomeGamification();
  } else if (item.type === 'theme') {
    if (!gd.ownedThemes) gd.ownedThemes = ['default'];
    if (!gd.ownedThemes.includes(itemId)) gd.ownedThemes.push(itemId);
    gd.activeTheme = itemId;
    applyTheme(itemId);
    showXpToast(item.icon + ' Theme applied!');
  }

  saveGameData();
  renderShopView();
}

var _sprevFlipped = false;
var _sprevItem = null;
var _sprevVariantIdx = 0;
var _sprevSampleCard = null;
var _shopPreviewReturnScrollTop = 0;

function getLevelOnePreviewPool() {
  var pool = [];
  (decks || []).forEach(function(deck) {
    (deck.cards || []).forEach(function(card) {
      if ((card.level || 1) === 1) pool.push({ deck: deck, card: card });
    });
  });
  if (!pool.length) {
    (decks || []).forEach(function(deck) {
      (deck.cards || []).forEach(function(card) {
        pool.push({ deck: deck, card: card });
      });
    });
  }
  return pool;
}

function getRandomShopPreviewCard() {
  var pool = getLevelOnePreviewPool();
  if (!pool.length) {
    return {
      deck: { name: 'Preview Deck' },
      card: { q: 'For God so loved the world that he gave his only Son, so that everyone who believes in him may not perish but may have eternal life.', a: 'John 3:16', level: 1 }
    };
  }
  return pool[Math.floor(Math.random() * pool.length)];
}

function setShopPreviewSample(sample) {
  _sprevSampleCard = sample || getRandomShopPreviewCard();
  var card = _sprevSampleCard.card || {};
  var deck = _sprevSampleCard.deck || {};
  document.getElementById('sprev-front-text').textContent = card.q || '';
  document.getElementById('sprev-back-text').textContent = card.a || '';
  document.getElementById('sprev-front-meta').textContent = (deck.name || 'Preview Deck') + ' · Level ' + (card.level || 1);
  document.getElementById('sprev-back-meta').textContent = (deck.name || 'Preview Deck') + ' · Level ' + (card.level || 1);
}

function openShopPreview(itemId) {
  openShopPreviewPage(itemId);
}

function openShopPreviewPage(itemId) {
  var item = getShopItem(itemId);
  if (!item) return;
  var appEl = document.getElementById('app');
  _shopPreviewReturnScrollTop = appEl ? appEl.scrollTop : 0;
  _sprevItem = item;
  _sprevVariantIdx = 0;
  _sprevFlipped = false;
  setShopPreviewSample(getRandomShopPreviewCard());
  renderShopPreviewPage();
  show('shop-preview-page');
}

function closeShopPreviewPage() {
  var returnTop = _shopPreviewReturnScrollTop || 0;
  renderShopView();
  show('shop');
  var appEl = document.getElementById('app');
  if (appEl) {
    requestAnimationFrame(function(){
      appEl.scrollTop = returnTop;
    });
  }
}

function toggleShopPreviewPageFlip() {
  _sprevFlipped = !_sprevFlipped;
  var el = document.getElementById('spp-card-3d');
  if (el) el.style.transform = _sprevFlipped ? 'rotateY(180deg)' : '';
}

function shopPreviewPageNav(dir) {
  if (!_sprevItem || !_sprevItem.variants || _sprevItem.variants.length <= 1) return;
  _sprevVariantIdx = (_sprevVariantIdx + dir + _sprevItem.variants.length) % _sprevItem.variants.length;
  renderShopPreviewPage();
}

function copyActualFlashcardPreviewIntoShopPreview(sample, item) {
  var prevActiveDeck = activeDeck;
  var prevFcCards = Array.isArray(fcCards) ? fcCards.slice() : fcCards;
  var prevFcIdx = fcIdx;
  var prevFcFlipped = fcFlipped;
  var prevTheme = gd.activeTheme;
  var prevThemeVariants = Object.assign({}, gd.activeThemeVariants || {});
  var prevFrame = gd.activeFrame;
  var faceFront = document.getElementById('face-front');
  var faceBack = document.getElementById('face-back');
  var frameFront = document.getElementById('frame-front');
  var frameBack = document.getElementById('frame-back');
  var saved = {
    frontHTML: faceFront ? faceFront.innerHTML : '',
    backHTML: faceBack ? faceBack.innerHTML : '',
    frontStyle: faceFront ? faceFront.getAttribute('style') || '' : '',
    backStyle: faceBack ? faceBack.getAttribute('style') || '' : '',
    ffHTML: frameFront ? frameFront.innerHTML : '',
    fbHTML: frameBack ? frameBack.innerHTML : '',
    fufHTML: document.getElementById('frame-under-front') ? document.getElementById('frame-under-front').innerHTML : '',
    fubHTML: document.getElementById('frame-under-back') ? document.getElementById('frame-under-back').innerHTML : ''
  };

  try {
    activeDeck = sample.deck || { id:'__preview__', name:'Preview' };
    fcCards = [{ card: sample.card || {}, deckId: (sample.deck && sample.deck.id) || '__preview__' }];
    fcIdx = 0;
    fcFlipped = false;
    renderFC();

    if (item.type === 'theme') {
      gd.activeTheme = item.id;
      if (!gd.activeThemeVariants) gd.activeThemeVariants = {};
      gd.activeThemeVariants[item.id] = _sprevVariantIdx || 0;
      applyTheme(item.id);
      applyFrame('none');
    } else if (item.type === 'frame') {
      gd.activeTheme = 'default';
      applyTheme('default');
      gd.activeFrame = sprevCurrentFrameId();
      applyFrame(gd.activeFrame || 'none');
    }

    var sppFront = document.getElementById('spp-face-front');
    var sppBack = document.getElementById('spp-face-back');
    var sppFrameFront = document.getElementById('spp-frame-front');
    var sppFrameBack = document.getElementById('spp-frame-back');
    var sppFrameUnderFront = document.getElementById('spp-frame-under-front');
    var sppFrameUnderBack = document.getElementById('spp-frame-under-back');
    if (sppFront && faceFront) {
      sppFront.innerHTML = faceFront.innerHTML;
      sppFront.setAttribute('style', faceFront.getAttribute('style') || '');
      copyCardThemeSurfaceAttrs(faceFront, sppFront);
    }
    if (sppBack && faceBack) {
      sppBack.innerHTML = faceBack.innerHTML;
      sppBack.setAttribute('style', faceBack.getAttribute('style') || '');
      copyCardThemeSurfaceAttrs(faceBack, sppBack);
    }
    if (sppFrameFront && frameFront) sppFrameFront.innerHTML = frameFront.innerHTML;
    if (sppFrameBack && frameBack) sppFrameBack.innerHTML = frameBack.innerHTML;
    if (sppFrameUnderFront && document.getElementById('frame-under-front')) sppFrameUnderFront.innerHTML = document.getElementById('frame-under-front').innerHTML;
    if (sppFrameUnderBack && document.getElementById('frame-under-back')) sppFrameUnderBack.innerHTML = document.getElementById('frame-under-back').innerHTML;
  } finally {
    activeDeck = prevActiveDeck;
    fcCards = prevFcCards;
    fcIdx = prevFcIdx;
    fcFlipped = prevFcFlipped;
    gd.activeTheme = prevTheme;
    gd.activeThemeVariants = prevThemeVariants;
    gd.activeFrame = prevFrame;
    if (faceFront) {
      faceFront.innerHTML = saved.frontHTML;
      faceFront.setAttribute('style', saved.frontStyle);
    }
    if (faceBack) {
      faceBack.innerHTML = saved.backHTML;
      faceBack.setAttribute('style', saved.backStyle);
    }
    applyTheme(prevTheme || 'default');
    if (frameFront) frameFront.innerHTML = saved.ffHTML;
    if (frameBack) frameBack.innerHTML = saved.fbHTML;
    if (document.getElementById('frame-under-front')) document.getElementById('frame-under-front').innerHTML = saved.fufHTML || '';
    if (document.getElementById('frame-under-back')) document.getElementById('frame-under-back').innerHTML = saved.fubHTML || '';
  }
}

function renderShopPreviewPage() {
  var item = _sprevItem;
  if (!item) return;
  document.getElementById('spp-title').textContent = item.icon + ' ' + item.name;
  document.getElementById('spp-desc').textContent = item.desc || '';
  var sample = _sprevSampleCard || getRandomShopPreviewCard();
  document.getElementById('spp-meta').textContent = String((_sprevVariantIdx || 0) + 1);
  copyActualFlashcardPreviewIntoShopPreview(sample, item);
  updateShopPreviewActionBtnToId('spp-action-btn', true);
  var label = document.getElementById('spp-variant-label');
  var hasVariants = item.variants && item.variants.length > 1;
  label.textContent = hasVariants ? ('Variation ' + (_sprevVariantIdx + 1)) : '';
  document.getElementById('spp-prev').style.opacity = hasVariants ? '1' : '.35';
  document.getElementById('spp-next').style.opacity = hasVariants ? '1' : '.35';
  document.getElementById('spp-prev').disabled = !hasVariants;
  document.getElementById('spp-next').disabled = !hasVariants;
  document.getElementById('spp-card-3d').style.transform = _sprevFlipped ? 'rotateY(180deg)' : '';
}

function sprevNav(dir) {
  if (!_sprevItem || !_sprevItem.variants) return;
  _sprevVariantIdx = (_sprevVariantIdx + dir + _sprevItem.variants.length) % _sprevItem.variants.length;
  sprevUpdateVariantLabel();
  sprevApplyVisuals();
  sprevUpdateActionBtn();
}

function sprevUpdateVariantLabel() {
  var item = _sprevItem;
  if (!item || !item.variants) return;
  var v = item.variants[_sprevVariantIdx];
  document.getElementById('sprev-variant-name').textContent = v.label;
  document.getElementById('sprev-variant-index').textContent = (_sprevVariantIdx+1) + ' of ' + item.variants.length;
}

function sprevCurrentFrameId() {
  var item = _sprevItem;
  if (!item) return 'none';
  if (item.variants && item.variants.length) return item.variants[_sprevVariantIdx].frameId;
  return item.frameId || 'none';
}

function resetCardThemeText(el) {
  if (!el) return;
  el.style.removeProperty('color');
  el.style.removeProperty('text-shadow');
}
function setCardThemeColor(el, color) {
  if (el && color) el.style.setProperty('color', color, 'important');
}
function setCardThemeShadow(el, textShadow) {
  if (el && textShadow != null) el.style.setProperty('text-shadow', textShadow, 'important');
}
function setCardThemeBackground(el, background) {
  if (!el) return;
  if (background) el.style.setProperty('background', background, 'important');
  else el.style.removeProperty('background');
}
function setCardThemeBorder(el, borderColor) {
  if (!el) return;
  if (borderColor) el.style.setProperty('border-color', borderColor, 'important');
  else el.style.removeProperty('border-color');
}
function markCardThemeSurface(el, item) {
  if (!el) return;
  if (item && item.type === 'theme') {
    el.setAttribute('data-card-theme-active', 'true');
    el.setAttribute('data-card-theme-id', item.id);
  } else {
    el.removeAttribute('data-card-theme-active');
    el.removeAttribute('data-card-theme-id');
  }
}
function copyCardThemeSurfaceAttrs(src, dest) {
  if (!src || !dest) return;
  ['data-card-theme-active', 'data-card-theme-id'].forEach(function(attr) {
    var val = src.getAttribute(attr);
    if (val == null) dest.removeAttribute(attr);
    else dest.setAttribute(attr, val);
  });
}
function applyCardThemeTextPalette(item, style, primaryEls, secondaryEls) {
  if (!item) return;
  var isHalo = item.id === 'theme_halo' || item.id === 'halo-white';
  var textColor = style && style.text ? style.text : (isHalo ? '#122033' : '#edf7ff');
  var secondaryColor = isHalo ? 'rgba(18,32,51,0.45)' : 'rgba(237,247,255,0.66)';
  var textShadow = style && style.textShadow != null ? style.textShadow : (isHalo ? 'none' : '0 2px 12px rgba(0,0,0,0.55)');
  (primaryEls || []).forEach(function(el) {
    setCardThemeColor(el, textColor);
    setCardThemeShadow(el, textShadow);
  });
  (secondaryEls || []).forEach(function(el) {
    setCardThemeColor(el, secondaryColor);
    setCardThemeShadow(el, textShadow);
  });
}

function applyShopPreviewVisualsToIds(frontId, backId, frameFrontId, frameBackId) {
  var item = _sprevItem;
  if (!item) return;
  var front = document.getElementById(frontId);
  var back  = document.getElementById(backId);
  var ffEl  = document.getElementById(frameFrontId);
  var fbEl  = document.getElementById(frameBackId);
  var fuEl  = document.getElementById(frameFrontId.replace('frame-front','frame-under-front'));
  var buEl  = document.getElementById(frameBackId.replace('frame-back','frame-under-back'));
  if (!front || !back || !ffEl || !fbEl) return;
  setCardThemeBackground(front, ''); setCardThemeBackground(back, '');
  setCardThemeBorder(front, ''); setCardThemeBorder(back, '');
  markCardThemeSurface(front, null); markCardThemeSurface(back, null);
  ffEl.innerHTML = ''; fbEl.innerHTML = '';

  var frontText = front.querySelector('.face-text') || document.getElementById('sprev-front-text');
  var backText = back.querySelector('.face-text') || document.getElementById('sprev-back-text');
  var frontSide = front.querySelector('.face-label') || document.getElementById('sprev-front-side');
  var backSide = back.querySelector('.face-label') || document.getElementById('sprev-back-side');
  var frontMeta = document.getElementById('sprev-front-meta');
  var backMeta = document.getElementById('sprev-back-meta');
  [frontText, backText, frontSide, backSide, frontMeta, backMeta].forEach(resetCardThemeText);

  if (item.type === 'theme') {
    markCardThemeSurface(front, item);
    markCardThemeSurface(back, item);
    var style = getThemeStyleFor(item.id, _sprevVariantIdx || 0);
    if (style) {
      setCardThemeBackground(front, style.front);
      setCardThemeBackground(back, style.back);
      if (style.text) {
        setCardThemeColor(frontText, style.text);
        setCardThemeColor(backText, style.text);
      }
      if (style.textShadow) {
        setCardThemeShadow(frontText, style.textShadow);
        setCardThemeShadow(backText, style.textShadow);
      }
    } else {
      setCardThemeBackground(front, item.front || '');
      setCardThemeBackground(back, item.back || '');
    }
    setCardThemeBorder(front, (item.accent || '#ffffff') + '66');
    setCardThemeBorder(back, (item.accent || '#ffffff') + '88');
    applyCardThemeTextPalette(item, style, [front, back, frontText, backText], [frontSide, backSide, frontMeta, backMeta]);
    if (item.id === 'theme_halo' || item.id === 'halo-white') {
      [frontText, backText].forEach(function(el){
        setCardThemeColor(el, '#122033');
        setCardThemeShadow(el, 'none');
      });
      [frontSide, backSide, frontMeta, backMeta].forEach(function(el){
        setCardThemeColor(el, 'rgba(18,32,51,0.45)');
        setCardThemeShadow(el, 'none');
      });
    }
  } else if (item.type === 'frame') {
    setCardThemeBackground(front, 'var(--surface)');
    setCardThemeBackground(back, 'var(--surface2)');
    var frameId = sprevCurrentFrameId();
    var frame = CARD_FRAMES[frameId] || CARD_FRAMES['none'];
    if (ffEl) ffEl.innerHTML = (frame.overFront != null ? frame.overFront : (frame.front || ''));
    if (fbEl) fbEl.innerHTML = (frame.overBack  != null ? frame.overBack  : (frame.back  || ''));
    if (fuEl) fuEl.innerHTML = frame.underFront || '';
    if (buEl) buEl.innerHTML = frame.underBack  || '';
  }
}

function updateShopPreviewActionBtnToId(btnId, closeAfter) {
  var item = _sprevItem;
  var available = (gd.shekels||0) - (gd.shekelsSpent||0);
  var userLevel = xpLevel(gd.xp);
  var btn = document.getElementById(btnId);
  if (!btn || !item) return;
  btn.onclick = null;
  btn.className = 'btn btn-gold';
  btn.style.opacity = ''; btn.style.cursor='';

  if (item.type === 'frame') {
    var ownedF  = (gd.ownedFrames||['none']).includes(item.id);
    var frameId = sprevCurrentFrameId();
    var activeF = gd.activeFrame === frameId;
    var levelOkF  = !item.minLevel || userLevel >= item.minLevel;
    var streakOkF = !item.streakReq || (gd.streak||0) >= item.streakReq;
    if (activeF) {
      btn.textContent = '✓ Active — tap to turn off'; btn.className = 'btn btn-soft';
      btn.onclick = function(){ equipFrame(frameId, item.id); if (closeAfter) closeShopPreviewPage(); else closeShopPreview(); };
    } else if (ownedF) {
      btn.textContent = 'Equip';
      btn.onclick = function(){ equipFrame(frameId, item.id); if (closeAfter) closeShopPreviewPage(); else closeShopPreview(); };
    } else if (!levelOkF) {
      btn.textContent = 'Requires Level ' + item.minLevel; btn.className = 'btn btn-soft'; btn.style.opacity = '.6'; btn.style.cursor = 'default';
    } else if (item.streakReq && !streakOkF) {
      btn.textContent = 'Requires ' + item.streakReq + '-day streak'; btn.className = 'btn btn-soft'; btn.style.opacity = '.6'; btn.style.cursor = 'default';
    } else if (item.cost === 0) {
      btn.textContent = 'Claim Free';
      btn.onclick = function(){ buyItem(item.id); if (closeAfter) closeShopPreviewPage(); else closeShopPreview(); };
    } else if (available >= item.cost) {
      btn.textContent = item.cost + ' 🪙';
      btn.onclick = function(){ buyItem(item.id); if (closeAfter) closeShopPreviewPage(); else closeShopPreview(); };
    } else {
      btn.textContent = 'Need ' + item.cost + ' 🪙'; btn.className = 'btn btn-soft'; btn.style.opacity = '.6'; btn.style.cursor = 'default';
    }
  } else if (item.type === 'theme') {
    var ownedTh  = (gd.ownedThemes||['default']).includes(item.id);
    var previewVariant = _sprevVariantIdx || 0;
    var activeTh = gd.activeTheme === item.id && getThemeVariantIndex(item.id) === previewVariant;
    if (activeTh) {
      btn.textContent = '✓ Active — tap to turn off'; btn.className = 'btn btn-soft';
      btn.onclick = function(){ equipTheme(item.id, previewVariant); if (closeAfter) closeShopPreviewPage(); else closeShopPreview(); };
    } else if (ownedTh) {
      btn.textContent = 'Equip';
      btn.onclick = function(){ equipTheme(item.id, previewVariant); if (closeAfter) closeShopPreviewPage(); else closeShopPreview(); };
    } else if (available >= item.cost) {
      btn.textContent = item.cost + ' 🪙';
      btn.onclick = function(){ buyItem(item.id); if (closeAfter) closeShopPreviewPage(); else closeShopPreview(); };
    } else {
      btn.textContent = 'Need ' + item.cost + ' 🪙'; btn.className = 'btn btn-soft'; btn.style.opacity = '.6'; btn.style.cursor = 'default';
    }
  }
}

function sprevApplyVisuals() {
  applyShopPreviewVisualsToIds('sprev-front','sprev-back','sprev-frame-front','sprev-frame-back');
}

function sprevUpdateActionBtn() {
  updateShopPreviewActionBtnToId('sprev-action-btn', false);
}

function closeShopPreview() {
  document.getElementById('shop-preview-modal').style.display = 'none';
  studyDeckCloseDialog('shop-preview-modal');
}

function toggleShopPreviewFlip() {
  _sprevFlipped = !_sprevFlipped;
  document.getElementById('sprev-card3d').style.transform = _sprevFlipped ? 'rotateY(180deg)' : '';
}

function equipFrame(frameId, itemId) {
  gd.activeFrame = gd.activeFrame === frameId ? 'none' : frameId;
  saveGameData();
  applyFrame(gd.activeFrame);
  renderShopView();
}

function equipTitle(itemId) {
  gd.activeTitle = gd.activeTitle === itemId ? null : itemId;
  saveGameData();
  renderHomeGamification();
  renderShopView();
}

function equipTheme(itemId, variantIdx) {
  gd.activeThemeVariants = gd.activeThemeVariants || {};
  var item = getShopItem(itemId);
  var targetVariant = Number(variantIdx || 0);
  if (item && item.variants && item.variants.length) {
    targetVariant = Math.max(0, Math.min(targetVariant, item.variants.length - 1));
  } else {
    targetVariant = 0;
  }
  var isSameTheme = gd.activeTheme === itemId;
  var isSameVariant = getThemeVariantIndex(itemId) === targetVariant;
  if (isSameTheme && isSameVariant) {
    gd.activeTheme = 'default';
  } else {
    gd.activeTheme = itemId;
    gd.activeThemeVariants[itemId] = targetVariant;
  }
  applyTheme(gd.activeTheme);
  saveGameData();
  renderShopView();
}

