function setFrameLayerContent(frontOverId, backOverId, frontUnderId, backUnderId, frameObj) {
  var fo = document.getElementById(frontOverId);
  var bo = document.getElementById(backOverId);
  var fu = document.getElementById(frontUnderId);
  var bu = document.getElementById(backUnderId);
  if (fo) fo.innerHTML = (frameObj.overFront != null ? frameObj.overFront : (frameObj.front || ''));
  if (bo) bo.innerHTML = (frameObj.overBack  != null ? frameObj.overBack  : (frameObj.back  || ''));
  if (fu) fu.innerHTML = (frameObj.underFront || '');
  if (bu) bu.innerHTML = (frameObj.underBack  || '');
}
function applyFrame(frameId) {
  var frame = CARD_FRAMES[frameId || 'none'] || CARD_FRAMES['none'];
  setFrameLayerContent('frame-front','frame-back','frame-under-front','frame-under-back', frame);
}

function updateFrameVisibility() { /* no-op — frames flip naturally inside card-3d */ }

// Theme surface styles: large gradients first, sparse motifs second
