function applyTheme(themeId) {
  var item = themeId === 'default' ? null : getShopItem(themeId);
  var front = document.getElementById('face-front');
  var back  = document.getElementById('face-back');
  if (!front || !back) return;
  var frontText = front.querySelector('.face-text');
  var backText = back.querySelector('.face-text');
  var frontSide = front.querySelector('.face-label');
  var backSide = back.querySelector('.face-label');
  var frontHint = front.querySelector('.card-scroll-hint');
  var backHint = back.querySelector('.card-scroll-hint');
  var themeTextEls = [front, back, frontText, backText, frontSide, backSide, frontHint, backHint];

  themeTextEls.forEach(resetCardThemeText);

  if (!item) {
    markCardThemeSurface(front, null);
    markCardThemeSurface(back, null);
    setCardThemeBackground(front, '');
    setCardThemeBackground(back, '');
    setCardThemeBorder(front, '');
    setCardThemeBorder(back, '');
    return;
  }

  markCardThemeSurface(front, item);
  markCardThemeSurface(back, item);
  var style = getThemeStyleFor(themeId, getThemeVariantIndex(themeId));
  if (style) {
    setCardThemeBackground(front, style.front);
    setCardThemeBackground(back, style.back);
    if (style.text) {
      [front, back, frontText, backText].forEach(function(el){
        setCardThemeColor(el, style.text);
      });
    }
    if (style.textShadow) {
      [front, back, frontText, backText].forEach(function(el){
        setCardThemeShadow(el, style.textShadow);
      });
    }
  } else {
    setCardThemeBackground(front, item.front);
    setCardThemeBackground(back, item.back);
  }

  setCardThemeBorder(front, item.accent + '66');
  setCardThemeBorder(back, item.accent + '88');
  applyCardThemeTextPalette(item, style, [front, back, frontText, backText], [frontSide, backSide, frontHint, backHint]);

  if (item.id === 'theme_halo' || item.id === 'halo-white') {
    [front, back, frontText, backText].forEach(function(el){
      setCardThemeColor(el, '#122033');
      setCardThemeShadow(el, 'none');
    });
    [frontSide, backSide, frontHint, backHint].forEach(function(el){
      setCardThemeColor(el, 'rgba(18,32,51,0.45)');
      setCardThemeShadow(el, 'none');
    });
  }
}

// ── MASTERY HELPERS ──
function recordCardResult(deckId, cardId, correct) {
  var m = getMastery(deckId, cardId);
  var score = m.score || 0;
  if (correct) {
    score = Math.min(20, score + 1);
  } else {
    score = Math.max(0, score - 1);
  }
  m.score = score;
  var tier = masteryTier(score);
  var intervals = [0, 1, 3, 7, 14];
  var days = intervals[tier];
  m.nextReview = days === 0 ? 0 : Date.now() + days * 86400000;
  setMastery(deckId, cardId, m);
  return {
    xp:      correct ? MASTERY_XP[tier]      : 1,
    shekels: correct ? MASTERY_SHEKELS[tier] : 0
  };
}

// ── HOOK INTO QUIZ nextQuestion ──
function nextQuestion() {
  var c       = qzCards[qzIdx];
  var chosenOpt = qzChosen !== null ? qzOpts[qzChosen] : null;
  var correct = !!(chosenOpt && chosenOpt.correct);
  var deckId  = c._deckId || (activeDeck && activeDeck.id !== '__all__' && activeDeck.id !== '__daily__' ? activeDeck.id : null);
  var xpEarned = 0, shekelsEarned = 0;

  var tierBefore = null, tierAfter = null;
  if (deckId) {
    var mBefore = getMastery(deckId, c.id);
    tierBefore  = masteryTier(mBefore.score || 0);
  }

  if (deckId && deckId !== '__all__' && deckId !== '__daily__') {
    if (!nextQuestion._affectedDecks) nextQuestion._affectedDecks = {};
    nextQuestion._affectedDecks[String(deckId)] = true;
    var earned = recordCardResult(deckId, c.id, correct);
    xpEarned = earned.xp;
    shekelsEarned = earned.shekels;
    var mAfter = getMastery(deckId, c.id);
    tierAfter = masteryTier(mAfter.score || 0);
  }

  qzLog.push({
    q:          c.q,
    a:          c.a,
    shownA:     getQuizAnswerForDifficulty(c, quizDifficulty),
    correct:    correct,
    chosen:     chosenOpt ? chosenOpt.label : '',
    tierBefore: tierBefore,
    tierAfter:  tierAfter
  });

  if (qzIdx < qzCards.length - 1) {
    qzIdx++; qzChosen = null;
    qzOpts = genOpts(qzCards[qzIdx], getDeckPool(qzCards[qzIdx]));
    renderQZ();
    gd.xp += xpEarned;
    gd.shekels = (gd.shekels||0) + shekelsEarned;
    saveGameData();
  } else {
    // Final results
    var pct = Math.round(qzScore / Math.max(1, qzCards.length) * 100);
    progress[activeDeck.id] = { lastScore: pct };
    touchStreak();

    // Completion bonuses
    var bonusXP = 3; // always earn XP for completing
    var bonusShekels = 5; // completion bonus
    if (pct === 100) {
      // Perfect score bonus — only if not all cards already mastered
      var allMastered = (function() {
        if (!deckId || deckId === '__all__' || deckId === '__daily__') return false;
        var d = decks.find(function(x){ return x.id == deckId; });
        if (!d) return false;
        return d.cards.every(function(card){ return (getMastery(deckId, card.id).score||0) >= 20; });
      })();
      bonusXP += 10;
      if (!allMastered) bonusShekels += 20;
    } else if (pct >= 80) { bonusXP += 5; bonusShekels += 8; }
    else if (pct >= 60) { bonusXP += 2; bonusShekels += 3; }

    gd.xp += xpEarned + bonusXP;
    gd.shekels = (gd.shekels||0) + shekelsEarned + bonusShekels;

    var newBadges = [];
    if (!gd.badges.includes('first_quiz')) { gd.badges.push('first_quiz'); newBadges.push('first_quiz'); }
    if (pct === 100) {
      if (!gd.badges.includes('perfect')) { gd.badges.push('perfect'); newBadges.push('perfect'); }
      gd._perfectCount = (gd._perfectCount||0) + 1;
      if (gd._perfectCount >= 5  && !gd.badges.includes('perfect5'))  { gd.badges.push('perfect5');  newBadges.push('perfect5'); }
      if (gd._perfectCount >= 10 && !gd.badges.includes('perfect10')) { gd.badges.push('perfect10'); newBadges.push('perfect10'); }
    }

    if (dailyMode) {
      var today = todayStr();
      gd.dailyProg = qzCards.length;
      if (gd.dailyDate === today) { gd.dailyDone++; }
      dailyMode = false;
    }

    newBadges = newBadges.concat(checkBadges());

    var affectedIds = Object.keys(nextQuestion._affectedDecks || {});
    nextQuestion._affectedDecks = {};
    affectedIds.forEach(function(id){ autoEnableDCDeck(id); });
    saveGameData();
    checkAllDeckUnlocks(affectedIds);

    var deckMasteryBonus = 0;
    var quizDeckId = qzCards[0] && (qzCards[0]._deckId || (activeDeck && activeDeck.id !== '__daily__' ? activeDeck.id : null));
    if (quizDeckId) {
      deckMasteryBonus = checkDeckMastery(quizDeckId);
      if (deckMasteryBonus > 0) { gd.shekels = (gd.shekels||0) + deckMasteryBonus; }
    }

    saveGameData();
    renderHomeGamification();

    document.getElementById('res-pct').textContent   = pct + '%';
    document.getElementById('res-title').textContent = pct===100?'🎉 Perfect!':pct>=70?'👏 Great job!':'📚 Keep studying!';
    document.getElementById('res-sub').textContent   = qzScore+' out of '+qzCards.length+' correct';
    var earnParts = [];
    if (bonusShekels+shekelsEarned > 0) earnParts.push('+' + (bonusShekels+shekelsEarned) + ' 🪙');
    if (bonusXP+xpEarned > 0) earnParts.push('+' + (bonusXP+xpEarned) + ' XP');
    if (deckMasteryBonus > 0) earnParts.push('👑 Deck Mastered! +' + deckMasteryBonus + ' 🪙');
    document.getElementById('res-xp').textContent = earnParts.join('  ·  ');

    var bdgEl = document.getElementById('res-badges');
    bdgEl.innerHTML = newBadges.map(function(id){
      var b = BADGE_DEFS.find(function(x){ return x.id===id; });
      return b ? '<div class="new-badge-pill">'+b.icon+' '+b.name+'</div>' : '';
    }).join('');

    var TIER_COLORS = ['tier-color-0','tier-color-1','tier-color-2','tier-color-3','tier-color-4'];
    var changesEl = document.getElementById('res-card-changes');
    changesEl.innerHTML = qzLog.map(function(entry, i){
      var rowClass = entry.correct ? 'correct' : 'wrong';
      var colorClass = TIER_COLORS[entry.tierAfter !== null ? entry.tierAfter : 0];
      var tierTag = '';
      if (entry.tierBefore !== null && entry.tierAfter !== null) {
        var name = MASTERY_NAMES[entry.tierAfter];
        if (entry.tierAfter > entry.tierBefore)       tierTag = '<span class="res-change-tier tier-up '+colorClass+'">↑ '+name+'</span>';
        else if (entry.tierAfter < entry.tierBefore)  tierTag = '<span class="res-change-tier tier-down '+colorClass+'">↓ '+name+'</span>';
        else                                           tierTag = '<span class="res-change-tier tier-same '+colorClass+'">'+name+'</span>';
      }
      var rawA = entry.a.length > 45 ? entry.a.slice(0,45)+'…' : entry.a;
      return '<div class="res-change-row '+rowClass+'" onclick="showResCardPopup('+i+')" style="cursor:pointer">'
        +'<span class="res-change-icon">'+(entry.correct?'✓':'✗')+'</span>'
        +'<span class="res-change-q">'+renderMD(rawA)+'</span>'
        +tierTag
      +'</div>';
    }).join('');

    show('results');
    if (pct >= 80) setTimeout(function(){ launchCelebration(); }, 200);
  }
}

// ── CELEBRATIONS ──
var _celebRaf = null;

function launchCelebration() {
  if (studyDeckPrefersReducedMotion()) {
    stopCelebration();
    return;
  }
  var effects = [doConfetti, doLasers, doBalloons, doFireworks];
  var fn = effects[Math.floor(Math.random() * effects.length)];
  fn();
}

function getCelebCanvas() {
  var c = document.getElementById('celebrate-canvas');
  c.style.display = 'block';
  var rect = c.getBoundingClientRect();
  var dpr = Math.max(1, window.devicePixelRatio || 1);
  var w = Math.max(1, Math.round(rect.width || window.innerWidth || 1));
  var h = Math.max(1, Math.round(rect.height || window.innerHeight || 1));
  c.width  = Math.round(w * dpr);
  c.height = Math.round(h * dpr);
  c._celebWidth = w;
  c._celebHeight = h;
  c._celebDpr = dpr;
  return c;
}
function getCelebContext(c) {
  var ctx = c.getContext('2d');
  var dpr = c._celebDpr || 1;
  if (ctx && ctx.setTransform) ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return ctx;
}

function stopCelebration() {
  if (_celebRaf) { cancelAnimationFrame(_celebRaf); _celebRaf = null; }
  var c = document.getElementById('celebrate-canvas');
  if (c) {
    c.style.display = 'none';
    var ctx = c.getContext('2d');
    if (ctx) {
      if (ctx.setTransform) ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0,0,c.width,c.height);
    }
  }
}

// ── CONFETTI ──
function doConfetti() {
  var c = getCelebCanvas(), ctx = getCelebContext(c);
  var W = c._celebWidth || c.width, H = c._celebHeight || c.height;
  var colors = ['#F59E0B','#10B981','#3B82F6','#8B5CF6','#EF4444','#EC4899','#ffffff'];
  var pieces = [];
  for (var i = 0; i < 160; i++) {
    pieces.push({
      x: Math.random() * W, y: -10 - Math.random() * H * 0.5,
      w: 6 + Math.random() * 8, h: 4 + Math.random() * 5,
      color: colors[Math.floor(Math.random() * colors.length)],
      angle: Math.random() * Math.PI * 2,
      spin: (Math.random() - 0.5) * 0.3,
      vx: (Math.random() - 0.5) * 3,
      vy: 2 + Math.random() * 4,
      alpha: 1
    });
  }
  var start = Date.now();
  function frame() {
    ctx.clearRect(0, 0, W, H);
    var elapsed = Date.now() - start;
    var done = true;
    pieces.forEach(function(p) {
      p.x += p.vx; p.y += p.vy; p.angle += p.spin;
      if (elapsed > 1800) p.alpha -= 0.018;
      if (p.y < H + 20 && p.alpha > 0) done = false;
      ctx.save();
      ctx.globalAlpha = Math.max(0, p.alpha);
      ctx.translate(p.x, p.y);
      ctx.rotate(p.angle);
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.w/2, -p.h/2, p.w, p.h);
      ctx.restore();
    });
    if (!done) { _celebRaf = requestAnimationFrame(frame); }
    else stopCelebration();
  }
  _celebRaf = requestAnimationFrame(frame);
}

// ── LASERS ──
function doLasers() {
  var c = getCelebCanvas(), ctx = getCelebContext(c);
  var W = c._celebWidth || c.width, H = c._celebHeight || c.height;
  var colors = ['#F59E0B','#10B981','#3B82F6','#8B5CF6','#EF4444','#EC4899'];
  var cx = W / 2, cy = H * 0.45;
  var beams = [];
  var count = 16;
  for (var i = 0; i < count; i++) {
    beams.push({ angle: (i / count) * Math.PI * 2, color: colors[i % colors.length], len: 0, maxLen: W * 0.85 });
  }
  var start = Date.now();
  function frame() {
    ctx.clearRect(0, 0, W, H);
    var elapsed = Date.now() - start;
    var t = elapsed / 1200;
    var alpha = t < 0.7 ? 1 : Math.max(0, 1 - (t - 0.7) / 0.5);
    var done = alpha <= 0;
    beams.forEach(function(b) {
      b.len = Math.min(b.maxLen, b.maxLen * Math.min(1, t * 2));
      var ex = cx + Math.cos(b.angle) * b.len;
      var ey = cy + Math.sin(b.angle) * b.len;
      var grad = ctx.createLinearGradient(cx, cy, ex, ey);
      grad.addColorStop(0, b.color);
      grad.addColorStop(1, 'transparent');
      ctx.save();
      ctx.globalAlpha = alpha * 0.85;
      ctx.strokeStyle = grad;
      ctx.lineWidth = 3 + Math.sin(elapsed * 0.01 + b.angle) * 1.5;
      ctx.shadowColor = b.color;
      ctx.shadowBlur = 12;
      ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(ex, ey); ctx.stroke();
      ctx.restore();
    });
    // Pulsing center circle
    ctx.save();
    ctx.globalAlpha = alpha * 0.9;
    ctx.fillStyle = '#F59E0B';
    ctx.shadowColor = '#F59E0B'; ctx.shadowBlur = 20;
    ctx.beginPath(); ctx.arc(cx, cy, 8 + Math.sin(elapsed * 0.01) * 3, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
    if (!done) _celebRaf = requestAnimationFrame(frame);
    else stopCelebration();
  }
  _celebRaf = requestAnimationFrame(frame);
}

// ── BALLOONS ──
function doBalloons() {
  var c = getCelebCanvas(), ctx = getCelebContext(c);
  var W = c._celebWidth || c.width, H = c._celebHeight || c.height;
  var colors = ['#F59E0B','#10B981','#3B82F6','#8B5CF6','#EF4444','#EC4899','#ffffff'];
  var balloons = [];
  for (var i = 0; i < 22; i++) {
    balloons.push({
      x: Math.random() * W,
      y: H + 40 + Math.random() * 200,
      r: 18 + Math.random() * 18,
      color: colors[Math.floor(Math.random() * colors.length)],
      vx: (Math.random() - 0.5) * 1.2,
      vy: -(1.5 + Math.random() * 2.5),
      sway: Math.random() * Math.PI * 2,
      swaySpeed: 0.02 + Math.random() * 0.02,
      alpha: 1
    });
  }
  var start = Date.now();
  function frame() {
    ctx.clearRect(0, 0, W, H);
    var elapsed = Date.now() - start;
    var done = true;
    balloons.forEach(function(b) {
      b.y += b.vy;
      b.sway += b.swaySpeed;
      b.x += Math.sin(b.sway) * 0.8 + b.vx;
      if (elapsed > 2000) b.alpha -= 0.012;
      if (b.y > -b.r * 3 && b.alpha > 0) done = false;
      ctx.save();
      ctx.globalAlpha = Math.max(0, b.alpha);
      // Balloon body
      ctx.beginPath();
      ctx.ellipse(b.x, b.y, b.r, b.r * 1.25, 0, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.shadowColor = b.color; ctx.shadowBlur = 8;
      ctx.fill();
      // Shine
      ctx.beginPath();
      ctx.ellipse(b.x - b.r*0.28, b.y - b.r*0.35, b.r*0.22, b.r*0.18, -0.5, 0, Math.PI*2);
      ctx.fillStyle = 'rgba(255,255,255,0.45)';
      ctx.shadowBlur = 0;
      ctx.fill();
      // String
      ctx.beginPath();
      ctx.moveTo(b.x, b.y + b.r * 1.25);
      ctx.quadraticCurveTo(b.x + b.r * 0.3, b.y + b.r * 2.2, b.x, b.y + b.r * 3.2);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 1;
      ctx.shadowBlur = 0;
      ctx.stroke();
      ctx.restore();
    });
    if (!done) _celebRaf = requestAnimationFrame(frame);
    else stopCelebration();
  }
  _celebRaf = requestAnimationFrame(frame);
}

// ── FIREWORKS ──
function doFireworks() {
  var c = getCelebCanvas(), ctx = getCelebContext(c);
  var W = c._celebWidth || c.width, H = c._celebHeight || c.height;
  var colors = ['#F59E0B','#10B981','#3B82F6','#8B5CF6','#EF4444','#EC4899','#ffffff','#FCD34D'];
  var particles = [];

  function burst(x, y) {
    var col = colors[Math.floor(Math.random() * colors.length)];
    for (var i = 0; i < 55; i++) {
      var angle = (i / 55) * Math.PI * 2;
      var speed = 2 + Math.random() * 5;
      particles.push({
        x: x, y: y,
        vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
        color: col, alpha: 1, r: 2 + Math.random() * 2.5, trail: []
      });
    }
  }

  // Launch 4-5 bursts staggered
  var bursts = [
    { t: 0,   x: W*0.3, y: H*0.25 },
    { t: 250, x: W*0.7, y: H*0.2  },
    { t: 450, x: W*0.5, y: H*0.35 },
    { t: 650, x: W*0.2, y: H*0.3  },
    { t: 800, x: W*0.8, y: H*0.28 },
  ];
  var start = Date.now();

  function frame() {
    ctx.fillStyle = 'rgba(13,17,23,0.18)';
    ctx.fillRect(0, 0, W, H);
    var elapsed = Date.now() - start;
    bursts.forEach(function(b) { if (elapsed >= b.t && !b.fired) { b.fired = true; burst(b.x, b.y); } });
    var active = false;
    particles.forEach(function(p) {
      p.trail.push({x: p.x, y: p.y});
      if (p.trail.length > 5) p.trail.shift();
      p.x += p.vx; p.y += p.vy;
      p.vy += 0.08; // gravity
      p.vx *= 0.97; p.vy *= 0.97;
      p.alpha -= 0.013;
      if (p.alpha > 0) {
        active = true;
        // Trail
        p.trail.forEach(function(pt, ti) {
          ctx.save();
          ctx.globalAlpha = (ti / p.trail.length) * p.alpha * 0.4;
          ctx.fillStyle = p.color;
          ctx.beginPath(); ctx.arc(pt.x, pt.y, p.r * 0.6, 0, Math.PI*2); ctx.fill();
          ctx.restore();
        });
        ctx.save();
        ctx.globalAlpha = Math.max(0, p.alpha);
        ctx.fillStyle = p.color;
        ctx.shadowColor = p.color; ctx.shadowBlur = 6;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI*2); ctx.fill();
        ctx.restore();
      }
    });
    particles = particles.filter(function(p){ return p.alpha > 0; });
    var stillBursting = bursts.some(function(b){ return !b.fired; });
    if (active || stillBursting) _celebRaf = requestAnimationFrame(frame);
    else stopCelebration();
  }
  _celebRaf = requestAnimationFrame(frame);
}

// ── CALENDAR ──
var _calYear  = null;
var _calMonth = null; // 0-indexed

function renderCalendar() {
  var now = new Date();
  if (_calYear === null) { _calYear = now.getFullYear(); _calMonth = now.getMonth(); }
  var days = gd.studyDays || {};
  var studiedCount = Object.values(days).filter(function(v){ return v==='studied'; }).length;
  var freezeCount  = Object.values(days).filter(function(v){ return v==='freeze'; }).length;

  document.getElementById('cal-streak').textContent       = gd.streak || 0;
  document.getElementById('cal-studied-days').textContent = studiedCount;
  document.getElementById('cal-freezes-used').textContent = freezeCount;

  var MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  document.getElementById('cal-month-label').textContent = MONTHS[_calMonth] + ' ' + _calYear;

  var today = todayStr();
  var firstDay = new Date(_calYear, _calMonth, 1).getDay(); // 0=Sun
  var daysInMonth = new Date(_calYear, _calMonth + 1, 0).getDate();

  var DOWS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var html = DOWS.map(function(d){ return '<div class="cal-dow">'+d+'</div>'; }).join('');

  // Empty cells before first day
  for (var i = 0; i < firstDay; i++) html += '<div class="cal-day"></div>';

  for (var d = 1; d <= daysInMonth; d++) {
    var dateStr = _calYear + '-'
      + String(_calMonth + 1).padStart(2,'0') + '-'
      + String(d).padStart(2,'0');
    var status = days[dateStr] || '';
    var isToday = dateStr === today;
    var isFuture = dateStr > today;
    var cls = 'cal-day';
    if (status === 'studied') cls += ' studied';
    else if (status === 'freeze') cls += ' freeze';
    if (isToday) cls += ' today';
    if (isFuture) cls += ' future';
    html += '<div class="'+cls+'">'+d+'</div>';
  }

  document.getElementById('cal-grid').innerHTML = html;
}

function calPrevMonth() {
  _calMonth--;
  if (_calMonth < 0) { _calMonth = 11; _calYear--; }
  renderCalendar();
}
function calNextMonth() {
  _calMonth++;
  if (_calMonth > 11) { _calMonth = 0; _calYear++; }
  renderCalendar();
}

