function openBQRef() {
  document.getElementById('bq-ref-modal').style.display = 'flex';
  studyDeckOpenDialog('bq-ref-modal', { focusSelector: '#bq-ref-modal button' });
}
function closeBQRef() {
  document.getElementById('bq-ref-modal').style.display = 'none';
  studyDeckCloseDialog('bq-ref-modal');
}

function bqAlphaKey(name) {
  // Strip leading number+space for sort: "1 Samuel" → "S", "2 Kings" → "K"
  return name.replace(/^\d+\s+/, '').toLowerCase();
}

function toggleBQRef() {
  var p = document.getElementById('bq-ref-panel');
  p.style.display = p.style.display === 'none' ? '' : 'none';
}

function startOrderQuiz() {
  startBookOrder('quiz');
}

function startOrderGuide() {
  startBookOrder('guide');
}

function restartBQ() {
  startBookOrder(bqState.mode === 'guide' ? 'guide' : 'quiz');
}

function startBookOrder(mode) {
  touchStreak();
  bqState.mode = mode === 'guide' ? 'guide' : 'quiz';
  bqState.submitted = false;
  bqState.ot = []; bqState.nt = [];
  var all = BIBLE_BOOKS_OT.concat(BIBLE_BOOKS_NT);
  // Sort alphabetically, treating leading numbers as their first letter
  all.sort(function(a, b) {
    return bqAlphaKey(a) < bqAlphaKey(b) ? -1 : bqAlphaKey(a) > bqAlphaKey(b) ? 1 : 0;
  });
  bqState.queue = all;
  document.getElementById('bq-submit').style.display = 'none';
  document.getElementById('bq-retry').style.display  = 'none';
  document.getElementById('bq-score-badge').style.display = 'none';
  renderBQ();
  show('books-quiz');
}

function renderBQ() {
  var isGuide = bqState.mode === 'guide';
  renderBQQueue();
  renderBQZone('ot');
  renderBQZone('nt');
  updateBQCounts();
  var titleEl = document.getElementById('bq-title');
  if (titleEl) titleEl.textContent = isGuide ? 'Books Order Guide' : 'Books Order Quiz';
  var queueLabel = document.getElementById('bq-queue-label');
  if (queueLabel) {
    queueLabel.innerHTML = (isGuide ? 'Queue — choose the next book ' : 'Queue — alphabetical ')
      + '<span id="bq-queue-count" style="color:var(--gold)"></span>';
    updateBQCounts();
  }
  var submitEl = document.getElementById('bq-submit');
  var retryEl  = document.getElementById('bq-retry');
  var badgeEl  = document.getElementById('bq-score-badge');
  if (isGuide) {
    submitEl.style.display = 'none';
    retryEl.style.display  = '';
    retryEl.textContent = bqState.queue.length ? 'Start Over' : 'Review Again';
    if (badgeEl) {
      var placed = bqState.ot.length + bqState.nt.length;
      badgeEl.style.display = '';
      badgeEl.textContent = placed + ' / 66 placed';
      badgeEl.style.background = placed === 66 ? 'rgba(16,185,129,0.15)' : 'rgba(59,130,246,0.13)';
      badgeEl.style.color = placed === 66 ? '#10B981' : 'var(--blue)';
    }
  } else if (!bqState.submitted) {
    submitEl.style.display = bqState.queue.length === 0 ? '' : 'none';
    retryEl.style.display  = 'none';
    retryEl.textContent = 'Try Again';
    if (badgeEl) badgeEl.style.display = 'none';
  } else {
    submitEl.style.display = 'none';
    retryEl.style.display  = '';
    retryEl.textContent = 'Try Again';
  }
}

function updateBQCounts() {
  document.getElementById('bq-queue-count').textContent = bqState.queue.length ? '('+bqState.queue.length+' remaining)' : '(empty)';
  document.getElementById('bq-ot-count').textContent   = bqState.ot.length ? '('+bqState.ot.length+')' : '';
  document.getElementById('bq-nt-count').textContent   = bqState.nt.length ? '('+bqState.nt.length+')' : '';
}

function renderBQQueue() {
  var el = document.getElementById('bq-queue');
  el.innerHTML = '';
  var nextOT = bqState.mode === 'guide' ? bqExpectedNext('ot') : '';
  var nextNT = bqState.mode === 'guide' ? bqExpectedNext('nt') : '';
  bqState.queue.forEach(function(book, i) {
    var chip = document.createElement('div');
    chip.className = 'bq-book';
    if (book === nextOT) chip.className += ' guide-next-ot';
    if (book === nextNT) chip.className += ' guide-next-nt';
    chip.textContent = book;
    chip.dataset.book = book;
    chip.dataset.from = 'queue';
    chip.dataset.idx  = i;
    bindBQDrag(chip);
    el.appendChild(chip);
  });
  if (!bqState.queue.length) {
    el.innerHTML = '<span style="font-size:12px;color:var(--muted);padding:4px">All books placed!</span>';
  }
}

function renderBQZone(zone) {
  var el = document.getElementById('bq-'+zone);
  el.innerHTML = '';
  bqState[zone].forEach(function(book, i) {
    var row = document.createElement('div');
    row.className = 'bq-placed' + (bqState.submitted ? (isCorrectPlacement(book, zone, i) ? ' correct' : ' wrong') : '');
    row.dataset.book = book;
    row.dataset.from = zone;
    row.dataset.idx  = i;
    row.innerHTML = '<span class="bq-num">'+(i+1)+'</span><span>'+escHtml(book)+'</span>';
    if (!bqState.submitted && bqState.mode !== 'guide') bindBQDrag(row);
    el.appendChild(row);
  });
  // Always-visible end drop target
  if (!bqState.submitted) {
    var endDrop = document.createElement('div');
    endDrop.className = 'bq-end-drop';
    endDrop.dataset.endZone = zone;
    if (bqState.mode === 'guide') {
      var nextBook = bqExpectedNext(zone);
      endDrop.className += nextBook ? ' guide-next guide-next-' + zone : ' guide-complete';
      endDrop.textContent = nextBook || 'Complete';
    } else {
      endDrop.textContent = '+ drop here';
    }
    el.appendChild(endDrop);
    // Scroll to show end drop when something was just added
  }
}

function isCorrectPlacement(book, zone, idx) {
  var correctList = zone === 'ot' ? BIBLE_BOOKS_OT : BIBLE_BOOKS_NT;
  return correctList[idx] === book;
}

function bqExpectedNext(zone) {
  var list = zone === 'ot' ? BIBLE_BOOKS_OT : BIBLE_BOOKS_NT;
  return list[bqState[zone].length] || '';
}

function bqCanDropBook(book, dest, fromZone) {
  if (bqState.mode !== 'guide') return true;
  if (fromZone !== 'queue') return false;
  if (dest !== 'ot' && dest !== 'nt') return false;
  return bqExpectedNext(dest) === book;
}

// ── DRAG AND DROP (unified pointer events) ──
function bindBQDrag(el) {
  el.addEventListener('pointerdown', bqPointerDown);
}

function bqPointerDown(e) {
  if (bqState.submitted) return;
  var src = e.currentTarget;

  if (e.pointerType === 'touch') {
    bqPendingDrag = {
      src: src,
      startX: e.clientX,
      startY: e.clientY,
      lastX: e.clientX,
      lastY: e.clientY,
      pointerId: e.pointerId,
      timer: null
    };
    bqPendingDrag.timer = setTimeout(function(){
      if (!bqPendingDrag) return;
      var p = bqPendingDrag;
      bqPendingDrag = null;
      bqBeginDrag(p.src, p.lastX, p.lastY, p.pointerId);
    }, 280);
    document.addEventListener('pointermove', bqPointerMove, { passive: false });
    document.addEventListener('pointerup', bqPointerUp);
    document.addEventListener('pointercancel', bqPointerUp);
    return;
  }

  e.preventDefault();
  bqBeginDrag(src, e.clientX, e.clientY, e.pointerId);
  document.addEventListener('pointermove', bqPointerMove, { passive: false });
  document.addEventListener('pointerup', bqPointerUp);
  document.addEventListener('pointercancel', bqPointerUp);
}

function bqClearPendingDrag(removeListeners) {
  if (!bqPendingDrag) return;
  if (bqPendingDrag.timer) clearTimeout(bqPendingDrag.timer);
  bqPendingDrag = null;
  if (removeListeners) {
    document.removeEventListener('pointermove', bqPointerMove);
    document.removeEventListener('pointerup', bqPointerUp);
    document.removeEventListener('pointercancel', bqPointerUp);
  }
}

function bqReleasePointerCapture() {
  var src = bqDrag && bqDrag.capturedEl;
  var pointerId = bqDrag && bqDrag.pointerId;
  if (!src || pointerId == null || !src.releasePointerCapture) return;
  try {
    if (!src.hasPointerCapture || src.hasPointerCapture(pointerId)) src.releasePointerCapture(pointerId);
  } catch (_) {}
}

function bqBeginDrag(src, clientX, clientY, pointerId) {
  var book     = src.dataset.book;
  var fromZone = src.dataset.from;
  var fromIdx  = parseInt(src.dataset.idx, 10);
  var rect     = src.getBoundingClientRect();

  // Create floating clone
  var clone = document.createElement('div');
  clone.className = 'bq-dragging-clone';
  clone.textContent = book;
  document.body.appendChild(clone);

  // Make source ghost
  src.classList.add('ghost');

  bqDrag = {
    book: book, fromZone: fromZone, fromIdx: fromIdx,
    clone: clone, ghost: src,
    offsetX: clientX - rect.left,
    offsetY: clientY - rect.top,
    capturedEl: src,
    pointerId: pointerId
  };

  moveClone(clientX, clientY);

  try {
    if (src.setPointerCapture && pointerId != null) src.setPointerCapture(pointerId);
  } catch (_) {}
}

function moveClone(cx, cy) {
  var c = bqDrag.clone;
  if (!c) return;
  c.style.left = (cx - bqDrag.offsetX) + 'px';
  c.style.top  = (cy - bqDrag.offsetY) + 'px';
}

function bqFindZone(el) {
  while (el) {
    if (el.id === 'bq-queue' || el.id === 'bq-ot' || el.id === 'bq-nt') return el;
    el = el.parentElement;
  }
  return null;
}

function bqPointerMove(e) {
  if (bqPendingDrag && !bqDrag.clone) {
    var dx = e.clientX - bqPendingDrag.startX;
    var dy = e.clientY - bqPendingDrag.startY;
    var absX = Math.abs(dx);
    var absY = Math.abs(dy);
    bqPendingDrag.lastX = e.clientX;
    bqPendingDrag.lastY = e.clientY;

    if (absY > 7 && absY > absX + 2) {
      bqClearPendingDrag(true);
      return;
    }
    if (absX > 10 && absX > absY + 2) {
      if (e.cancelable) e.preventDefault();
      var p = bqPendingDrag;
      bqClearPendingDrag(false);
      bqBeginDrag(p.src, e.clientX, e.clientY, p.pointerId);
    } else {
      return;
    }
  }

  if (!bqDrag.clone) return;
  if (e.cancelable) e.preventDefault();
  moveClone(e.clientX, e.clientY);
  ['bq-queue','bq-ot','bq-nt'].forEach(function(id){
    document.getElementById(id).classList.remove('drag-over');
  });
  document.querySelectorAll('.bq-end-drop').forEach(function(el){ el.classList.remove('drop-here'); });
  var el = document.elementFromPoint(e.clientX, e.clientY);
  var zone = bqFindZone(el);
  if (zone) {
    var dest = zone.id === 'bq-queue' ? 'queue' : (zone.id === 'bq-ot' ? 'ot' : 'nt');
    var canDrop = bqCanDropBook(bqDrag.book, dest, bqDrag.fromZone);
    if (canDrop) zone.classList.add('drag-over');
    // If hovering over end-drop, highlight it
    var endEl = bqFindEndDrop(el);
    if (endEl && canDrop) endEl.classList.add('drop-here');
  }
}

function bqFindEndDrop(el) {
  while (el) {
    if (el.classList && el.classList.contains('bq-end-drop')) return el;
    el = el.parentElement;
  }
  return null;
}

function bqPointerUp(e) {
  if (bqPendingDrag && !bqDrag.clone) {
    bqClearPendingDrag(true);
    return;
  }

  document.removeEventListener('pointermove', bqPointerMove);
  document.removeEventListener('pointerup',   bqPointerUp);
  document.removeEventListener('pointercancel', bqPointerUp);
  bqReleasePointerCapture();

  ['bq-queue','bq-ot','bq-nt'].forEach(function(id){
    document.getElementById(id).classList.remove('drag-over');
  });
  document.querySelectorAll('.bq-end-drop').forEach(function(el){ el.classList.remove('drop-here'); });

  if (bqDrag.clone) { bqDrag.clone.remove(); bqDrag.clone = null; }
  if (bqDrag.ghost) { bqDrag.ghost.classList.remove('ghost'); }

  var under = document.elementFromPoint(e.clientX, e.clientY);
  var zone  = bqFindZone(under);
  if (!zone) { bqDrag = {}; return; }

  var targetId = zone.id;
  var book     = bqDrag.book;
  var fromZone = bqDrag.fromZone;
  var fromIdx  = bqDrag.fromIdx;
  var dest = targetId === 'bq-queue' ? 'queue' : (targetId === 'bq-ot' ? 'ot' : 'nt');

  if (!bqCanDropBook(book, dest, fromZone)) {
    bqDrag = {};
    return;
  }

  // Remove from source
  if (fromZone === 'queue') {
    bqState.queue.splice(fromIdx, 1);
  } else {
    bqState[fromZone].splice(fromIdx, 1);
  }

  if (dest === 'queue') {
    bqState.queue.push(book);
  } else {
    // Check if dropped on end-drop target → append to end
    var endEl = bqFindEndDrop(under);
    if (endEl) {
      bqState[dest].push(book);
    } else {
      // Insert at position based on pointer Y
      var children = Array.from(zone.querySelectorAll('.bq-placed'));
      var insertAt = bqState[dest].length;
      for (var i = 0; i < children.length; i++) {
        var r = children[i].getBoundingClientRect();
        if (e.clientY < r.top + r.height / 2) { insertAt = i; break; }
      }
      bqState[dest].splice(insertAt, 0, book);
    }
    // Scroll zone to show the newly placed item
    setTimeout(function() {
      var zoneEl = document.getElementById('bq-'+dest);
      if (zoneEl) zoneEl.scrollTop = zoneEl.scrollHeight;
    }, 50);
  }

  bqDrag = {};
  renderBQ();
}

function submitOrderQuiz() {
  if (bqState.queue.length > 0) return;
  bqState.submitted = true;

  // Score
  var correct = 0, total = bqState.ot.length + bqState.nt.length;
  bqState.ot.forEach(function(b, i){ if (isCorrectPlacement(b,'ot',i)) correct++; });
  bqState.nt.forEach(function(b, i){ if (isCorrectPlacement(b,'nt',i)) correct++; });
  var pct = Math.round(correct / 66 * 100);

  // XP
  var xp = Math.round(pct / 100 * 50) + (pct === 100 ? 100 : 0);
  gd.xp += xp; saveGameData(); renderHomeGamification();
  if (xp > 0) showXpToast('+' + xp + ' XP');
  if (pct >= 80) setTimeout(launchCelebration, 200);

  var badge = document.getElementById('bq-score-badge');
  badge.textContent = correct + ' / 66 correct (' + pct + '%)';
  badge.style.display = '';
  badge.style.background = pct >= 80 ? 'rgba(16,185,129,0.15)' : 'rgba(239,68,68,0.12)';
  badge.style.color      = pct >= 80 ? '#10B981' : '#EF4444';

  renderBQ();
}

