function normalizeDeckKey(name) {
  return String(name || '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getDeckIconSVG(name) {
  var key = normalizeDeckKey(name);
  key = DECK_ICON_ALIASES[key] || key;
  if (DECK_ICON_SVGS[key]) return DECK_ICON_SVGS[key];

  if (key.indexOf('passage') !== -1 || key.indexOf('quote') !== -1) return DECK_ICON_SVGS['popular passages'];
  if (key.indexOf('character') !== -1 || key.indexOf('people') !== -1) return DECK_ICON_SVGS['characters'];
  if (key.indexOf('book') !== -1) return DECK_ICON_SVGS['books'];
  if (key.indexOf('stor') !== -1 || key.indexOf('narrative') !== -1) return DECK_ICON_SVGS['stories'];
  if (key.indexOf('atrocit') !== -1 || key.indexOf('moral') !== -1 || key.indexOf('violence') !== -1) return DECK_ICON_SVGS['atrocities'];
  if (key.indexOf('geograph') !== -1 || key.indexOf('location') !== -1 || key.indexOf('map') !== -1) return DECK_ICON_SVGS['geography'];
  if (key.indexOf('tension') !== -1 || key.indexOf('contradiction') !== -1) return DECK_ICON_SVGS['textual tensions'];
  if (key.indexOf('ot in the nt') !== -1 || (key.indexOf('old testament') !== -1 && key.indexOf('new testament') !== -1)) return DECK_ICON_SVGS['ot in the nt'];
  if (key.indexOf('parallel') !== -1) return DECK_ICON_SVGS['non-biblical parallels'];
  if (key.indexOf('timeline') !== -1 || key.indexOf('attribution') !== -1 || key.indexOf('author') !== -1 || key.indexOf('dating') !== -1) return DECK_ICON_SVGS['timeline and attribution'];
  if (key.indexOf('jesus') !== -1 || key.indexOf('messiah') !== -1 || key.indexOf('christ') !== -1) return DECK_ICON_SVGS['jesus messiah'];
  if (key.indexOf('comparison') !== -1 || key.indexOf('compare') !== -1) return DECK_ICON_SVGS['comparisons'];
  return DECK_ICON_SVGS['default'];
}

function renderHome() {
  var lb = document.getElementById('lock-btn');
  if (lb) {
    lb.textContent = authorMode ? '🔓' : '🔒';
    lb.classList.toggle('unlocked', authorMode);
    lb.title = authorMode ? 'Lock author mode' : 'Author access';
  }
  populateAppStyleSelect();
  renderGuidedEntry();
  if (typeof renderTimelineHomeEntry === 'function') renderTimelineHomeEntry();
  renderHomeGamification();
  renderRecentAchievement();
  if (typeof refreshStyleLabView === 'function') refreshStyleLabView();
}

function renderDecks() {
  var addBtn = document.getElementById('add-deck-btn');
  var authorTools = document.getElementById('author-tools');
  var deckCount = document.getElementById('deck-count');
  var deckList = document.getElementById('deck-list');
  if (addBtn) addBtn.style.display = authorMode ? '' : 'none';
  if (authorTools) authorTools.style.display = authorMode ? 'flex' : 'none';
  if (deckCount) {
    deckCount.textContent = decks.length + ' collection' + (decks.length!==1?'s':'');
  }
  if (!deckList) return;
  var totalCards = decks.reduce(function(n,d){ return n+d.cards.length; }, 0);
  var allDeckCard = '<div class="deck-card deck-card-all" data-sl-ref-color="#E8E3D9" onclick="openAllDecks()" style="'+styleLabReferenceStyle('#E8E3D9')+'">'
    +'<div class="deck-name" style="color:#E8E3D9">All Decks</div>'
    +'<div class="deck-desc">Every card from every collection</div>'
    +'<div class="deck-meta">'
      +'<span class="meta-pill">🃏 '+totalCards+' cards total</span>'
      +'<span class="meta-pill" style="margin-left:auto;font-size:11px;color:rgba(255,255,255,0.25)">'+decks.length+' decks</span>'
    +'</div>'
  +'</div>';

  deckList.innerHTML = decks.map(function(d, idx){
    var isFirst = idx === 0, isLast = idx === decks.length - 1;
    var unlockedLevel = getDeckUnlockedLevel(d.id);
    var unlockedCount = d.cards.filter(function(c){ return (c.level||1) <= unlockedLevel; }).length;
    var totalScore = 0;
    d.cards.forEach(function(c){
      var m = getMastery(d.id, c.id);
      totalScore += (m.score || 0);
    });
    var maxScore = d.cards.length * 20;
    var masteryPct = maxScore > 0 ? Math.round(totalScore / maxScore * 100) : 0;
    var reorderHTML = authorMode
      ? '<div class="deck-reorder">'
          +'<button class="reorder-btn" '+(isFirst?'disabled':'')+' onclick="moveDeck('+d.id+',-1,event)" title="Move up">↑</button>'
          +'<button class="reorder-btn" '+(isLast?'disabled':'')+' onclick="moveDeck('+d.id+',1,event)" title="Move down">↓</button>'
        +'</div>'
      : '';
    var namePad = authorMode ? 'padding-left:40px;padding-right:56px' : '';
    var crowned = masteryPct === 100;
    var deckColor = styleLabNormalizeHex(d.color, '#4FCFFF');
    var levelBadge = !authorMode
      ? '<span class="meta-pill" style="color:var(--gold);background:rgba(245,158,11,0.1);border-color:rgba(245,158,11,0.25)">Lv '+unlockedLevel+'</span>'
      : '';
    var deckIcon = getDeckIconSVG(d.name);
    return '<div class="deck-card" data-sl-ref-color="'+deckColor+'" onclick="openDeck('+d.id+')" style="position:relative;border-color:'+deckColor+'22;'+styleLabReferenceStyle(deckColor)+'">'
      +'<div class="deck-accent" style="background:linear-gradient(105deg,'+deckColor+'26 0%,'+deckColor+'0a 45%,transparent 70%)"></div>'
      +(deckIcon ? '<div class="deck-topic-icon" style="color:'+deckColor+'">'+deckIcon+'</div>' : '')
      +reorderHTML
      +(authorMode ? '<button class="deck-edit-btn" onclick="event.stopPropagation();showEditDeck('+d.id+')">✏ Edit</button>' : '')
      +(crowned ? '<div class="deck-crown" title="Deck fully mastered!">👑</div>' : '')
      +'<div class="deck-name" style="color:'+deckColor+';'+namePad+'">'+d.name+'</div>'
      +'<div class="deck-desc" style="'+(authorMode?'padding-left:40px':'')+'">'+d.desc+'</div>'
      +'<div class="deck-meta" style="'+(authorMode?'padding-left:40px':'')+'">'
        +'<span class="meta-pill">🃏 '+(authorMode ? d.cards.length+' cards' : unlockedCount+' / '+d.cards.length+' unlocked')+'</span>'
        +levelBadge
        +'<span class="score-badge" style="background:'+deckColor+'22;color:'+deckColor+'">'+masteryPct+'%</span>'
      +'</div>'
    +'</div>';
  }).join('') + allDeckCard;
  if (typeof refreshStyleLabView === 'function') refreshStyleLabView();
}

function renderRecentAchievement() {
  var iconEl = document.getElementById('home-achievement-icon');
  var titleEl = document.getElementById('home-achievement-title');
  var subEl = document.getElementById('home-achievement-sub');
  if (!iconEl || !titleEl || !subEl) return;
  var earned = (gd.badges || []).map(function(id){
    return BADGE_DEFS.find(function(b){ return b.id === id; });
  }).filter(Boolean);
  var latest = earned.length ? earned[earned.length - 1] : null;
  iconEl.textContent = latest ? latest.icon : '✦';
  titleEl.textContent = latest ? latest.name : 'No achievement yet';
  subEl.textContent = latest ? latest.desc : 'Complete a quiz or keep a streak to earn one.';
}

function deckReadinessCards(deck) {
  return deck && Array.isArray(deck.cards) ? deck.cards : [];
}

function deckReadinessText(value) {
  return String(value == null ? '' : value).trim();
}

function deckReadinessDeckText(deck) {
  return [
    deck && deck.name,
    deck && deck.desc,
    deck && deck.description
  ].map(deckReadinessText).join(' ').toLowerCase();
}

function deckReadinessHasCardBasics(card) {
  return !!(card && deckReadinessText(card.q) && deckReadinessText(card.a));
}

function deckReadinessHasEvidence(card) {
  if (!card || typeof card !== 'object') return false;
  if (Array.isArray(card.notes) && card.notes.length) return true;
  if (card.notes && typeof card.notes === 'object' && Object.keys(card.notes).length) return true;
  if (Array.isArray(card.links) && card.links.length) return true;
  return [
    card.evidence,
    card.evidenceNotes,
    card.reference,
    card.references,
    card.sourceReference,
    card.bibleReference,
    card.passage,
    card.verse
  ].some(function(value){
    if (Array.isArray(value)) return value.length > 0;
    if (value && typeof value === 'object') return Object.keys(value).length > 0;
    return !!deckReadinessText(value);
  });
}

function deckReadinessNeedsMap(deck) {
  return /(geograph|\bmaps?\b|\blocations?\b|\bplaces?\b|\bcity\b|\bcities\b|\bregions?\b|\broutes?\b|\bjourneys?\b)/.test(deckReadinessDeckText(deck));
}

function deckReadinessNeedsTimeline(deck) {
  return /(timeline|attribution|\bdates?\b|\bdating\b|chronolog|\brulers?\b|\breigns?\b|\bperiods?\b|\bcentury\b|\bcenturies\b)/.test(deckReadinessDeckText(deck));
}

function deckReadinessNormalizeName(value) {
  if (typeof guidedNormalizeName === 'function') return guidedNormalizeName(value || '');
  return String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function deckReadinessNameMatchesDeck(name, deck) {
  var deckName = deckReadinessNormalizeName(deck && deck.name);
  var wantedName = deckReadinessNormalizeName(name);
  return !!(deckName && wantedName && (deckName === wantedName || deckName.indexOf(wantedName) !== -1 || wantedName.indexOf(deckName) !== -1));
}

function deckReadinessSidecarMatchesDeck(sidecar, deck) {
  if (!sidecar || !deck) return false;
  var meta = sidecar.__studydeckSidecar || {};
  if (meta.matchedDeckId != null && String(meta.matchedDeckId) === String(deck.id)) return true;
  if (sidecar.deckId != null && String(sidecar.deckId) === String(deck.id)) return true;
  if (sidecar.targetDeckId != null && String(sidecar.targetDeckId) === String(deck.id)) return true;
  var names = [
    sidecar.deckName,
    sidecar.sourceDeckName,
    sidecar.deck,
    sidecar.targetDeck,
    meta.matchedDeckName,
    meta.sourceDeckName
  ].filter(deckReadinessText);
  if (names.some(function(name){ return deckReadinessNameMatchesDeck(name, deck); })) return true;
  var category = deckReadinessNormalizeName(sidecar.deckCategory || sidecar.categoryId || meta.deckCategory || '').replace(/-/g, ' ');
  if (category) {
    var deckText = deckReadinessNormalizeName((deck && deck.name || '') + ' ' + (deck && deck.desc || ''));
    var tokens = category.split(/\s+/).filter(function(token){ return token.length > 2; });
    if (tokens.length && tokens.every(function(token){ return deckText.indexOf(token) !== -1; })) return true;
  }
  return false;
}

function deckReadinessStoredGuidedSidecars() {
  if (typeof guidedAuthorStoredSidecars === 'function') return guidedAuthorStoredSidecars();
  return guidedSidecarStore && Array.isArray(guidedSidecarStore.sidecars) ? guidedSidecarStore.sidecars : [];
}

function deckReadinessSidecarIsGuidedLesson(sidecar) {
  if (!sidecar || typeof sidecar !== 'object') return false;
  if (sidecar.sidecarType === 'studydeck-timeline') return false;
  if (sidecar.timelineLearning && !sidecar.guidedLearning) return false;
  return !!(sidecar.guidedLearning || sidecar.sidecarType === 'guidedLearningOverlay' || sidecar.cards);
}

function deckReadinessReportMatchesDeck(report, deck) {
  if (!report || !deck) return false;
  if (report.matchedDeck && String(report.matchedDeck.id) === String(deck.id)) return true;
  return deckReadinessSidecarMatchesDeck(report.sidecar, deck);
}

function deckReadinessGuidedSummary(deck) {
  var sidecars = deckReadinessStoredGuidedSidecars().filter(deckReadinessSidecarIsGuidedLesson);
  var reports = sidecars.map(function(sidecar){
    if (typeof guidedBuildSidecarHealthReport === 'function') return guidedBuildSidecarHealthReport(sidecar);
    return { sidecar: sidecar, totals: { sidecarCards: 0, matchedCards: 0, missingCards: 0, validationErrors: 0, validationWarnings: 0, genericLearnFallbacks: 0 } };
  }).filter(function(report){
    return deckReadinessReportMatchesDeck(report, deck);
  });
  return {
    reports: reports,
    totals: reports.reduce(function(out, report){
      var totals = report && report.totals || {};
      var sidecar = report && report.sidecar || {};
      var entries = typeof guidedAuthorSidecarCardEntries === 'function' ? guidedAuthorSidecarCardEntries(sidecar) : [];
      out.sidecars += 1;
      out.sidecarCards += Number(totals.sidecarCards || entries.length || 0) || 0;
      out.matchedCards += Number(totals.matchedCards || 0) || 0;
      out.missingCards += Number(totals.missingCards || 0) || 0;
      out.validationErrors += Number(totals.validationErrors || 0) || 0;
      out.validationWarnings += Number(totals.validationWarnings || 0) || 0;
      out.genericLearnFallbacks += Number(totals.genericLearnFallbacks || 0) || 0;
      return out;
    }, { sidecars: 0, sidecarCards: 0, matchedCards: 0, missingCards: 0, validationErrors: 0, validationWarnings: 0, genericLearnFallbacks: 0 })
  };
}

function deckReadinessSidecarHasMap(sidecar) {
  if (!sidecar || typeof sidecar !== 'object') return false;
  if (typeof guidedAuthorSidecarUsesMapEvidence === 'function' && guidedAuthorSidecarUsesMapEvidence(sidecar)) return true;
  var sidecarText = [
    sidecar.title,
    sidecar.name,
    sidecar.deckName,
    sidecar.sourceDeckName,
    sidecar.deckCategory,
    sidecar.categoryId
  ].map(deckReadinessText).join(' ').toLowerCase();
  if (/\b(geograph|map|location|place)\b/.test(sidecarText)) return true;
  var entries = typeof guidedAuthorSidecarCardEntries === 'function' ? guidedAuthorSidecarCardEntries(sidecar) : [];
  return entries.some(function(item){
    var entry = item && item.entry || {};
    var gl = entry.guidedLearning || {};
    return !!(entry.mapLocation || gl.mapLocation || gl.maps || gl.mapPanel || gl.mapContext);
  });
}

function deckReadinessCardHasMap(card) {
  if (!card || typeof card !== 'object') return false;
  return !!(card.mapLocation || card.location || card.geo || card.coordinates || card.map);
}

function deckReadinessSidecarHasTimeline(sidecar) {
  if (!sidecar || typeof sidecar !== 'object') return false;
  if (sidecar.sidecarType === 'studydeck-timeline' || sidecar.timelineLearning) return true;
  var entries = typeof guidedAuthorSidecarCardEntries === 'function' ? guidedAuthorSidecarCardEntries(sidecar) : [];
  return entries.some(function(item){
    var entry = item && item.entry || {};
    var gl = entry.guidedLearning || {};
    return !!(entry.timeline || gl.timeline || gl.timelineEvent || gl.timelineLearning);
  });
}

function deckReadinessTimelineSidecars(deck) {
  var sidecars = [];
  if (Array.isArray(window.STUDYDECK_TIMELINE_SIDECARS)) {
    sidecars = sidecars.concat(window.STUDYDECK_TIMELINE_SIDECARS);
  }
  sidecars = sidecars.concat(deckReadinessStoredGuidedSidecars());
  var seen = {};
  return sidecars.filter(function(sidecar){
    if (!deckReadinessSidecarHasTimeline(sidecar)) return false;
    if (!deckReadinessSidecarMatchesDeck(sidecar, deck)) return false;
    var key = [
      sidecar.title || sidecar.name || '',
      sidecar.deckName || sidecar.sourceDeckName || '',
      sidecar.source && sidecar.source.deckFileSha256 || ''
    ].join('|');
    if (seen[key]) return false;
    seen[key] = true;
    return true;
  });
}

function deckReadinessTimelineCoverage(deck) {
  var cards = deckReadinessCards(deck);
  var uidLookup = {};
  cards.forEach(function(card){
    var uid = typeof guidedSidecarCardUid === 'function' ? guidedSidecarCardUid(card) : deckReadinessText(card && card.uid).toUpperCase();
    if (uid) uidLookup[uid] = true;
  });
  var matched = {};
  deckReadinessTimelineSidecars(deck).forEach(function(sidecar){
    var entries = typeof guidedAuthorSidecarCardEntries === 'function' ? guidedAuthorSidecarCardEntries(sidecar) : [];
    entries.forEach(function(item){
      var uid = typeof guidedAuthorSidecarEntryUid === 'function' ? guidedAuthorSidecarEntryUid(item) : item && item.key || '';
      uid = String(uid || '').trim().toUpperCase();
      if (uid && uidLookup[uid]) matched[uid] = true;
    });
  });
  return Object.keys(matched).length;
}

function deckReadinessPushChip(chips, label, status) {
  chips.push({ label: label, status: status || 'ready' });
}

function deckReadinessBuild(deck) {
  var cards = deckReadinessCards(deck);
  var total = cards.length;
  var validCards = cards.filter(deckReadinessHasCardBasics).length;
  var evidenceCards = cards.filter(deckReadinessHasEvidence).length;
  var needsMap = deckReadinessNeedsMap(deck);
  var needsTimeline = deckReadinessNeedsTimeline(deck);
  var guided = deckReadinessGuidedSummary(deck);
  var guidedTotals = guided && guided.totals || {};
  var guidedMatched = Math.min(total, Number(guidedTotals.matchedCards || 0) || 0);
  var guidedSidecarCards = Number(guidedTotals.sidecarCards || 0) || 0;
  var guidedErrors = Number(guidedTotals.validationErrors || 0) || 0;
  var guidedWarnings = Number(guidedTotals.validationWarnings || 0) || 0;
  var guidedFallbacks = Number(guidedTotals.genericLearnFallbacks || 0) || 0;
  var mapReady = cards.some(deckReadinessCardHasMap) || (guided.reports || []).some(function(report){
    return deckReadinessSidecarHasMap(report.sidecar);
  });
  var timelineMatched = deckReadinessTimelineCoverage(deck);
  var chips = [];
  var score = 0;

  if (!total) {
    deckReadinessPushChip(chips, 'No cards yet', 'missing');
    return {
      deck: deck,
      score: 0,
      chips: chips
    };
  }

  score += Math.round(20 * (validCards / total));
  if (validCards === total) deckReadinessPushChip(chips, 'Flashcards ready', 'ready');
  else if (validCards) deckReadinessPushChip(chips, 'Flashcards ' + validCards + '/' + total, 'warning');
  else deckReadinessPushChip(chips, 'Flashcards missing', 'missing');

  if (validCards >= 4) {
    score += 15;
    deckReadinessPushChip(chips, 'Quiz ready', 'ready');
  } else if (validCards) {
    score += 7;
    deckReadinessPushChip(chips, 'Quiz needs 4+ cards', 'warning');
  } else {
    deckReadinessPushChip(chips, 'Quiz missing', 'missing');
  }

  score += Math.round(25 * (guidedMatched / total));
  if (guidedMatched >= Math.ceil(total * 0.85) && !guidedErrors) {
    deckReadinessPushChip(chips, 'Guided ready', guidedWarnings ? 'warning' : 'ready');
  } else if (guidedMatched > 0) {
    deckReadinessPushChip(chips, 'Guided ' + guidedMatched + '/' + total, guidedErrors ? 'missing' : 'warning');
  } else if (guidedSidecarCards > 0) {
    deckReadinessPushChip(chips, 'Guided not matched', 'missing');
  } else {
    deckReadinessPushChip(chips, 'Guided missing', 'missing');
  }
  if (guidedFallbacks) deckReadinessPushChip(chips, 'Fallback questions ' + guidedFallbacks, 'warning');
  if (guidedErrors) deckReadinessPushChip(chips, 'Guided needs repair', 'missing');

  score += Math.round(15 * (evidenceCards / total));
  if (evidenceCards >= Math.ceil(total * 0.85)) deckReadinessPushChip(chips, 'Evidence ready', 'ready');
  else if (evidenceCards) deckReadinessPushChip(chips, 'Evidence ' + evidenceCards + '/' + total, 'warning');
  else deckReadinessPushChip(chips, 'Evidence missing', 'missing');

  var specialScore = 15;
  var specialParts = 0;
  var specialEarned = 0;
  if (needsMap) {
    specialParts += 1;
    if (mapReady) {
      specialEarned += 1;
      deckReadinessPushChip(chips, 'Maps ready', 'ready');
    } else {
      deckReadinessPushChip(chips, 'Maps missing', 'missing');
    }
  } else {
    deckReadinessPushChip(chips, 'Maps optional', 'ready');
  }
  if (needsTimeline) {
    specialParts += 1;
    if (timelineMatched) {
      specialEarned += Math.min(1, timelineMatched / Math.max(1, Math.ceil(total * 0.25)));
      deckReadinessPushChip(chips, 'Timeline ' + timelineMatched + '/' + total, timelineMatched >= Math.ceil(total * 0.25) ? 'ready' : 'warning');
    } else {
      deckReadinessPushChip(chips, 'Timeline missing', 'missing');
    }
  } else {
    deckReadinessPushChip(chips, 'Timeline optional', 'ready');
  }
  score += specialParts ? Math.round(specialScore * (specialEarned / specialParts)) : specialScore;
  score = Math.max(0, Math.min(100, score));

  return {
    deck: deck,
    score: score,
    chips: chips
  };
}

function backupCenterRenderDeckReadiness() {
  var el = document.getElementById('profile-deck-readiness');
  if (!el) return;
  if (!Array.isArray(decks) || !decks.length) {
    el.innerHTML = '<div class="deck-readiness-empty">No decks found yet. Once you add or import decks, this area will show what is ready and what needs attention.</div>';
    return;
  }
  var reports = decks.map(deckReadinessBuild).sort(function(a, b){
    return a.score - b.score || String(a.deck && a.deck.name || '').localeCompare(String(b.deck && b.deck.name || ''));
  });
  el.innerHTML = reports.map(function(report){
    var name = report.deck && report.deck.name || 'Untitled deck';
    var score = Math.round(report.score);
    var color = score >= 85 ? '#22c55e' : (score >= 60 ? '#facc15' : '#f87171');
    return '<div class="deck-readiness-row">'
      + '<div class="deck-readiness-top"><strong>' + escHtml(name) + '</strong><span class="deck-readiness-score">' + score + '%</span></div>'
      + '<div class="deck-readiness-meter" aria-hidden="true"><span style="width:' + escHtml(score) + '%;background:' + escHtml(color) + '"></span></div>'
      + '<div class="deck-readiness-chips">'
      + report.chips.map(function(chip){
        return '<span class="deck-readiness-chip is-' + escHtml(chip.status || 'ready') + '">' + escHtml(chip.label) + '</span>';
      }).join('')
      + '</div>'
      + '</div>';
  }).join('');
}

var GUIDED_WORKBENCH_BATCH_SIZE = 8;
var GUIDED_WORKBENCH_VISIBLE_BATCH_LIMIT = 4;
var guidedWorkbenchReturnCheck = null;
var guidedWorkbenchReturnLastText = '';

var GUIDED_WORKBENCH_RETURN_TEXT_FIELDS = [
  'helperCue',
  'rememberThis',
  'whyThisMatters',
  'teachingPrompt',
  'commonMistake',
  'briefingTitle',
  'harmSummary',
  'eventSummary',
  'ethicalTension',
  'actor',
  'reference',
  'passage'
];
var GUIDED_WORKBENCH_RETURN_ARRAY_FIELDS = [
  'questions',
  'questionBank',
  'learnQuestions',
  'learningQuestions',
  'practiceQuestions',
  'challengeQuestions',
  'contentQuestions',
  'scholarQuestions',
  'briefingScreens',
  'exactPassageDetails'
];
var GUIDED_WORKBENCH_RETURN_OBJECT_FIELDS = [
  'eventStructure',
  'mapLocation'
];

function guidedWorkbenchText(value) {
  return String(value == null ? '' : value).trim();
}

function guidedWorkbenchSnippet(value, max) {
  var text = guidedWorkbenchText(value).replace(/\s+/g, ' ');
  max = Number(max || 0) || 0;
  if (max && text.length > max) return text.slice(0, Math.max(0, max - 1)).trim() + '...';
  return text;
}

function guidedWorkbenchNormalizeUid(value) {
  if (typeof guidedSidecarNormalizeUid === 'function') return guidedSidecarNormalizeUid(value);
  return String(value || '').trim().toUpperCase();
}

function guidedWorkbenchCardUid(card) {
  if (typeof guidedSidecarCardUid === 'function') return guidedSidecarCardUid(card);
  return guidedWorkbenchNormalizeUid(card && (card.uid || card.cardUid || card.guidedUid || ''));
}

function guidedWorkbenchEntryUid(item) {
  if (typeof guidedAuthorSidecarEntryUid === 'function') return guidedAuthorSidecarEntryUid(item);
  var entry = item && item.entry || {};
  return String(entry.cardUid || entry.uid || item && item.key || '').trim();
}

function guidedWorkbenchMatchedUidLookup(deck) {
  var lookup = {};
  var deckUids = {};
  deckReadinessCards(deck).forEach(function(card){
    var uid = guidedWorkbenchCardUid(card);
    if (uid) deckUids[uid] = true;
  });
  var guided = deckReadinessGuidedSummary(deck);
  (guided.reports || []).forEach(function(report){
    var sidecar = report && report.sidecar;
    var entries = typeof guidedAuthorSidecarCardEntries === 'function' ? guidedAuthorSidecarCardEntries(sidecar) : [];
    entries.forEach(function(item){
      var uid = guidedWorkbenchNormalizeUid(guidedWorkbenchEntryUid(item));
      if (uid && deckUids[uid]) lookup[uid] = true;
    });
  });
  return lookup;
}

function guidedWorkbenchMissingCards(deck) {
  var matched = guidedWorkbenchMatchedUidLookup(deck);
  return deckReadinessCards(deck).filter(function(card){
    var uid = guidedWorkbenchCardUid(card);
    return !uid || !matched[uid];
  });
}

function guidedWorkbenchCardRowModel(card) {
  return {
    uid: guidedWorkbenchCardUid(card) || 'No ID',
    question: guidedWorkbenchSnippet(card && (card.q || card.question || card.title || card.prompt), 130) || 'Untitled card',
    answer: guidedWorkbenchSnippet(card && (card.a || card.answer || card.back || card.reference), 140) || '',
    tags: Array.isArray(card && card.tags) ? card.tags.slice(0, 4).map(guidedWorkbenchText).filter(Boolean) : []
  };
}

function guidedWorkbenchDeckModel(cat) {
  var status = guidedTrustCategoryStatus(cat);
  var deck = status.deck;
  var cards = deckReadinessCards(deck);
  var missing = deck ? guidedWorkbenchMissingCards(deck) : [];
  var nextBatch = missing.slice(0, GUIDED_WORKBENCH_BATCH_SIZE).map(guidedWorkbenchCardRowModel);
  var percent = status.total ? Math.round((status.matched / status.total) * 100) : 0;
  return {
    category: cat,
    deck: deck,
    status: status,
    total: status.total,
    matched: status.matched,
    missingCount: missing.length,
    percent: percent,
    nextBatch: nextBatch
  };
}

function guidedWorkbenchModels() {
  return guidedGetAvailableCategories().map(guidedWorkbenchDeckModel).sort(function(a, b){
    if (!!b.missingCount !== !!a.missingCount) return b.missingCount - a.missingCount;
    return b.missingCount - a.missingCount || String(a.category && a.category.label || '').localeCompare(String(b.category && b.category.label || ''));
  });
}

function guidedWorkbenchSummary(models) {
  models = models || [];
  return models.reduce(function(out, model){
    out.decks += 1;
    out.ready += model.missingCount ? 0 : 1;
    out.missing += model.missingCount;
    out.nextBatch += model.nextBatch.length;
    return out;
  }, { decks: 0, ready: 0, missing: 0, nextBatch: 0 });
}

function guidedWorkbenchProgressColor(model) {
  if (!model || model.percent >= 85) return '#22c55e';
  if (model.percent > 0) return '#facc15';
  return '#f87171';
}

function guidedWorkbenchRenderCardList(model) {
  if (!model || !model.nextBatch.length) {
    return '<div class="guided-workbench-empty">No missing cards in this deck right now.</div>';
  }
  var visibleCards = model.nextBatch.slice(0, GUIDED_WORKBENCH_VISIBLE_BATCH_LIMIT);
  var moreCount = Math.max(0, model.nextBatch.length - visibleCards.length);
  return '<div class="guided-workbench-batch">'
    + visibleCards.map(function(card){
      return '<div class="guided-workbench-card-row">'
        + '<strong>' + escHtml(card.uid) + '</strong>'
        + '<span>' + escHtml(card.question) + '</span>'
        + (card.answer ? '<em>' + escHtml(card.answer) + '</em>' : '')
        + '</div>';
    }).join('')
    + (moreCount ? '<div class="guided-workbench-more">+' + escHtml(moreCount) + ' more included when copied</div>' : '')
    + '</div>';
}

function guidedWorkbenchRender() {
  var statusEl = document.getElementById('profile-guided-workbench-status');
  var summaryEl = document.getElementById('profile-guided-workbench-summary');
  var listEl = document.getElementById('profile-guided-workbench-list');
  if (!statusEl && !summaryEl && !listEl) return;
  var models = guidedWorkbenchModels();
  var summary = guidedWorkbenchSummary(models);
  if (statusEl) {
    statusEl.textContent = summary.missing
      ? summary.missing + ' cards still need rich Guided lessons.'
      : 'All available Guided decks look covered.';
  }
  if (summaryEl) {
    summaryEl.innerHTML = '<span><em>Decks</em><strong>' + escHtml(summary.decks) + '</strong></span>'
      + '<span><em>Ready</em><strong>' + escHtml(summary.ready + '/' + summary.decks) + '</strong></span>'
      + '<span><em>Missing</em><strong>' + escHtml(summary.missing + ' cards') + '</strong></span>'
      + '<span><em>Next batch</em><strong>' + escHtml(summary.nextBatch + ' cards') + '</strong></span>';
  }
  if (!listEl) return;
  if (!models.length) {
    listEl.innerHTML = '<div class="guided-workbench-empty">No Guided decks are available yet. Load a deck first, then this area will show what to improve next.</div>';
    guidedWorkbenchRenderReturnResult();
    return;
  }
  listEl.innerHTML = models.map(function(model){
    var cat = model.category || {};
    var tone = model.missingCount ? (model.matched ? 'warning' : 'missing') : 'ready';
    var batchLabel = model.nextBatch.length ? ('Copy next ' + model.nextBatch.length) : 'Covered';
    var batchAria = model.nextBatch.length ? ('Copy next ' + model.nextBatch.length + ' ' + (cat.label || 'Guided') + ' cards') : ((cat.label || 'Guided') + ' covered');
    return '<div class="guided-workbench-row is-' + escHtml(tone) + '">'
      + '<div class="guided-workbench-row-head">'
      + '<div><strong>' + escHtml(cat.label || (model.deck && model.deck.name) || 'Guided deck') + '</strong>'
      + '<span>' + escHtml(model.matched + '/' + model.total + ' rich · ' + model.missingCount + ' still need lessons') + '</span></div>'
      + '<button type="button" class="profile-inline-btn" aria-label="' + escHtml(batchAria) + '" ' + (model.nextBatch.length ? 'onclick="guidedWorkbenchCopyBatch(\'' + escHtml(cat.id || '') + '\')"' : 'disabled') + '>' + escHtml(batchLabel) + '</button>'
      + '</div>'
      + '<div class="guided-workbench-meter" aria-hidden="true"><span style="width:' + escHtml(model.percent) + '%;background:' + escHtml(guidedWorkbenchProgressColor(model)) + '"></span></div>'
      + guidedWorkbenchRenderCardList(model)
      + '<div class="guided-workbench-actions">'
      + '<button type="button" class="btn btn-soft" onclick="contentBuilderOpenGuidedContent()">Open Guided files</button>'
      + '<button type="button" class="btn btn-soft" onclick="contentBuilderCheckQuality()">View full readiness</button>'
      + '</div>'
      + '</div>';
  }).join('');
  guidedWorkbenchRenderReturnResult();
}

function guidedWorkbenchBatchPayload(categoryId) {
  var model = guidedWorkbenchModels().filter(function(item){
    return String(item.category && item.category.id || '') === String(categoryId || '');
  })[0];
  if (!model || !model.nextBatch.length) return '';
  return JSON.stringify({
    deckName: model.deck && model.deck.name || model.category && model.category.label || '',
    category: model.category && model.category.label || '',
    batchSize: model.nextBatch.length,
    goal: 'Create rich Guided Learning content for these cards. Keep each cardUid exactly as shown.',
    suggestedFields: [
      'helperCue',
      'rememberThis',
      'whyThisMatters',
      'teachingPrompt',
      'commonMistake',
      'briefingScreens',
      'questions'
    ],
    cards: model.nextBatch.map(function(card){
      return {
        cardUid: card.uid,
        question: card.question,
        answer: card.answer,
        tags: card.tags
      };
    })
  }, null, 2);
}

function guidedWorkbenchCopyBatch(categoryId) {
  var text = guidedWorkbenchBatchPayload(categoryId);
  if (!text) {
    if (typeof showXpToast === 'function') showXpToast('No missing cards in that batch.');
    return;
  }
  var title = 'Guided content batch';
  var body = '<strong>Next Guided batch</strong><br>Use this card list when writing the next rich Guided lessons.';
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(function(){
      if (typeof showXpToast === 'function') showXpToast('Guided batch copied.');
    }).catch(function(){
      openExportTextModal(title, body, text, 'guided-content-next-batch.json', { description: 'Guided content batch', bridgeFolder: 'sidecars' });
    });
  } else {
    openExportTextModal(title, body, text, 'guided-content-next-batch.json', { description: 'Guided content batch', bridgeFolder: 'sidecars' });
  }
}

function guidedWorkbenchClone(value) {
  if (typeof guidedSidecarClone === 'function') return guidedSidecarClone(value);
  try { return JSON.parse(JSON.stringify(value)); } catch(e) { return value; }
}

function guidedWorkbenchNormalizeName(value) {
  if (typeof guidedNormalizeName === 'function') return guidedNormalizeName(value || '');
  return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function guidedWorkbenchFindDeckByName(value) {
  var wanted = guidedWorkbenchNormalizeName(value);
  if (!wanted || !Array.isArray(decks)) return null;
  return decks.find(function(deck){
    var deckName = guidedWorkbenchNormalizeName(deck && deck.name);
    return deckName && (deckName === wanted || deckName.indexOf(wanted) !== -1 || wanted.indexOf(deckName) !== -1);
  }) || null;
}

function guidedWorkbenchFindCategoryByValue(value) {
  var wanted = guidedWorkbenchNormalizeName(value);
  if (!wanted) return null;
  return guidedGetAvailableCategories().find(function(cat){
    return guidedWorkbenchNormalizeName(cat.id) === wanted
      || guidedWorkbenchNormalizeName(cat.label) === wanted
      || guidedWorkbenchNormalizeName(cat.deckName) === wanted;
  }) || null;
}

function guidedWorkbenchFindCategoryForDeck(deck) {
  if (!deck) return null;
  return guidedGetAvailableCategories().find(function(cat){
    return String(cat.deckId) === String(deck.id);
  }) || null;
}

function guidedWorkbenchCardListFromReturnedJson(parsed) {
  var cards = parsed && parsed.cards;
  if (!cards && parsed && parsed.sidecar) cards = parsed.sidecar.cards;
  if (!cards && parsed && parsed.batch) cards = parsed.batch.cards;
  if (!cards) return [];
  if (Array.isArray(cards)) return cards.map(function(card){ return card || {}; });
  if (typeof cards === 'object') {
    return Object.keys(cards).map(function(key){
      var copy = guidedWorkbenchClone(cards[key] || {}) || {};
      if (copy.cardUid == null && copy.uid == null && copy.guidedUid == null) copy.cardUid = key;
      copy.__returnKey = key;
      return copy;
    });
  }
  return [];
}

function guidedWorkbenchInferDeckFromUids(rawCards) {
  var uidLookup = {};
  (rawCards || []).forEach(function(card){
    var uid = guidedWorkbenchNormalizeUid(card && (card.cardUid || card.uid || card.guidedUid || card.id || card.__returnKey));
    if (uid) uidLookup[uid] = true;
  });
  var best = null;
  (decks || []).forEach(function(deck){
    var score = 0;
    deckReadinessCards(deck).forEach(function(card){
      var uid = guidedWorkbenchCardUid(card);
      if (uid && uidLookup[uid]) score += 1;
    });
    if (!best || score > best.score) best = { deck: deck, score: score };
  });
  return best && best.score ? best.deck : null;
}

function guidedWorkbenchReturnedContext(parsed, rawCards) {
  parsed = parsed || {};
  var sidecar = parsed.sidecar || parsed;
  var category = [
    parsed.categoryId,
    parsed.deckCategory,
    parsed.category,
    sidecar.categoryId,
    sidecar.deckCategory,
    sidecar.category,
    parsed.deckName,
    sidecar.deckName,
    sidecar.sourceDeckName
  ].map(guidedWorkbenchFindCategoryByValue).filter(Boolean)[0] || null;
  var deck = category ? guidedGetDeckById(category.deckId) : null;
  deck = deck || guidedWorkbenchFindDeckByName(parsed.deckName || sidecar.deckName || sidecar.sourceDeckName || sidecar.targetDeck || sidecar.deck);
  deck = deck || guidedWorkbenchInferDeckFromUids(rawCards);
  category = category || guidedWorkbenchFindCategoryForDeck(deck);
  return { deck: deck || null, category: category || null };
}

function guidedWorkbenchReturnedGuidedPayload(raw) {
  var payload = {};
  raw = raw || {};
  if (raw.guidedLearning && typeof raw.guidedLearning === 'object') payload = typeof guidedSidecarMergeObject === 'function' ? guidedSidecarMergeObject(payload, raw.guidedLearning) : Object.assign(payload, guidedWorkbenchClone(raw.guidedLearning));
  if (raw.guided && typeof raw.guided === 'object') payload = typeof guidedSidecarMergeObject === 'function' ? guidedSidecarMergeObject(payload, raw.guided) : Object.assign(payload, guidedWorkbenchClone(raw.guided));
  GUIDED_WORKBENCH_RETURN_TEXT_FIELDS.concat(GUIDED_WORKBENCH_RETURN_ARRAY_FIELDS, GUIDED_WORKBENCH_RETURN_OBJECT_FIELDS).forEach(function(key){
    if (raw[key] !== undefined) payload[key] = guidedWorkbenchClone(raw[key]);
  });
  if (payload.questionBank && !payload.questions) payload.questions = guidedWorkbenchClone(payload.questionBank);
  return payload;
}

function guidedWorkbenchValueHasContent(value) {
  if (value == null) return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === 'object') return Object.keys(value).length > 0;
  return !!guidedWorkbenchText(value);
}

function guidedWorkbenchReturnedEntryHasContent(entry) {
  var gl = entry && entry.guidedLearning || {};
  return GUIDED_WORKBENCH_RETURN_TEXT_FIELDS.concat(GUIDED_WORKBENCH_RETURN_ARRAY_FIELDS, GUIDED_WORKBENCH_RETURN_OBJECT_FIELDS).some(function(key){
    return guidedWorkbenchValueHasContent(gl[key]) || guidedWorkbenchValueHasContent(entry && entry[key]);
  });
}

function guidedWorkbenchBuildReturnedSidecar(parsed) {
  var rawCards = guidedWorkbenchCardListFromReturnedJson(parsed);
  var context = guidedWorkbenchReturnedContext(parsed || {}, rawCards);
  var deck = context.deck;
  var category = context.category;
  var source = parsed && (parsed.sidecar || parsed) || {};
  var now = new Date().toISOString();
  var label = category && category.label || deck && deck.name || source.deckName || parsed && parsed.category || 'Guided';
  var sidecar = {
    schemaVersion: source.schemaVersion || 1,
    sidecarType: 'guidedLearningOverlay',
    title: 'Guided Workbench Returned Batch - ' + label + ' - ' + now.replace(/[:.]/g, '-'),
    deckName: deck && deck.name || source.deckName || parsed && parsed.deckName || '',
    sourceDeckName: deck && deck.name || source.sourceDeckName || source.deckName || parsed && parsed.deckName || '',
    deckCategory: category && category.id || source.deckCategory || source.categoryId || parsed && (parsed.deckCategory || parsed.categoryId) || '',
    description: 'Returned through the StudyDeck Guided Content Workbench.',
    sourceTranslation: source.sourceTranslation || source.translation || '',
    createdForDeckUidPolicy: source.createdForDeckUidPolicy || 'cardUid',
    guidedLearning: {
      source: 'StudyDeck Guided Content Workbench',
      returnedAt: now
    },
    cards: {}
  };
  rawCards.forEach(function(raw, idx){
    raw = raw || {};
    var rawUid = raw.cardUid || raw.uid || raw.guidedUid || raw.id || raw.__returnKey || '';
    var uid = guidedWorkbenchNormalizeUid(rawUid);
    var card = deck && uid ? deckReadinessCards(deck).find(function(item){
      return guidedWorkbenchCardUid(item) === uid;
    }) : null;
    var payload = guidedWorkbenchReturnedGuidedPayload(raw);
    var entry = {
      cardUid: uid || String(rawUid || ''),
      stage: raw.stage || raw.level || card && card.level || 1,
      titleHint: raw.titleHint || raw.question || raw.prompt || card && card.q || '',
      deckAnswer: raw.deckAnswer || raw.answer || raw.reference || card && card.a || '',
      sourceTags: Array.isArray(raw.sourceTags) ? raw.sourceTags : (Array.isArray(raw.tags) ? raw.tags : (card && Array.isArray(card.tags) ? card.tags : [])),
      guidedLearning: payload
    };
    if (raw.sourceReference || raw.reference || card && card.a) entry.sourceReference = raw.sourceReference || raw.reference || card && card.a || '';
    var key = uid || ('returned-' + (idx + 1));
    sidecar.cards[key] = entry;
  });
  return { sidecar: sidecar, deck: deck, category: category, rawCards: rawCards };
}

function guidedWorkbenchReturnedIssue(kind, text) {
  return { kind: kind || 'warning', text: text || '' };
}

function guidedWorkbenchAnalyzeReturnedBatch(text) {
  text = guidedWorkbenchText(text);
  if (!text) {
    return {
      tone: 'missing',
      title: 'Paste a returned batch first',
      body: 'Nothing has been checked yet.',
      chips: [],
      issues: [guidedWorkbenchReturnedIssue('error', 'Paste completed Guided JSON before checking.')],
      canSave: false
    };
  }
  var parsed = null;
  try {
    parsed = JSON.parse(text);
  } catch(err) {
    return {
      tone: 'missing',
      title: 'JSON needs fixing',
      body: 'The pasted text is not valid JSON yet.',
      chips: [],
      issues: [guidedWorkbenchReturnedIssue('error', err && err.message ? err.message : 'Unable to parse JSON.')],
      canSave: false
    };
  }
  var built = guidedWorkbenchBuildReturnedSidecar(parsed);
  var sidecar = built.sidecar;
  var entries = typeof guidedAuthorSidecarCardEntries === 'function' ? guidedAuthorSidecarCardEntries(sidecar) : [];
  var report = typeof guidedAuthorValidateSidecarObject === 'function'
    ? guidedAuthorValidateSidecarObject(sidecar, 'Guided Workbench returned batch')
    : { matchedDeck: built.deck, totals: { sidecarCards: entries.length, matchedCards: 0, missingCards: entries.length, errors: 1, warnings: 0 }, issues: [] };
  var totals = report.totals || {};
  var seen = {};
  var duplicateUids = [];
  var missingUidCount = 0;
  var emptyContentCount = 0;
  entries.forEach(function(item){
    var uid = guidedWorkbenchNormalizeUid(guidedWorkbenchEntryUid(item));
    if (!uid) missingUidCount += 1;
    else if (seen[uid]) duplicateUids.push(uid);
    else seen[uid] = true;
    if (!guidedWorkbenchReturnedEntryHasContent(item && item.entry || {})) emptyContentCount += 1;
  });
  var alreadyCovered = 0;
  if (built.deck) {
    var activeLookup = guidedWorkbenchMatchedUidLookup(built.deck);
    Object.keys(seen).forEach(function(uid){
      if (activeLookup[uid]) alreadyCovered += 1;
    });
  }
  var issues = [];
  if (!entries.length) issues.push(guidedWorkbenchReturnedIssue('error', 'No returned cards were found in the JSON.'));
  if (!report.matchedDeck) issues.push(guidedWorkbenchReturnedIssue('error', 'No deck could be matched for this returned batch.'));
  if (missingUidCount) issues.push(guidedWorkbenchReturnedIssue('error', missingUidCount + ' returned card' + (missingUidCount === 1 ? ' is' : 's are') + ' missing a card ID.'));
  if (duplicateUids.length) issues.push(guidedWorkbenchReturnedIssue('error', duplicateUids.length + ' duplicate card ID' + (duplicateUids.length === 1 ? '' : 's') + ' found in the returned batch.'));
  if (Number(totals.missingCards || 0)) issues.push(guidedWorkbenchReturnedIssue('error', totals.missingCards + ' card ID' + (totals.missingCards === 1 ? ' does' : 's do') + ' not match the deck.'));
  if (emptyContentCount) issues.push(guidedWorkbenchReturnedIssue('error', emptyContentCount + ' returned card' + (emptyContentCount === 1 ? ' has' : 's have') + ' no rich Guided content yet.'));
  if (alreadyCovered) issues.push(guidedWorkbenchReturnedIssue('error', alreadyCovered + ' returned card' + (alreadyCovered === 1 ? ' is' : 's are') + ' already covered by active Guided content.'));
  if (Number(totals.errors || 0)) issues.push(guidedWorkbenchReturnedIssue('error', totals.errors + ' Guided validation error' + (totals.errors === 1 ? '' : 's') + ' found.'));
  if (Number(totals.warnings || 0)) issues.push(guidedWorkbenchReturnedIssue('warning', totals.warnings + ' Guided validation warning' + (totals.warnings === 1 ? '' : 's') + ' found.'));
  var errorCount = issues.filter(function(issue){ return issue.kind === 'error'; }).length;
  var canSave = !errorCount;
  return {
    tone: canSave ? (issues.length ? 'warning' : 'ready') : 'missing',
    title: canSave ? 'Ready to save' : 'Needs fixes before saving',
    body: canSave
      ? (entries.length + ' returned card' + (entries.length === 1 ? '' : 's') + ' checked; all card IDs match.')
      : 'Fix the items below, then check the returned batch again.',
    chips: [
      entries.length + ' card' + (entries.length === 1 ? '' : 's') + ' found',
      (totals.matchedCards || 0) + ' ID match' + ((totals.matchedCards || 0) === 1 ? '' : 'es'),
      (entries.length - alreadyCovered) + ' new',
      (totals.warnings || 0) + ' warning' + ((totals.warnings || 0) === 1 ? '' : 's')
    ],
    issues: issues,
    canSave: canSave,
    sidecar: sidecar,
    report: report,
    deck: built.deck,
    category: built.category
  };
}

function guidedWorkbenchReturnInputChanged() {
  var input = document.getElementById('profile-guided-return-input');
  var text = input ? input.value : '';
  if (guidedWorkbenchReturnLastText && text !== guidedWorkbenchReturnLastText) {
    guidedWorkbenchReturnCheck = {
      tone: 'warning',
      title: 'Batch changed',
      body: 'Check the returned batch again before saving.',
      chips: [],
      issues: [],
      canSave: false
    };
    guidedWorkbenchRenderReturnResult();
  }
}

function guidedWorkbenchCheckReturnedBatch() {
  var input = document.getElementById('profile-guided-return-input');
  var text = input ? input.value : '';
  guidedWorkbenchReturnLastText = text;
  guidedWorkbenchReturnCheck = guidedWorkbenchAnalyzeReturnedBatch(text);
  guidedWorkbenchRenderReturnResult();
}

function guidedWorkbenchRenderReturnResult() {
  var el = document.getElementById('profile-guided-return-result');
  var saveBtn = document.getElementById('profile-guided-return-save-btn');
  var check = guidedWorkbenchReturnCheck;
  if (saveBtn) saveBtn.disabled = !(check && check.canSave);
  if (!el) return;
  if (!check) {
    el.className = 'guided-workbench-return-result';
    el.textContent = 'No returned batch checked yet.';
    return;
  }
  el.className = 'guided-workbench-return-result is-' + escHtml(check.tone || 'warning');
  el.innerHTML = '<strong>' + escHtml(check.title || 'Returned batch check') + '</strong>'
    + '<span>' + escHtml(check.body || '') + '</span>'
    + ((check.chips || []).length ? '<div class="guided-workbench-return-chips">' + check.chips.map(function(chip){
        return '<em>' + escHtml(chip) + '</em>';
      }).join('') + '</div>' : '')
    + ((check.issues || []).length ? '<div class="guided-workbench-return-issues">' + check.issues.slice(0, 6).map(function(issue){
        return '<p class="is-' + escHtml(issue.kind || 'warning') + '">' + escHtml(issue.text) + '</p>';
      }).join('') + '</div>' : '');
}

function guidedWorkbenchSaveReturnedBatch() {
  var input = document.getElementById('profile-guided-return-input');
  var text = input ? input.value : '';
  if (!guidedWorkbenchReturnCheck || text !== guidedWorkbenchReturnLastText) {
    guidedWorkbenchReturnLastText = text;
    guidedWorkbenchReturnCheck = guidedWorkbenchAnalyzeReturnedBatch(text);
    guidedWorkbenchRenderReturnResult();
    if (!guidedWorkbenchReturnCheck.canSave) return;
  }
  if (!guidedWorkbenchReturnCheck.canSave) {
    guidedWorkbenchRenderReturnResult();
    return;
  }
  if (typeof guidedAuthorCommitActiveSidecar !== 'function') {
    guidedWorkbenchReturnCheck = {
      tone: 'missing',
      title: 'Save path unavailable',
      body: 'Guided content storage is not ready in this browser.',
      chips: [],
      issues: [guidedWorkbenchReturnedIssue('error', 'Reload the app and try again.')],
      canSave: false
    };
    guidedWorkbenchRenderReturnResult();
    return;
  }
  if (typeof writeCriticalProgressBackup === 'function') {
    writeCriticalProgressBackup('before_guided_workbench_return_save', { includeDecks: false, includeSidecars: true });
  }
  var idBase = [
    'guided-workbench-return',
    guidedWorkbenchReturnCheck.category && guidedWorkbenchReturnCheck.category.id,
    guidedWorkbenchReturnCheck.deck && guidedWorkbenchReturnCheck.deck.id,
    Date.now()
  ].filter(Boolean).join(' ');
  var id = typeof guidedSidecarCleanKey === 'function'
    ? guidedSidecarCleanKey(idBase)
    : idBase.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  var prepared = guidedAuthorCommitActiveSidecar(guidedWorkbenchClone(guidedWorkbenchReturnCheck.sidecar), guidedWorkbenchReturnCheck.report, id);
  var savedTitle = prepared && prepared.sidecar && prepared.sidecar.title || 'Returned Guided batch';
  guidedWorkbenchReturnCheck = {
    tone: 'ready',
    title: 'Returned batch saved',
    body: savedTitle + ' is now active Guided content in this browser.',
    chips: [],
    issues: [],
    canSave: false
  };
  guidedWorkbenchReturnLastText = '';
  if (input) input.value = '';
  guidedWorkbenchRender();
  contentBuilderRefreshStatus();
  backupCenterRenderDeckReadiness();
  guidedWorkbenchRenderReturnResult();
  if (typeof showXpToast === 'function') showXpToast('Returned Guided batch saved.');
}

function contentBuilderGuidedCount() {
  return deckReadinessStoredGuidedSidecars().length;
}

function contentBuilderStats() {
  var reports = Array.isArray(decks) ? decks.map(deckReadinessBuild) : [];
  return {
    decks: Array.isArray(decks) ? decks.length : 0,
    cards: Array.isArray(decks) ? decks.reduce(function(total, deck){
      return total + deckReadinessCards(deck).length;
    }, 0) : 0,
    ready: reports.filter(function(report){ return report.score >= 85; }).length,
    close: reports.filter(function(report){ return report.score >= 70 && report.score < 85; }).length,
    needsWork: reports.filter(function(report){ return report.score < 70; }).length,
    guided: contentBuilderGuidedCount()
  };
}

function contentBuilderRefreshStatus() {
  var statusEl = document.getElementById('profile-builder-status');
  var summaryEl = document.getElementById('profile-builder-summary');
  var authorBtn = document.getElementById('profile-builder-author-btn');
  if (!statusEl && !summaryEl && !authorBtn) return;
  var stats = contentBuilderStats();
  if (statusEl) {
    statusEl.textContent = authorMode
      ? 'Creator tools are unlocked.'
      : 'Unlock Author Mode before changing deck or Guided content.';
  }
  if (authorBtn) authorBtn.textContent = authorMode ? 'Lock' : 'Unlock';
  if (summaryEl) {
    summaryEl.innerHTML = '<span><em>Decks</em><strong>' + escHtml(stats.decks) + '</strong></span>'
      + '<span><em>Cards</em><strong>' + escHtml(stats.cards) + '</strong></span>'
      + '<span><em>Readiness</em><strong>' + escHtml(stats.ready + ' ready / ' + stats.close + ' close / ' + stats.needsWork + ' work') + '</strong></span>'
      + '<span><em>Guided</em><strong>' + escHtml(stats.guided + ' active file' + (stats.guided === 1 ? '' : 's')) + '</strong></span>';
  }
}

