var _studyDeckAudioContext = null;
var _studyDeckLastSoundAt = 0;
function normalizeSoundFeedbackVolume(value) {
  var num = Number(value);
  if (!Number.isFinite(num)) num = 0.35;
  if (num > 1) num = num / 100;
  return Math.max(0, Math.min(1, num));
}
function getSoundFeedbackVolume() {
  gd = normalizeGameData(gd);
  return normalizeSoundFeedbackVolume(gd.soundVolume);
}
function updateAudioFeedbackControls() {
  var enabled = !!(gd && gd.soundFeedback);
  var volume = Math.round(getSoundFeedbackVolume() * 100);
  var toggle = document.getElementById('sound-feedback-toggle');
  var slider = document.getElementById('sound-volume-range');
  var value = document.getElementById('sound-volume-value');
  if (toggle) {
    toggle.textContent = enabled ? 'On' : 'Off';
    toggle.classList.toggle('dc-on', enabled);
    toggle.setAttribute('aria-pressed', enabled ? 'true' : 'false');
    toggle.setAttribute('aria-label', enabled ? 'Turn sound feedback off' : 'Turn sound feedback on');
    toggle.setAttribute('title', enabled ? 'Turn sound feedback off' : 'Turn sound feedback on');
  }
  if (slider && String(slider.value) !== String(volume)) slider.value = String(volume);
  if (value) value.textContent = volume + '%';
  updateProfileSettingsSummary();
}
function getQuizDifficultySummaryLabel() {
  var current = normalizeQuizDifficulty(typeof quizDifficulty !== 'undefined' ? quizDifficulty : 'hard');
  var match = QUIZ_DIFFICULTY_OPTIONS.find(function(opt){ return opt.id === current; });
  var label = match ? match.label : 'Hard / Exact';
  return label.split('/')[0].trim();
}
function updateProfileSettingsSummary() {
  var summaryEl = document.getElementById('profile-settings-summary');
  var styleEl = document.getElementById('profile-setting-style');
  var bibleEl = document.getElementById('profile-setting-bible');
  var quizEl = document.getElementById('profile-setting-quiz');
  var soundEl = document.getElementById('profile-setting-sound');
  var styleLabel = getAppStyleLabel(getCurrentAppStyleId());
  var bibleLabel = normalizeBibleVersion(bibleGatewayVersion);
  var quizLabel = getQuizDifficultySummaryLabel();
  var soundLabel = gd && gd.soundFeedback ? Math.round(getSoundFeedbackVolume() * 100) + '%' : 'Off';
  if (styleEl) styleEl.textContent = styleLabel;
  if (bibleEl) bibleEl.textContent = bibleLabel;
  if (quizEl) quizEl.textContent = quizLabel;
  if (soundEl) soundEl.textContent = soundLabel;
  if (summaryEl) {
    summaryEl.setAttribute(
      'aria-label',
      'Open app settings. Current settings: Style ' + styleLabel + ', Bible version ' + bibleLabel + ', Quiz difficulty ' + quizLabel + ', Sound feedback ' + soundLabel + '.'
    );
  }
}
function setSoundFeedback(enabled) {
  gd.soundFeedback = !!enabled;
  gd.soundVolume = getSoundFeedbackVolume();
  saveGameData();
  updateAudioFeedbackControls();
  if (gd.soundFeedback) studyDeckPlayUiSound('test', { force: true });
}
function toggleSoundFeedback() {
  setSoundFeedback(!(gd && gd.soundFeedback));
}
function setSoundFeedbackVolume(value) {
  gd.soundVolume = normalizeSoundFeedbackVolume(value);
  saveGameData();
  updateAudioFeedbackControls();
}
function getStudyDeckAudioContext() {
  var AudioCtor = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtor) return null;
  if (!_studyDeckAudioContext) _studyDeckAudioContext = new AudioCtor();
  return _studyDeckAudioContext;
}
function studyDeckPlayUiSound(kind, options) {
  options = options || {};
  if (!options.force && !(gd && gd.soundFeedback)) return false;
  var nowMs = Date.now();
  if (!options.force && nowMs - _studyDeckLastSoundAt < 120) return false;
  _studyDeckLastSoundAt = nowMs;
  var ctx = getStudyDeckAudioContext();
  if (!ctx) {
    if (options.force && typeof showXpToast === 'function') showXpToast('Sound is not available in this browser.', 1600);
    return false;
  }
  var volume = normalizeSoundFeedbackVolume(options.volume !== undefined ? options.volume : getSoundFeedbackVolume());
  if (volume <= 0) return false;
  try {
    if (ctx.state === 'suspended' && ctx.resume) ctx.resume();
    var now = ctx.currentTime;
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    var isBad = kind === 'bad' || kind === 'miss';
    var isTest = kind === 'test';
    var startFreq = isBad ? 220 : isTest ? 440 : 523.25;
    var endFreq = isBad ? 174.61 : isTest ? 659.25 : 659.25;
    var duration = isBad ? 0.16 : 0.18;
    osc.type = isBad ? 'triangle' : 'sine';
    osc.frequency.setValueAtTime(startFreq, now);
    osc.frequency.exponentialRampToValueAtTime(endFreq, now + duration * 0.62);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volume * 0.11), now + 0.018);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + duration + 0.02);
    return true;
  } catch(e) {
    return false;
  }
}
function testSoundFeedback() {
  studyDeckPlayUiSound('test', { force: true });
}

