function cardLevelNumber(card) {
  var level = Number(card && card.level);
  if (!Number.isFinite(level) || level < 1) return 1;
  return Math.round(level);
}
function cardLevelBadgeHTML(card) {
  var level = String(cardLevelNumber(card));
  return '<span class="mini-tag card-level-tag" aria-label="Card level '+escHtml(level)+'" title="Card level '+escHtml(level)+'">Lvl. '+escHtml(level)+'</span>';
}
function cardTagBadgesHTML(card) {
  var tags = Array.isArray(card && card.tags) ? card.tags : [];
  return cardLevelBadgeHTML(card) + tags.map(function(t){ return '<span class="mini-tag">'+escHtml(t)+'</span>'; }).join('');
}

// ── DETAIL ──
function renderDetail() {
  if (!activeDeck) return;
  var d = activeDeck, filtered = getFiltered(), tags = allTags(d);
  var deckColor = styleLabNormalizeHex(d.color, '#4FCFFF');
  applyStyleLabReferenceToElement(document.getElementById('detail'), deckColor);
  applyStyleLabReferenceToElement(document.getElementById('detail-hero'), deckColor);
  var favCount  = d.cards.filter(function(c){ return favorites.has(d.id+':'+c.id); }).length;
  var moreCount = d.cards.filter(function(c){ return studyMore.has(d.id+':'+c.id); }).length;

  var unlockedLevel = activeDeck._isAll ? 9 : getDeckUnlockedLevel(d.id);
  var unlockedCount = activeDeck._isAll ? d.cards.length
    : d.cards.filter(function(c){ return (c.level||1) <= unlockedLevel; }).length;

  // Build unlock progress HTML (non-author, non-all-decks only)
  var unlockProgressHTML = '';
  if (!authorMode && !activeDeck._isAll) {
    var prog = getDeckUnlockProgress(d);
    if (prog && prog.nextCards > 0) {
      var reqRows = prog.reqs.map(function(r){
        var pct = Math.round(r.met / r.total * 100);
        var barColor = r.done ? '#10B981' : 'var(--gold)';
        return '<div style="margin-bottom:6px">'
          +'<div style="display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-bottom:3px">'
            +'<span>Level '+r.cardLevel+' cards — '+r.threshold+'× correct each</span>'
            +'<span>'+r.met+' / '+r.total+'</span>'
          +'</div>'
          +'<div style="height:4px;background:rgba(255,255,255,0.07);border-radius:2px;overflow:hidden">'
            +'<div style="height:100%;width:'+pct+'%;background:'+barColor+';border-radius:2px;transition:width .4s"></div>'
          +'</div>'
        +'</div>';
      }).join('');
      unlockProgressHTML = '<div style="padding:12px 16px;background:rgba(245,158,11,0.06);border:1px solid rgba(245,158,11,0.2);border-radius:10px;margin-top:12px">'
        +'<div style="font-size:12px;font-weight:600;color:var(--gold);margin-bottom:8px">To unlock Level '+prog.nextLevel+' ('+prog.nextCards+' cards):</div>'
        +reqRows
        +'</div>';
    } else if (prog && prog.nextCards === 0) {
      unlockProgressHTML = '<div style="font-size:12px;color:var(--muted);margin-top:8px;font-style:italic">No Level '+(unlockedLevel+1)+' cards in this deck.</div>';
    } else if (!prog) {
      unlockProgressHTML = '<div style="font-size:12px;color:var(--gold);margin-top:8px">🏆 All levels unlocked!</div>';
    }
  }

  var heroIcon = getDeckIconSVG(d.name);
  document.getElementById('detail-hero').innerHTML =
    '<div style="position:absolute;top:0;right:0;width:90px;height:90px;border-radius:0 var(--r) 0 90px;background:'+deckColor+';opacity:.13;pointer-events:none"></div>'
    +(heroIcon ? '<div class="deck-topic-icon header-icon" style="color:'+deckColor+'">'+heroIcon+'</div>' : '')
    +'<div class="deck-hero-title" style="color:'+deckColor+'">'+d.name+'</div>'
    +'<div class="deck-hero-desc">'+d.desc+'</div>'
    +'<div class="stats-row">'
      +'<div class="stat"><strong>'+d.cards.length+'</strong><span>Total</span></div>'
      +'<div class="stat"><strong>'+filtered.length+'</strong><span>Shown</span></div>'
      +(!authorMode && !activeDeck._isAll
        ? '<div class="stat"><strong>Lv '+unlockedLevel+'</strong><span>Unlocked</span></div>'
        : '<div class="stat"><strong>'+tags.length+'</strong><span>Tags</span></div>')
    +'</div>'
    +unlockProgressHTML;

  document.getElementById('btn-flash').disabled = filtered.length === 0;
  document.getElementById('btn-quiz').disabled  = filtered.length < 4;
  var orderWrap = document.getElementById('btn-order-quiz-wrap');
  if (orderWrap) {
    var isBooks = !activeDeck._isAll && d.name && d.name.toLowerCase().indexOf('book') !== -1;
    orderWrap.style.display = isBooks ? 'flex' : 'none';
  }
  // hide options gear on the virtual All Decks view
  var optsBtn = document.getElementById('opts-btn');
  if (optsBtn) optsBtn.style.display = activeDeck._isAll ? 'none' : '';
  var editBtn = document.getElementById('detail-edit-btn');
  if (editBtn) {
    var canEditDeck = authorMode && !activeDeck._isAll && activeDeck.id !== '__daily__' && decks.some(function(x){ return x.id === activeDeck.id; });
    editBtn.style.display = canEditDeck ? '' : 'none';
  }

  // Filter strip
  var deckTagSet = {};
  tags.forEach(function(t){ deckTagSet[t]=1; });
  // Only show groups that have at least one tag present in this deck
  var relevantGroups = tagGroups.filter(function(g){
    return g.tags.some(function(t){ return deckTagSet[t]; });
  });
  var ungroupedTags = tags.filter(function(t){
    return !relevantGroups.some(function(g){ return g.tags.includes(t); });
  });
  var tagControlCount = 2 + relevantGroups.length + ungroupedTags.length;
  var shouldCollapseTags = tagControlCount > 10;
  var tagPillsHTML = ''
    +'<button class="filter-pill fav-pill'+(filterFav?' on':'')+'" onclick="toggleFilterFav()">★ Favorites'+(favCount?' ('+favCount+')':'')+'</button>'
    +'<button class="filter-pill more-pill'+(filterMore?' on':'')+'" onclick="toggleFilterMore()">✕ I don’t know'+(moreCount?' ('+moreCount+')':'')+'</button>'
    +relevantGroups.map(function(g){
      var hasActive = g.tags.some(function(t){ return filterTags.includes(t) || filterExcludeTags.includes(t); });
      return '<button class="filter-pill tg-pill'+(hasActive?' has-active':'')+'" onclick="openTgOverlay('+g.id+')">'
        +escHtml(g.name)+'<span class="tg-chevron">▾</span></button>';
    }).join('')
    +ungroupedTags.map(function(t){
      var isOn = filterTags.includes(t);
      var isExcluded = filterExcludeTags.includes(t);
      return '<button class="filter-pill tag-pill'+(isOn?' on':'')+(isExcluded?' excluded':'')+'" '
        +'data-tag-pill="1" '
        +'data-tag="'+escHtml(t)+'" '
        +'data-tag-context="detail" '
        +'title="Tap to include. Press and hold to exclude.">'+escHtml(t)+'</button>';
    }).join('');
  var detailFilterSummary = [];
  if (filterSearch.trim()) detailFilterSummary.push({ label: 'Search', value: filterSearch.trim(), type: 'search' });
  if (filterLevel.trim()) detailFilterSummary.push({ label: 'Level', value: filterLevel.trim(), type: 'level' });
  if (filterFav) detailFilterSummary.push({ label: 'Review', value: 'Favorites only', type: 'review' });
  if (filterMore) detailFilterSummary.push({ label: 'Review', value: 'I don’t know only', type: 'review' });
  filterTags.forEach(function(t){ detailFilterSummary.push({ label: 'Include tag', value: t, type: 'include' }); });
  filterExcludeTags.forEach(function(t){ detailFilterSummary.push({ label: 'Hide tag', value: t, type: 'exclude' }); });
  var filterHTML = '<div class="filter-label">Filter</div>'
    +'<div class="filter-tags-shell">'
      +'<div class="filter-row filter-tags-wrap '+(shouldCollapseTags && !filterTagsExpanded ? 'collapsed' : 'expanded')+'">'
        +tagPillsHTML
      +'</div>'
      +(shouldCollapseTags
        ? (filterTagsExpanded
            ? '<div class="filter-tags-hint">Hold a tag for 1 second to hide matching cards.</div>'
            : '')
          +'<button class="filter-pill filter-tags-toggle" onclick="toggleTagExpansion()">'
          +(filterTagsExpanded ? 'Show Less Tags' : 'Show More Tags')
          +'</button>'
        : '')
    +'</div>'
    +'<div style="display:flex;align-items:center;gap:8px;margin-top:8px">'
      +'<span style="font-size:12px;color:var(--muted);flex-shrink:0">Level:</span>'
      +'<input class="form-inp" id="filter-level-inp" value="'+escHtml(filterLevel)+'" placeholder="e.g. 2 or 3-5 or 1,4" style="padding:6px 10px;font-size:12px;flex:1;max-width:200px" oninput="setFilterLevel(this.value)">'
      +(filterLevel.trim() ? '<button class="filter-pill" style="flex-shrink:0;padding:4px 10px;font-size:11px" onclick="setFilterLevel(\'\')">✕</button>' : '')
    +'</div>'
    + renderFilterActiveSummary(detailFilterSummary, 'clearAllDeckFilters()');
  document.getElementById('filter-sec').innerHTML = filterHTML;

  // Sync search bar state (persists across re-renders)
  var searchInp = document.getElementById('deck-search');
  var searchClr = document.getElementById('deck-search-clear');
  if (searchInp && searchInp.value !== filterSearch) searchInp.value = filterSearch;
  if (searchClr) searchClr.style.display = filterSearch.trim() ? '' : 'none';

  // Cards
  var cardsHTML = '<div class="cards-sec-head">'+filtered.length+' card'+(filtered.length!==1?'s':'')+'</div>'
    + (!filtered.length ? renderDeckCardsNoResults() : filtered.map(function(c){
      var deckId = activeDeck._isAll ? (c._deckId||activeDeck.id) : activeDeck.id;
      var m = getMastery(deckId, c.id);
      var score = m.score || 0;
      var tier  = masteryTier(score);
      var mpClass = 'mp' + tier;
      var masteryLabel = score + '/20 · ' + MASTERY_NAMES[tier];
      var masteryPill = authorMode
        ? '<button type="button" class="mastery-pill mastery-pill-editable '+mpClass+'" data-mastery-editor="1" data-deck-id="'+escHtml(deckId)+'" data-card-id="'+escHtml(c.id)+'" title="Set mastery">'+masteryLabel+'</button>'
        : '<span class="mastery-pill '+mpClass+'">'+masteryLabel+'</span>';
      return '<div class="card-row">'
        +'<div class="card-row-tapzone" onclick="openCardInFlash('+c.id+')" title="Open in flashcards">'
          +'<div class="card-row-q">'+renderMD(c.q)+' <span style="color:rgba(255,255,255,0.18);font-size:12px;font-weight:400">›</span></div>'
          +'<div class="card-row-a">'+renderMD(c.a)+'</div>'
        +'</div>'
        +'<div class="card-footer">'
          +'<div class="card-tags">'+cardTagBadgesHTML(c)+'</div>'
          +masteryPill
          +'<button class="icon-btn fav-btn'+(isFav(c)?' on':'')+'" onclick="event.stopPropagation();tapFav('+c.id+')" title="Favorite">★</button>'
          +'<button class="icon-btn more-btn'+(isMore(c)?' on':'')+'" onclick="event.stopPropagation();tapMore('+c.id+')" title="I don’t know">✕</button>'
        +'</div>'
      +'</div>';
    }).join(''));
  document.getElementById('cards-sec').innerHTML = cardsHTML;
}

function updateFaceVisibility() {
  var front = document.getElementById('face-front');
  var back  = document.getElementById('face-back');
  if (!front || !back) return;
  var frontHidden = !!fcFlipped;
  var backHidden = !fcFlipped;
  front.classList.toggle('face-hidden', frontHidden);
  back.classList.toggle('face-hidden', backHidden);
  front.setAttribute('aria-hidden', frontHidden ? 'true' : 'false');
  back.setAttribute('aria-hidden', backHidden ? 'true' : 'false');
  try { front.inert = frontHidden; } catch (err) {}
  try { back.inert = backHidden; } catch (err) {}
  var card = document.getElementById('card-3d');
  if (card) {
    card.setAttribute('aria-label', fcFlipped ? 'Flashcard back. Press Enter to show front.' : 'Flashcard front. Press Enter to show back.');
    card.setAttribute('aria-pressed', fcFlipped ? 'true' : 'false');
  }
  // Reset scroll on the face that just became hidden — but AFTER
  // the flip animation finishes (500ms) so the jump isn't visible
  var faceToReset = fcFlipped ? front : back;
  setTimeout(function() { faceToReset.scrollTop = 0; }, studyDeckMotionDuration(520, 0));
}
function toggleFilterFav()  { filterFav  = !filterFav;  renderDetail(); }
function toggleFilterMore() { filterMore = !filterMore; renderDetail(); }
function setDeckSearch(val) {
  filterSearch = val;
  var inp = document.getElementById('deck-search');
  var clr = document.getElementById('deck-search-clear');
  if (inp) inp.value = val;
  if (clr) clr.style.display = val.trim() ? '' : 'none';
  renderDetail();
}
function clearAllDeckFilters() {
  filterTags = [];
  filterExcludeTags = [];
  filterFav = false;
  filterMore = false;
  filterLevel = '';
  filterSearch = '';
  renderDetail();
}
function renderDeckCardsNoResults() {
  var hasFilters = filterTags.length || filterExcludeTags.length || filterFav || filterMore || filterLevel.trim() || filterSearch.trim();
  var helper = hasFilters
    ? 'Try a different search term, loosen the tags, or clear the filters to show this deck again.'
    : 'This deck does not have cards available for the current view.';
  return '<div class="studydeck-empty">'
    + '<strong>No cards to show.</strong>'
    + '<span>' + escHtml(helper) + '</span>'
    + (hasFilters ? '<div class="studydeck-empty-actions"><button type="button" class="btn btn-soft" onclick="clearAllDeckFilters()">Clear filters</button></div>' : '')
    + '</div>';
}
function setFilterLevel(val) {
  filterLevel = val;
  // Re-render without resetting the input (preserve cursor)
  renderDetail();
  // Restore focus and value on the input after re-render
  var inp = document.getElementById('filter-level-inp');
  if (inp && document.activeElement !== inp) { /* leave focus alone */ }
}
function toggleTagExpansion() {
  filterTagsExpanded = !filterTagsExpanded;
  renderDetail();
}
function toggleTag(t, context) {
  context = context || 'detail';
  if (context === 'edit') {
    editExcludeTags = editExcludeTags.filter(function(x){ return x!==t; });
    editTagFilter = editTagFilter.includes(t) ? editTagFilter.filter(function(x){ return x!==t; }) : editTagFilter.concat([t]);
    renderEditCardsListSafe();
    if (activeTgGroup && _tgContext === 'edit') renderTgGrid();
    return;
  }
  filterExcludeTags = filterExcludeTags.filter(function(x){ return x!==t; });
  filterTags = filterTags.includes(t) ? filterTags.filter(function(x){ return x!==t; }) : filterTags.concat([t]);
  renderDetail();
  if (activeTgGroup && _tgContext === 'detail') renderTgGrid();
}
function toggleTagExclude(t, context) {
  context = context || 'detail';
  if (context === 'edit') {
    editTagFilter = editTagFilter.filter(function(x){ return x!==t; });
    editExcludeTags = editExcludeTags.includes(t)
      ? editExcludeTags.filter(function(x){ return x!==t; })
      : editExcludeTags.concat([t]);
    renderEditCardsListSafe();
    if (activeTgGroup && _tgContext === 'edit') renderTgGrid();
    return;
  }
  filterTags = filterTags.filter(function(x){ return x!==t; });
  filterExcludeTags = filterExcludeTags.includes(t)
    ? filterExcludeTags.filter(function(x){ return x!==t; })
    : filterExcludeTags.concat([t]);
  renderDetail();
  if (activeTgGroup && _tgContext === 'detail') renderTgGrid();
}
function tagPressStart(e, t, context, el) {
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  tagPressCancel();
  tagPressState = {
    tag: t,
    context: context || 'detail',
    x: e.clientX,
    y: e.clientY,
    fired: false,
    el: el || e.currentTarget,
    timer: setTimeout(function(){
      if (!tagPressState || tagPressState.tag !== t) return;
      tagPressState.fired = true;
      if (tagPressState.el) tagPressState.el.classList.add('excluded');
      toggleTagExclude(t, tagPressState.context);
    }, 1000)
  };
}
function tagPressMove(e) {
  if (!tagPressState) return;
  var dx = Math.abs(e.clientX - tagPressState.x);
  var dy = Math.abs(e.clientY - tagPressState.y);
  if (dx > 8 || dy > 8) tagPressCancel();
}
function tagPressCancel() {
  if (!tagPressState) return;
  if (tagPressState.timer) clearTimeout(tagPressState.timer);
  tagPressState = null;
}
function tagPressEnd(e, t) {
  if (!tagPressState || tagPressState.tag !== t) return;
  var fired = tagPressState.fired;
  var context = tagPressState.context || 'detail';
  tagPressCancel();
  if (fired) {
    if (e && e.preventDefault) e.preventDefault();
    if (e && e.stopPropagation) e.stopPropagation();
    return false;
  }
  toggleTag(t, context);
}
document.addEventListener('pointerdown', function(e){
  var el = e.target && e.target.closest ? e.target.closest('[data-tag-pill]') : null;
  if (!el) return;
  tagPressStart(e, el.dataset.tag || '', el.dataset.tagContext || 'detail', el);
});
document.addEventListener('pointermove', function(e){
  if (tagPressState) tagPressMove(e);
});
document.addEventListener('pointerup', function(e){
  if (!tagPressState) return;
  tagPressEnd(e, tagPressState.tag);
});
document.addEventListener('pointercancel', function(){
  tagPressCancel();
});
document.addEventListener('contextmenu', function(e){
  var el = e.target && e.target.closest ? e.target.closest('[data-tag-pill]') : null;
  if (el) e.preventDefault();
});
document.addEventListener('click', function(e){
  var uidCopy = e.target && e.target.closest ? e.target.closest('[data-copy-card-uid]') : null;
  if (uidCopy) {
    var uid = uidCopy.dataset.copyCardUid || '';
    if (navigator.clipboard && uid) navigator.clipboard.writeText(uid).then(function(){ showXpToast('ID copied!'); });
    return;
  }
  var masteryBtn = e.target && e.target.closest ? e.target.closest('[data-mastery-editor]') : null;
  if (masteryBtn) {
    e.stopPropagation();
    openMasteryEditor(masteryBtn.dataset.deckId, masteryBtn.dataset.cardId);
    return;
  }
  var cardLinkBtn = e.target && e.target.closest ? e.target.closest('[data-cardlink-open]') : null;
  if (cardLinkBtn) {
    e.stopPropagation();
    openCardlink(cardLinkBtn.dataset.deckId, cardLinkBtn.dataset.cardId, cardLinkBtn.dataset.cardUid);
  }
});
document.addEventListener('keydown', function(e){
  var uidCopy = e.target && e.target.closest ? e.target.closest('[data-copy-card-uid]') : null;
  if (!uidCopy || (e.key !== 'Enter' && e.key !== ' ')) return;
  e.preventDefault();
  uidCopy.click();
});
function tapFav(cardId) {
  var c = activeDeck.cards.find(function(x){ return x.id===cardId; });
  if (c) { toggleFav(c); renderDetail(); }
}
function tapMore(cardId) {
  var c = activeDeck.cards.find(function(x){ return x.id===cardId; });
  if (c) { toggleMore(c); renderDetail(); }
}

// ── FLASHCARD ──
var _fcAutoAdvanceTimer = null;
function clearFlashcardAutoAdvance() {
  if (_fcAutoAdvanceTimer) clearTimeout(_fcAutoAdvanceTimer);
  _fcAutoAdvanceTimer = null;
}
function getFlashcardMasteryScore(card) {
  var deckId = getFlashcardMasteryDeckId(card);
  return deckId ? clampMasteryScore((getMastery(deckId, card.id).score || 0)) : 0;
}
function learningMixChanceForScore(score) {
  score = clampMasteryScore(score);
  if (score >= 20) return 0.22;
  return Math.max(0.24, 1 - score * 0.04);
}
function buildLearningMix(base) {
  var picked = base.filter(function(c){
    return Math.random() < learningMixChanceForScore(getFlashcardMasteryScore(c));
  });
  if (!picked.length && base.length) {
    var leastKnown = base.slice().sort(function(a,b){
      return getFlashcardMasteryScore(a) - getFlashcardMasteryScore(b);
    })[0];
    picked = [leastKnown];
  }
  return shuffle(picked);
}
function orderFlashcardBase(base, targetCardId) {
  var ordered = deckOrder === 'random'
    ? shuffle(base)
    : deckOrder === 'learning'
      ? buildLearningMix(base)
      : base.slice();
  if (targetCardId !== undefined && targetCardId !== null) {
    var target = base.find(function(c){ return c.id === targetCardId; });
    if (target && !ordered.some(function(c){ return c.id === targetCardId; })) ordered.push(target);
  }
  return ordered;
}
function captureFlashcardSessionBaseline() {
  fcSessionStartMore = new Set();
  fcSessionStartScores = {};
  fcSessionKeys = [];
  fcSessionDeckByKey = {};
  fcSessionCardIdByKey = {};
  var seen = {};
  fcCards.forEach(function(entry){
    var c = entry.card;
    var key = getFlashcardReviewKey(c);
    if (seen[key]) return;
    seen[key] = true;
    fcSessionKeys.push(key);
    if (studyMore.has(key)) fcSessionStartMore.add(key);
    var deckId = getFlashcardMasteryDeckId(c);
    fcSessionDeckByKey[key] = deckId;
    fcSessionCardIdByKey[key] = c.id;
    fcSessionStartScores[key] = deckId ? clampMasteryScore((getMastery(deckId, c.id).score || 0)) : 0;
  });
}
function startFlashcardSession(base, targetCardId) {
  base = Array.isArray(base) ? base : [];
  var ordered = orderFlashcardBase(base, targetCardId);
  fcCards = ordered.map(function(c) {
    var startFlipped = deckFace === 'back' ? true : deckFace === 'mixed' ? Math.random() > 0.5 : false;
    return { card: c, startFlipped: startFlipped };
  });
  if (!fcCards.length) {
    fcIdx = 0;
    fcFlipped = false;
    fcStudied = new Set();
    fcKnownThisPass = new Set();
    clearFlashcardAutoAdvance();
    captureFlashcardSessionBaseline();
    return false;
  }
  fcIdx = targetCardId !== undefined && targetCardId !== null
    ? fcCards.findIndex(function(e){ return e.card.id === targetCardId; })
    : 0;
  if (fcIdx < 0) fcIdx = 0;
  fcFlipped = fcCards[fcIdx].startFlipped;
  fcStudied = new Set();
  fcKnownThisPass = new Set();
  clearFlashcardAutoAdvance();
  captureFlashcardSessionBaseline();
  return true;
}
function getFlashcardSummaryStats() {
  var known = 0, markedDontKnow = 0, clearedDontKnow = 0, masteryGained = 0;
  fcSessionKeys.forEach(function(key){
    if (fcKnownThisPass.has(key)) known++;
    var wasMore = fcSessionStartMore.has(key);
    var isMoreNow = studyMore.has(key);
    if (!wasMore && isMoreNow) markedDontKnow++;
    if (wasMore && !isMoreNow) clearedDontKnow++;
    var deckId = fcSessionDeckByKey[key];
    var cardId = fcSessionCardIdByKey[key];
    if (deckId) {
      var startScore = fcSessionStartScores[key] || 0;
      var nowScore = clampMasteryScore((getMastery(deckId, cardId).score || 0));
      masteryGained += Math.max(0, nowScore - startScore);
    }
  });
  return {
    known: known,
    markedDontKnow: markedDontKnow,
    clearedDontKnow: clearedDontKnow,
    masteryGained: masteryGained,
    changed: known + markedDontKnow + clearedDontKnow > 0
  };
}
function syncFlashcardExitButton() {
  var btn = document.getElementById('fc-exit-btn');
  if (!btn) return;
  var hasSummary = getFlashcardSummaryStats().changed;
  btn.textContent = hasSummary ? '✓' : '←';
  btn.title = hasSummary ? 'Show flashcard summary' : 'Back to deck';
  btn.setAttribute('aria-label', btn.title);
  btn.classList.toggle('summary-ready', hasSummary);
}
function showFlashcardSummary() {
  clearFlashcardAutoAdvance();
  var stats = getFlashcardSummaryStats();
  if (!stats.changed) { showDetail(); return; }
  var totalChanged = stats.known + stats.markedDontKnow + stats.clearedDontKnow;
  document.getElementById('fc-summary-sub').textContent =
    totalChanged + ' card' + (totalChanged === 1 ? '' : 's') + ' changed during this flashcard pass.';
  document.getElementById('fc-summary-grid').innerHTML =
    '<div class="fc-summary-stat known"><strong>'+stats.known+'</strong><span>I know it!</span></div>'
    +'<div class="fc-summary-stat dontknow"><strong>'+stats.markedDontKnow+'</strong><span>Marked I don’t know</span></div>'
    +'<div class="fc-summary-stat cleared"><strong>'+stats.clearedDontKnow+'</strong><span>Cleared from I don’t know</span></div>'
    +'<div class="fc-summary-stat mastery"><strong>'+stats.masteryGained+'</strong><span>Mastery point'+(stats.masteryGained===1?'':'s')+' gained</span></div>';
  document.getElementById('fc-summary-note').textContent =
    stats.masteryGained > 0
      ? 'Mastery reflects the net points gained by cards in this session.'
      : 'No mastery points were gained, but your known/not-known marks were updated.';
  show('flash-summary');
}
function leaveFlashcards() {
  var stats = getFlashcardSummaryStats();
  if (stats.changed) showFlashcardSummary();
  else showDetail();
}
function scheduleFlashcardAutoAdvance() {
  clearFlashcardAutoAdvance();
  if (!fcAutoAdvance) return;
  _fcAutoAdvanceTimer = setTimeout(function(){
    _fcAutoAdvanceTimer = null;
    if (fcIdx < fcCards.length - 1) nextCard();
    else showFlashcardSummary();
  }, 650);
}
function openCardInFlash(cardId) {
  // Build flashcard session from current filtered set
  var base = getFiltered();

  if (!base || !base.length) {
    alert("No cards match your current filters.");
    return;
  }
  if (!startFlashcardSession(base, cardId)) {
    alert("No cards match your current filters.");
    return;
  }
  touchStreak();
  applyStyleLabReferenceToElement(document.getElementById('flashcard'), activeDeck.color);
  document.getElementById('fc-deck-name').textContent = activeDeck.name;
  // Skip flip animation on initial load
  var el = document.getElementById('card-3d');
  el.style.transition = 'none';
  el.classList.toggle('flipped', fcFlipped);
  el.getBoundingClientRect(); // force reflow
  el.style.transition = '';
  renderFC();
  show('flashcard');
}

function startFlash() {
  var base = getFiltered();

  if (!base || !base.length) {
    alert("No cards match your current filters.");
    return;
  }
  if (!startFlashcardSession(base)) {
    alert("No cards match your current filters.");
    return;
  }
  touchStreak();
  applyStyleLabReferenceToElement(document.getElementById('flashcard'), activeDeck.color);
  document.getElementById('fc-deck-name').textContent = activeDeck.name;
  renderFC(); show('flashcard');
}
