  markBundledCustomStyleDeleted(styleId);
  saveStyleLabData();
  saveStyleLabPresetData();
  populateAppStyleSelect('modern_sleek_tech');
  applyAppStyle('modern_sleek_tech');
  if (typeof syncStyleLabPanel === 'function') syncStyleLabPanel();
  if (typeof refreshStyleLabView === 'function') refreshStyleLabView();
