function confirmDeleteCurrentCustomAppStyle() {
  var styleId = getCurrentAppStyleId();
  var style = getCustomAppStyle(styleId);
  if (!style) return;
  closeOptionsMenu();
  appConfirm(
    'Delete custom style?',
    'Delete "' + style.label + '" and all Style Lab settings and presets saved for it? Decks, cards, progress, XP, and streak data will not be affected.',
    'Delete',
    'btn-danger',
    function(ok) {
      if (ok) deleteCustomAppStyle(styleId);
    }
  );
}
function applyAppStyle(styleId) {
  var preset = getAppStylePreset(styleId);
  var resolvedStyleId = preset ? styleId : APP_STYLE_DEFAULT_ID;
  if (!preset) preset = APP_STYLE_PRESETS[APP_STYLE_DEFAULT_ID] || APP_STYLE_PRESETS.modern_sleek_tech;
  Object.keys(preset.vars).forEach(function(k){ document.documentElement.style.setProperty(k, preset.vars[k]); });
  document.documentElement.setAttribute('data-theme', resolvedStyleId || APP_STYLE_DEFAULT_ID);
  var themeMeta = document.querySelector('meta[name="theme-color"]');
  if (themeMeta) themeMeta.setAttribute('content', preset.vars['--bg'] || '#0D1117');
  safeSetLocalStorage(APP_STYLE_KEY, resolvedStyleId, 'app style preference');
  var sel = document.getElementById('app-style-select');
  if (sel && sel.value !== resolvedStyleId) sel.value = resolvedStyleId;
  updateCustomAppStyleControls();
  updateProfileSettingsSummary();
  if (typeof applyStyleLabOverrides === 'function') applyStyleLabOverrides();
  if (typeof updateStyleLabChrome === 'function') updateStyleLabChrome();
}
function populateAppStyleSelect(preferredStyleId) {
  var sel = document.getElementById('app-style-select');
  if (!sel) return;
  var builtInOptions = Object.keys(APP_STYLE_PRESETS).map(function(k){
    return '<option value="'+k+'">'+escapeAppStyleText(APP_STYLE_PRESETS[k].label)+'</option>';
  }).join('');
  var customOptions = customAppStyles.map(function(style){
    return '<option value="'+escapeAppStyleText(style.id)+'">'+escapeAppStyleText(style.label)+'</option>';
  }).join('');
  sel.innerHTML = builtInOptions
    + (customOptions ? '<optgroup label="Custom styles">'+customOptions+'</optgroup>' : '');
  var saved = null;
  try { saved = localStorage.getItem(APP_STYLE_KEY); } catch(e) {}
  saved = preferredStyleId || saved || getCurrentAppStyleId() || APP_STYLE_DEFAULT_ID;
  sel.value = getAppStylePreset(saved) ? saved : APP_STYLE_DEFAULT_ID;
  updateCustomAppStyleControls();
}
function onAppStyleChange(value) {
  if (value === ADD_CUSTOM_APP_STYLE_VALUE) {
    var previous = getCurrentAppStyleId();
    populateAppStyleSelect(previous);
    openBlankAppStyleModal();
    return;
  }
  applyAppStyle(value);
  var menu = document.getElementById('options-menu');
  if (menu && menu.classList.contains('open')) positionOptionsMenu();
}
function normalizeBibleVersion(value) {
  value = String(value || 'NRSVUE').toUpperCase();
  return BIBLE_VERSION_OPTIONS.indexOf(value) >= 0 ? value : 'NRSVUE';
}
function applyBibleVersion(value) {
  bibleGatewayVersion = normalizeBibleVersion(value);
  safeSetLocalStorage(BIBLE_VERSION_KEY, bibleGatewayVersion, 'Bible version preference');
  var sel = document.getElementById('bible-version-select');
  if (sel) sel.value = bibleGatewayVersion;
  updateProfileSettingsSummary();
}
function populateBibleVersionSelect() {
  var sel = document.getElementById('bible-version-select');
  if (!sel) return;
  sel.innerHTML = BIBLE_VERSION_OPTIONS.map(function(version){
    return '<option value="'+version+'">'+version+'</option>';
  }).join('');
  var saved = null;
  try { saved = localStorage.getItem(BIBLE_VERSION_KEY); } catch(e) {}
  applyBibleVersion(saved || 'NRSVUE');
}
function onBibleVersionChange(value) {
  applyBibleVersion(value);
  var menu = document.getElementById('options-menu');
  if (menu && menu.classList.contains('open')) positionOptionsMenu();
}
function normalizeQuizDifficulty(value) {
  value = String(value || 'hard').toLowerCase();
  return QUIZ_DIFFICULTY_OPTIONS.some(function(opt){ return opt.id === value; }) ? value : 'hard';
}
function applyQuizDifficulty(value) {
  quizDifficulty = normalizeQuizDifficulty(value);
  safeSetLocalStorage(QUIZ_DIFFICULTY_KEY, quizDifficulty, 'quiz difficulty preference');
  var sel = document.getElementById('quiz-difficulty-select');
  if (sel) sel.value = quizDifficulty;
  updateProfileSettingsSummary();
}
function populateQuizDifficultySelect() {
  var sel = document.getElementById('quiz-difficulty-select');
  if (!sel) return;
  sel.innerHTML = QUIZ_DIFFICULTY_OPTIONS.map(function(opt){
    return '<option value="'+opt.id+'">'+opt.label+'</option>';
  }).join('');
  var saved = null;
  try { saved = localStorage.getItem(QUIZ_DIFFICULTY_KEY); } catch(e) {}
  applyQuizDifficulty(saved || 'hard');
}
function onQuizDifficultyChange(value) {
  applyQuizDifficulty(value);
  if (document.getElementById('options-menu')?.classList.contains('open')) positionOptionsMenu();
}
function rewriteBibleGatewayUrl(url) {
  var version = normalizeBibleVersion(bibleGatewayVersion);
  if (!url || version === 'NRSVUE') return url;
  try {
    var parsed = new URL(url, window.location.href);
    if (!/(^|\.)biblegateway\.com$/i.test(parsed.hostname)) return url;
    if (!parsed.searchParams.has('version') && !/\/passage\//i.test(parsed.pathname)) return url;
    parsed.searchParams.set('version', version);
    return parsed.toString();
  } catch(e) {
    return String(url).replace(/([?&]version=)[^&#]*/i, '$1'+encodeURIComponent(version));
  }
}
function ensureOptionsMenuPortal() {
  var menu = document.getElementById('options-menu');
  if (menu && menu.parentElement !== document.body) document.body.appendChild(menu);
}
function positionOptionsMenu() {
  ensureOptionsMenuPortal();
  var menu = document.getElementById('options-menu');
  var cog = document.getElementById('options-cog');
  if (!menu || !cog) return;
  var rect = cog.getBoundingClientRect();
  var width = Math.min(306, Math.max(220, window.innerWidth - 28));
  var left = Math.max(14, Math.min(window.innerWidth - width - 14, rect.right - width));
  var top = rect.bottom + 8;
  var maxHeight = Math.max(260, window.innerHeight - top - 16);
  if (maxHeight < 340) {
    top = 14;
    maxHeight = Math.max(260, window.innerHeight - 28);
  }
  menu.style.position = 'fixed';
  menu.style.top = top + 'px';
  menu.style.left = left + 'px';
  menu.style.right = 'auto';
  menu.style.width = width + 'px';
  menu.style.maxHeight = maxHeight + 'px';
}
function openOptionsMenu(ev) {
  if (ev && ev.stopPropagation) ev.stopPropagation();
  var menu = document.getElementById('options-menu');
  var cog = document.getElementById('options-cog');
  if (!menu || !cog) return;
  positionOptionsMenu();
  menu.classList.add('open');
  updateAudioFeedbackControls();
  updateOptionsMenuTriggerState(true);
}
function toggleOptionsMenu(ev) {
  if (ev && ev.stopPropagation) ev.stopPropagation();
  var menu = document.getElementById('options-menu');
  if (!menu) return;
  if (menu.classList.contains('open')) closeOptionsMenu();
  else openOptionsMenu(ev);
}
function openProfileSettingsMenu(ev) {
  openOptionsMenu(ev);
}
function updateOptionsMenuTriggerState(open) {
  var cog = document.getElementById('options-cog');
  var summary = document.getElementById('profile-settings-summary');
  if (cog) {
    cog.setAttribute('aria-expanded', open ? 'true' : 'false');
    cog.setAttribute('aria-label', open ? 'Close app settings' : 'Open app settings');
    cog.setAttribute('title', open ? 'Close app settings' : 'Open app settings');
  }
  if (summary) summary.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function closeOptionsMenu() {
  var menu = document.getElementById('options-menu');
  if (menu) menu.classList.remove('open');
  updateOptionsMenuTriggerState(false);
}
document.addEventListener('click', function(ev){
  var wrap = document.getElementById('header-options');
  var menu = document.getElementById('options-menu');
  if (!wrap) return;
  if (!wrap.contains(ev.target) && !(menu && menu.contains(ev.target))) closeOptionsMenu();
});
document.addEventListener('click', function(ev){
  var link = ev.target && ev.target.closest ? ev.target.closest('a[href]') : null;
  if (!link) return;
  var href = link.getAttribute('href');
  var rewritten = rewriteBibleGatewayUrl(href);
  if (rewritten && rewritten !== href) link.setAttribute('href', rewritten);
}, true);
document.addEventListener('keydown', function(ev){ if (ev.key === 'Escape') closeOptionsMenu(); });
window.addEventListener('resize', function(){
  var menu = document.getElementById('options-menu');
  if (menu && menu.classList.contains('open')) positionOptionsMenu();
});

