function loadStyleLabData() {
  try {
    var raw = localStorage.getItem(STYLE_LAB_KEY);
    var parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch(e) {
    return {};
  }
}
